(window.GIM_TS=window.GIM_TS||{})["Yevamot.4"]={"from":96,"a":[["\u0003אלו שני דורות,\u0004 השנים שנקצבות לו לאדם לחיות בדורו. אם \u0003זכה — משלימין לו\u0004 וחי כל מספר שנותיו, \u0003לא זכה — פוחתין לו\u0004 ממספר השנים שנקצב לו. אלו \u0003דברי ר' עקיבא. וחכמים אומרים:\u0004 אם \u0003זכה — מוסיפים לו\u0004 על שנותיו הקצובות, \u0003לא זכה — פוחתין לו.\u0004 \u0003אמרו לו לר' עקיבא, הרי הוא אומר\u0004 כשחלה חזקיה: \u0003\"והספתי על ימיך חמש עשרה שנה\"\u0004 (מלכים ב' כ, ו), משמע שמוסיפים לאדם על שנותיו הקצובות! \u0003אמר להם: משלו הוסיפו לו.\u0004 כלומר, שנים אלה מיועדות היו לו מתחילה, ולא נוסף לו דבר. \u0003תדע\u0004 שכך הוא, שמתחילה כך נגזר עליו, \u0003שהרי נביא עומד ומתנבא\u0004 בזמן ירבעם \u0003\"הנה בן נולד לבית דוד יאשיהו שמו\"\u0004 (מלכים א' יג, ב), \u0003ו\u0004באותה שעה שחלה חזקיה \u0003עדיין לא נולד מנשה\u0004 בנו של חזקיה, ויאשיהו היה נכדו של מנשה, ואם כן נמצא שמראש כבר נגזר שיחיה ויוליד בן זה!","","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה אומרים הם על כך — \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 שיאשיהו יהיה \u0003מחזקיה?\u0004 רק \u0003\"לבית דוד\" כתיב\u0004 \u0005[נאמר]\u0006 שם, \u0003אי\u0004 \u0005[או]\u0006 ש\u0003מחזקיה נולד\u0004 הבן הזה, מלך ישראל שבו תתקיים הנבואה, \u0003אי מאינש אחרינא\u0004 \u0005[או מאיש אחר],\u0006 מבית דוד, שיוליד אותו. ואם כן אין משם ראיה.","שנינו במשנה: \u0003אשתו שמתה\u0004 אחרי נישואיה — מותר באחותה, וכן \u0003יבמתו שמתה\u0004 — מותר באחותה. \u0003אמר רב יוסף: כאן שנה רבי משנה שאינה צריכה,\u0004 שהמקרים השונים שנתפרטו במשנה אינם צריכים ואין בהם חידוש, שהדבר מפורש בתורה שלא נאסרה אחות אשה אלא בחיי אשתו (\"ואשה אל אחותה לא תקח לצרור לגלות ערוותה עליה בחייה\". ויקרא יח, יח), בין שהאחות פנויה, גרושה או נשואה, וכן ביבמתו.","","\u0003רבן גמליאל אומר: אין גט אחר גט\u0004 ביבמה, כלומר, אם ניתן גט ליבמה, אין גט שניתן לצרתה (או גט שנותן אח אחר לאותה יבמה) נחשב כלל לענין האיסור לשאת את קרובותיה, \u0003ולא מאמר\u0004 תופס \u0003אחר מאמר,\u0004 בין של יבם אחד בשתי יבמות, בין של שני יבמים ביבמה אחת, \u0003ולא בעילה\u0004 תופסת \u0003אחר בעילה\u0004 ביבמה שניה, \u0003ולא חליצה אחר חליצה. וחכמים אומרים: יש גט אחר גט, ויש מאמר אחר מאמר. אבל לא אחר בעילה ולא אחר חליצה כלום,\u0004 שאם בא היבם על היבמה, או שחלץ לה, שוב אין פעולה אחרת תופסת, לא ביבמתה ולא במה שעושה בה היבם האחר.","ומבארים \u0003כיצד\u0004 הם הדינים הללו לפרטיהם: \u0003עשה מאמר ביבמתו\u0004 שקידש אותה \u0003ונתן לה\u0004 אחר כך \u0003גט —\u0004 אף על פי כן \u0003צריכה הימנו חליצה,\u0004 שהגט לא פטר אותה לחלוטין ועדיין זיקת הייבום קיימת. ואם \u0003עשה\u0004 בה \u0003מאמר וחליצה — צריכה הימנו גט\u0004 כדי לפטור אותה מן המאמר. \u0003עשה מאמר ובעל — הרי זו כמצותה,\u0004 שכך תיקנו חכמים שיעשו.","\u0003נתן\u0004 לה \u0003גט ו\u0004אחר כך \u0003עשה\u0004 בה \u0003מאמר — צריכה גט\u0004 נוסף למאמר זה, ועדיין צריכה גם \u0003חליצה\u0004 כדי לפטור אותה מן הייבום. אם \u0003נתן\u0004 לה \u0003גט ובעל — צריכה גט\u0004 לבעילתו (שכיון שנתן לה גט נאסרה עליו) \u0003וחליצה\u0004 לפטור זיקת הייבום. \u0003נתן\u0004 לה \u0003גט וחלץ — אין אחר חליצה כלום,\u0004 שכבר פקעה הזיקה לגמרי. וכן אם \u0003חלץ ו\u0004אחר כך \u0003עשה\u0004 בה \u0003מאמר,\u0004 או \u0003נתן גט ובעל, או בעל ועשה מאמר,\u0004 או \u0003נתן גט וחלץ\u0004 אחרי הבעילה — \u0003אין אחר חליצה\u0004 ובעילה \u0003כלום,\u0004 שאף שעשה מעשה אחריה אין זה שייך לזיקת יבמים.",""],["\u0003אחת\u0004 (בין שמדובר) ב\u0003יבמה אחת ליבם אחד, ואחת\u0004 (ובין שמדובר) ב\u0003שתי יבמות ליבם אחד. כיצד? עשה מאמר בזו ומאמר בזו\u0004 (בצרתה) — \u0003צריכות שני גיטין,\u0004 גט לכל אחת לפוטרן מן המאמר, \u0003וחליצה\u0004 לאחת מהן כדי להפקיע את הזיקה משתיהן. עשה \u0003מאמר בזו ו\u0004נתן \u0003גט לזו — צריכה גט\u0004 לבטל את המאמר, \u0003וחליצה\u0004 לאחת מהן כדי להפקיע את הזיקה. עשה \u0003מאמר בזו ובעל את זו — צריכות שני גיטין וחליצה\u0004 לאחת מהן. \u0003מאמר בזו וחלץ לזו, הראשונה\u0004 בעלת המאמר \u0003צריכה גט\u0004 לפוטרה מן המאמר.","\u0003גט לזו וגט לזו — צריכות הימנו חליצה. גט לזו ובעל את זו — צריכה,\u0004 זו שבעל, \u0003גט וחליצה. גט לזו ומאמר בזו — צריכה\u0004 בעלת המאמר \u0003גט, וחליצה\u0004 לאחת מהן. \u0003גט לזו וחלץ לזו — אין אחר חליצה כלום,\u0004 ולא יוכל לקדש את צרתה.","\u0003חלץ\u0004 לזו \u0003וחלץ\u0004 לזו, \u0003או חלץ\u0004 לאחת \u0003ועשה מאמר\u0004 בשניה, או \u0003נתן גט\u0004 לאחת \u0003ובעל\u0004 את השניה, \u0003או בעל\u0004 אחת \u0003ובעל\u0004 גם את השניה, \u0003או בעל\u0004 אחת \u0003ועשה מאמר\u0004 בשניה, או \u0003נתן גט\u0004 לשניה, או \u0003חלץ — אין אחר חליצה\u0004 ובעילה שקדמו \u0003כלום,\u0004 וכל הדינים האלה הם \u0003בין יבם אחד לשתי יבמות, בין שני יבמין ליבמה אחת.\u0004","\u0003חלץ ועשה מאמר, נתן גט ובעל, או בעל ועשה מאמר, ונתן גט וחלץ — אין אחר חליצה כלום, בין\u0004 שהיתה חליצה \u0003בתחלה, בין באמצע, בין בסוף.\u0004 וכל אלה — לשיטת ר' עקיבא, שכיוון שיש איסור לאו על היבמה לאחר חליצה שוב אין קידושין תופסים בה.","\u0003והבעילה, בזמן שהיא בתחלה,\u0004 שהיתה מעשה ראשון שעשה היבם ביבמתו — \u0003אין אחריה כלום,\u0004 שכל מה שנעשה אחר כך בטל, אבל אם היתה \u0003באמצע ו\u0004כן \u0003בסוף,\u0004 שקודם נעשה מעשה אחר הפוגם את תוקפה — \u0003יש אחריה כלום. ר' נחמיה אומר: אחת בעילה ואחת חליצה, בין בתחלה בין באמצע בין בסוף — אין אחריה כלום,\u0004 שאם עשה מעשה שיש לו תוקף מן התורה — אין עוד משמעות הלכתית למעשה אחר שנעשה אחר כך.","\u0003עד כאן לא פליגי\u0004 \u0005[נחלקו]\u0006 חכמים ורבן גמליאל \u0003אלא בגט אחר גט, ומאמר אחר מאמר, אבל גט אחד ביבמה\u0004 אחת, \u0003ו\u0004כן \u0003מאמר אחד ביבמה מהני\u0004 \u0005[מועיל],\u0006 שאחרי הגט שוב אינו רשאי לייבם, והמאמר יש לו תוקף, שצריך לתת גט, ולא די בחליצה.","ומסבירים: \u0003מאי טעמא אמור רבנן\u0004 \u0005[מה טעם אמרו חכמים]\u0006 ש\u0003גט ביבמה מהני\u0004 \u0005[מועיל]\u0006 אף שאינה אשתו — \u0003משום דמהני בעלמא\u0004 \u0005[ש\u0006הוא \u0005מועיל בכלל]\u0006 באשת איש. \u0003דאי אמרת לא מהני\u0004 \u0005[שאם אומר אתה\u0006 ש\u0005לא יועיל]\u0006 ביבמה ולא ייחשב, \u0003אמרי\u0004 \u0005[אומרים],\u0006 עלולים אנשים לומר בטעות: \u0003גט\u0004 לאשה בא \u0003להוציאה\u0004 מבעלה, \u0003וחליצה\u0004 באה \u0003להוציאה\u0004 מן היבם, \u0003ומ\u0004כיון שה\u0003גט לא מהני\u0004 \u0005[מועיל]\u0006 ואינו נחשב כלל ביבמה זו, אף \u0003חליצה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא מהני\u0004 \u0005[מועילה],\u0006 שאין לחליצה תוקף מוחלט לנתק לגמרי את הקשר ביניהם, \u0003ואתי למיבעל\u0004 \u0005[ויבוא לבעול]\u0006 \u0003אחר חליצה\u0004 והיא אסורה לו מן התורה (משום \"לא יבנה\").","\u0003ומאי טעמא אמור רבנן\u0004 \u0005[ומה טעם אמרו חכמים]\u0006 ש\u0003מאמר ביבמה מהני\u0004 \u0005[מועיל]\u0006 — \u0003משום דמהני בעלמא\u0004 \u0005[שמועיל בכלל]\u0006 שגם המאמר הוא מעשה קידושין, ונראה כקידושין באשה אחרת. \u0003דאי אמרת\u0004 \u0005[שאם אומר אתה]\u0006 שהמאמר \u0003לא מהני\u0004 \u0005[מועיל],\u0006 \u0003אמרי\u0004 \u0005[אומרים],\u0006 יאמרו אנשים: \u0003מאמר\u0004 בא \u0003לקנות\u0004 אשה \u0003וביאה לקנות,\u0004 שגם בביאה אפשר לקדש אשה. \u0003ומ\u0004כיון שה\u0003מאמר לא מהני\u0004 \u0005[מועיל]\u0006 ביבמה לקנותה, \u0003ביאה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא מהניא\u0004 \u0005[מועילה]\u0006 לקנות את היבמה קנין גמור \u0003ואתי למיבעל\u0004 \u0005[ויבוא לבעול]\u0006 \u0003אחר ביאה\u0004 של יבמה אחת גם את צרתה.","\u0003ומאי טעמא אמור רבנן\u0004 \u0005[ומה טעם אמרו חכמים]\u0006 (החלוקים על ר' נחמיה) ש\u0003ביאה פסולה\u0004 שנעשתה אחר מעשה שיש בו קנין כלשהו בצרתה איננה קונה קנין גמור ו\u0003יש אחריה כלום,\u0004 שנשארת עדיין זיקת ייבום, ומעשה שנעשה אחריה ביבמה מועיל — כי","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 היתה פסולה משום ש\u0003ביאה אחר הגט היא — גזירה ביאה אחר הגט משום ביאה אחר חליצה,\u0004 שהיא אסורה מן התורה ולכן תיקנו שביאה פסולה כזו לא תיחשב כמנתקת את זיקת הייבום לגמרי. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003ביאה אחר מאמר היא — גזירה ביאה אחר מאמר, משום ביאה\u0004 ביבמה שניה \u0003אחר ביאה\u0004 בראשונה.","\u0003ומאי טעמא אמור רבנן\u0004 \u0005[ומה טעם אמרו חכמים]\u0006 \u0003האי\u0004 \u0005[זו]\u0006 \u0003חליצה פסולה אין אחריה כלום\u0004 כי \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 יש\u0005]\u0006 \u0003לגזור\u0004 בדבר זה? אם \u0003נגזור חליצה אחר הגט משום חליצה אחר חליצה\u0004 הלא אין פגם בחליצה אחר חליצה — \u0003כל כי הני\u0004 \u0005[כמו כל אלה]\u0006 \u0003תחלוץ ותיזיל\u0004 \u0005[ותלך],\u0006 כלומר, אף אם תחלוץ שלא לצורך, אין עבירה בכך ולא עשתה דבר.","ואם תאמר \u0003ליגזור\u0004 (נגזור) ב\u0003חליצה אחר מאמר משום חליצה אחר ביאה,\u0004 שיאמרו שאחר ביאה לא צריך גט אם חלץ לה, כמו בחליצה אחר מאמר, \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003חליצה אחר מאמר מי לא בעיא\u0004 \u0005[האם אינה צריכה]\u0006 על כל פנים \u0003גט למאמרו?\u0004 ומכיון שכן, \u0003חליצה אחר ביאה נמי בעיא\u0004 \u0005[גם כן צריכה]\u0006 \u0003גט לביאתו\u0004 ואם כן מה שעושים בחליצה אחר מאמר מועיל גם לחליצה אחר ביאה, ואין לגזור יותר.","\u0003אמר רבא:\u0004"],["\u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבן גמליאל\u0004 שאמר אין גט אחר גט — \u0003דמספקא ליה\u0004 \u0005[שמסופק לו]\u0006 בענין \u0003גט\u0004 שניתן ליבמה \u0003אי דחי אי לא דחי\u0004 \u0005[אם דוחה או לא דוחה]\u0006 לגמרי. וכן מסופק לו לגבי ה\u0003מאמר אי קני אי לא קני\u0004 \u0005[אם קונה או לא קונה].\u0006 ומפרשים: \u0003גט, אי דחי אי לא דחי\u0004 \u0005[אם דוחה או לא דוחה],\u0006 ומכל מקום \u0003אי קמא דחי\u0004 \u0005[אם\u0006 הגט \u0005הראשון דוחה] —\u0006 \u0003בתרא מאי קעביד\u0004 \u0005[האחרון,\u0006 השני, \u0005מה הוא עושה],\u0006 ולכן אין בו ממש. וכן \u0003אי קמא לא דחי\u0004 \u0005[אם\u0006 הגט \u0005הראשון אינו דוחה] —\u0006 \u0003בתרא נמי לא דחי\u0004 \u0005[האחרון גם כן אינו דוחה],\u0006 ולכן בכל מקרה גט אחר גט אין בו ולא כלום.","וכיוצא בו \u0003מאמר אי קני אי לא קני\u0004 \u0005[אם קונה או לא קונה],\u0006 \u0003אי קמא קני\u0004 \u0005[אם\u0006 המאמר \u0005הראשון קונה]\u0006 — \u0003בתרא מאי קעביד\u0004 \u0005[האחרון,\u0006 השני, \u0005מה\u0006 הוא \u0005עושה],\u0006 \u0003ואי קמא לא קני\u0004 \u0005[ואם הראשון אינו קונה] —\u0006 \u0003בתרא נמי לא קני\u0004 \u0005[האחרון גם כן אינו קונה],\u0006 ולכן אין גט אחר גט ואין מאמר אחר מאמר.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 ממה ששנינו בברייתא: \u0003ומודה רבן גמליאל שיש גט אחר מאמר,\u0004 שעשה מאמר ביבמה אחת ונתן לשניה גט, \u0003ו\u0004כן מודה שיש \u0003מאמר אחר הגט,\u0004 שנתן ליבמה אחת גט ועשה בשניה מאמר. \u0003ו\u0004כן מודה שיש \u0003גט אחר ביאה ומאמר,\u0004 כגון שבא על יבמה אחת, ועשה מאמר בשניה, ונתן גט לשלישית, \u0003ומאמר אחר ביאה וגט.\u0004","ומעתה, \u0003ואי מספקא ליה\u0004 \u0005[ואם מסופק לו]\u0006 \u0003לרבן גמליאל\u0004 מה כוחו של המאמר, אם נאמר שמאמר קונה — לא תועיל ביאה כלל, ואם המאמר אינו קונה כלל, \u0003תהוי\u0004 \u0005[תהיה]\u0006 ביאה זו שאחרי המאמר \u0003כביאה\u0004 שמ \u0003לכתחלה, ו\u0004הביאה הזאת \u0003תקני\u0004 \u0005[תקנה]\u0006 ביבמה זו קנין גמור, ולא יהא ערך לגט שנתן אחר כך לצרתה, \u0003דהא תנן\u0004 \u0005[שהרי שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003הבעילה, בזמן שהיא בתחלה — אין אחריה כלום\u0004 ולכן לא היה צריך להורות כהלכה זו.","\u0003אלא אמר אביי\u0004 ודאי יש לרבן גמליאל דעה משלו לגבי תוקף המאמר, ו\u0003לעולם\u0004 תפרש כך: \u0003פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 \u0003לרבן גמליאל בגט דדחי\u0004 \u0005[ש\u0006הוא \u0005דוחה]\u0006 \u0003ו\u0004ב\u0003מאמר דקני\u0004 \u0005[ש\u0006הוא \u0005קונה].\u0006 \u0003מיהו, אמור רבנן\u0004 \u0005[\u0006ו\u0005מכל מקום אמרו חכמים]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ה\u0003יבמה, בחד צד מהני\u0004 \u0005[בצד אחד מועיל]\u0006 \u0003בה\u0004 ה\u0003גט, ובחד צד מהני\u0004 \u0005[ובצד אחד מועיל]\u0006 \u0003בה\u0004 ה\u0003מאמר,\u0004 אבל אין אחיזתם ותפיסתם בה באותו אופן. ולכן, \u0003גט אחר גט לא דחי\u0004 \u0005[אינו דוחה]\u0006 \u0003דהא דחה ליה קמא\u0004 \u0005[שהרי דחה לו\u0006 הגט \u0005הראשון]\u0006 כל מה שאפשר לדחות בגט. \u0003ומאמר אחר מאמר לא קני\u0004 \u0005[קונה]\u0006 \u0003דהא קני ליה קמא\u0004 \u0005[שהרי קנה לו\u0006 המאמר \u0005הראשון].\u0006 ואילו \u0003גט אחר מאמר ומאמר אחר הגט, האי מילתא קא דחי והאי מילתא קא קני\u0004 \u0005[דבר זה דוחה ודבר זה קונה],\u0006 שכיון שאין הקנייה במאמר והדחייה בגט באותו אופן, הרי יש כאן גם קנין וגם דחייה, ולכן מועילים הם ותופסים בזה אחר זה.","\u0003ו\u0004אילו \u0003רבנן\u0004 \u0005[חכמים]\u0006 סבורים: \u0003כל חד וחד תקינו ליה רבנן\u0004 \u0005[אחד ואחד\u0006 מהיבמים \u0005תיקנו לו חכמים]\u0006 גם דחיית \u0003גט ו\u0004גם תפיסת \u0003מאמר ביבמה,\u0004 ותיקנו שיהו אלה תופסים בכל אחת מן היבמות. ולכן ככוחו של גט ראשון, כוחו של גט שני.","ועוד מסביר הוא את המשך דברי רבן גמליאל בברייתא, \u0003והאי\u0004 \u0005[וזו]\u0006 \u0003ביאה פסולה,\u0004 ביאה שהיה בה פסול, שנעשתה שלא כראוי (כגון שנעשתה אחר הגט) — \u0003עדיפא\u0004 \u0005[עדיפה]\u0006 \u0003ממאמר וגריעא\u0004 \u0005[ו\u0006גם \u0005גרועה]\u0006 \u0003ממאמר: עדיפא\u0004 היא \u0003ממאמר\u0004 בצד מסויים, ש\u0003אילו מאמר אחר מאמר לא מהני\u0004 \u0005[מועיל]\u0006 כלל לדעת רבן גמליאל, \u0003ואילו ביאה אחר מאמר מהני\u0004 \u0005[מועילה],\u0006 שהרי היא קנין מן התורה. \u0003וגריעא\u0004 \u0005[וגרועה]\u0006 \u0003ממאמר,\u0004 ש\u0003אילו מאמר אחר הגט\u0004 לדעת רבן גמליאל \u0003קני לכוליה שיורא\u0004 \u0005[קונה את כל שיורו]\u0006 של ה\u0003גט\u0004 שבאותו צד שבו לא דחה הגט דחייה גמורה קונה המאמר, ומאמר זה תופס. \u0003ואילו ביאה אחר הגט לא קניא ליה לכוליה שיורא\u0004 \u0005[אינה קונה את כל שיורו]\u0006 של ה\u0003גט\u0004 ומועיל מאמר אחריה, ואינה כביאה כשרה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כיצד\u0004 (באיזה אופן) \u0003אמר רבן גמליאל אין גט אחר גט?\u0004 — \u0003שתי יבמות שנפלו לפני יבם אחד, ונתן גט לזו וגט לזו. רבן גמליאל אומר: חולץ לראשונה, ואסור בקרובותיה,\u0004 שהרי היא חלוצתו, \u0003ומותר\u0004 לגמרי \u0003בקרובות\u0004 ה\u0003שניה,\u0004 משום שהגט שנתן לשניה אינו נחשב כלל, והרי היא רק צרת חלוצתו, ולכן מותר בקרובותיה.","\u0003וחכמים אומרים: נתן גט לזו וגט לזו — אסור בקרובות שתיהן, וחליצה\u0004 עושה \u0003לאחת מהן. וכן אתה אומר בשני יבמים ויבמה אחת,\u0004 שאם נתנו לה שני היבמים גט בזה אחר זה, לרבן גמליאל הגט של היבם השני אינו נחשב כלל, והוא מותר בקרובותיה. ולדעת חכמים הגט הועיל במשהו, ולכן הוא נאסר בקרובותיה.","\u0003כיצד\u0004 (באיזה אופן) \u0003אמר רבן גמליאל אין מאמר אחר מאמר?\u0004 — \u0003שתי יבמות שנפלו לפני יבם אחד, ועשה מאמר בזו ומאמר בזו, רבן גמליאל אומר: נותן גט לראשונה וחולץ לה, ואסור בקרובותיה, ומותר בקרובות\u0004 ה\u0003שניה,\u0004 שכן המאמר שעשה בצרה אינו נחשב. \u0003וחכמים אומרים: נותן גט לשתיהן,\u0004 משום שהמאמר נחשב לגבי שתיהן, \u0003ואסור בקרובות שתיהן, וחליצה\u0004 עושה \u0003לאחת מהן. וכן אתה אומר בשני יבמים ויבמה אחת,\u0004 שאם עשה בה הראשון מאמר, ואחר כך עשה בה השני מאמר — שניהם צריכים לתת גט, ושניהם אסורים בקרובותיה.","ומבררים: \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003נותן גט לזו וגט לזו, רבן גמליאל אומר: חולץ לראשונה ואסור בקרובותיה, ומותר בקרובות שניה.\u0004 ושואלים: \u0003לימא תיהוי תיובתא\u0004 \u0005[\u0006האם \u0005נאמר\u0006 ש\u0005תהא זו קושיה חמורה]\u0006 ל\u0003שמואל,\u0004 ש\u0003אמר שמואל:\u0004 אם \u0003חלץ לבעלת הגט,\u0004 ליבמה שקודם לכן נתן לה גט — \u0003לא נפטרה צרה\u0004 על ידי חליצה זו, שלא היתה זו חליצה כשרה. ולכן צריך לחזור ולחלוץ גם לצרה. ואילו בברייתא זו נאמר שחולץ לאחת מהן!","ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003שמואל: כי אמרי אנא\u0004 \u0005[כאשר אמרתי אני]\u0006 מה שאמרתי, הרי זה \u0003אליבא דמאן דאמר\u0004 \u0005[על פי שיטת מי שאומר]\u0006 \u0003יש זיקה,\u0004 וכיון שיש זיקה לשתי היבמות — אין הזיקה פוקעת אלא על ידי חליצה מעולה, וחליצה זו שלאחר הגט אין בכוחה להפקיע לגמרי את זיקתה של הצרה שלא חלצו לה. \u0003ו\u0004אילו \u0003רבן גמליאל סבר\u0004 ש\u0003אין זיקה,\u0004","ולכן די בחליצת אחת כדי לפטור ממילא גם את השניה. \u0003ו\u0004שואלים: אם כן, \u0003מ\u0004אחר ש\u0003רבן גמליאל סבר\u0004 ש\u0003אין זיקה,\u0004"],["\u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 ודאי ש\u0003יש זיקה,\u0004 שמן הסתם חלקו עליו גם בענין זה, \u0003וקתני סיפא\u0004 \u0005[ושנה\u0006 ב\u0005סופה]\u0006 של אותה ברייתא: \u0003וכן אתה אומר בשני יבמין ויבמה אחת,\u0004 שאם נתן לה גם היבם השני גט, היא נפטרת בחליצתו של אחד מהם. אם כן \u0003לימא תיהוי תיובתא\u0004 \u0005[\u0006האם \u0005נאמר\u0006 ש\u0005תהא\u0006 זו \u0005קושיה חמורה]\u0006 על \u0003רבה בר רב הונא אמר רב.\u0004 ש\u0003אמר רבה בר רב הונא אמר רב:\u0004 אם חלץ אחד מן האחים את היבמה \u0003חליצה פסולה — צריכה\u0004 היבמה \u0003לחזור על כל\u0004 שאר \u0003האחין\u0004 עד שיחלוץ לה אחד מהם כדין, משום שהיבמה זקוקה לכל האחים, ואין זיקה נפקעת על ידי חליצה פגומה. ואילו בברייתא נאמר שדי אם אחד מהם חולץ אף שהיתה זו חליצה פסולה, שכן נעשתה לאחר הגט.","ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003רבה בר רב הונא: בין לרבן גמליאל בין לרבנן סברי\u0004 \u0005[סבורים\u0006 הם\u0005]\u0006 ש\u0003אין זיקה,\u0004 ודברי רבה בר רב הונא לפי השיטה שיש זיקה. \u0003והכא\u0004 \u0005[וכאן]\u0006 המחלוקת איננה כלל בענין הזיקה, אלא רק בנושא שנאמר במפורש: \u0003בגט אחר גט ומאמר אחר מאמר קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 אם הוא מועיל או איננו מועיל.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 באותה ברייתא: \u0003עשה מאמר בזו ומאמר בזו, רבן גמליאל אומר: נותן גט לראשונה וחולץ לה, ואסור בקרובותיה, ומותר בקרובות\u0004 ה\u0003שניה.\u0004 ושואלים: \u0003מכדי קסבר\u0004 \u0005[הלא סבור]\u0006 \u0003רבן גמליאל\u0004 כי \u0003אין מאמר אחר מאמר,\u0004 שהמאמר השני אינו נחשב כלל, אם כן \u0003ראשונה נמי\u0004 \u0005[גם כן]\u0006 \u0003תתייבם,\u0004 אם ירצה, ומדוע צריך לחלוץ לה? ומשיבים: \u0003גזירה דלמא אתי לייבומי\u0004 \u0005[שמא יבוא לייבם]\u0006 את ה\u0003שניה,\u0004 והשניה כבר אסורה עליו, שכיון שעשה מאמר בראשונה, נחשבת היא כקנויה לו במידה מסויימת, ואינו יכול עוד לשאת את היבמה האחרת, שהיא מבית אחד.","\u0003אמר ר' יוחנן: רבן גמליאל ובית שמאי ור' שמעון ובן עזאי ור' נחמיה — כולהו סבירא להו\u0004 \u0005[כולם סבורים הם]\u0006 כי \u0003מאמר קונה קנין גמור,\u0004 כמו קידושין רגילים. \u0003רבן גמליאל — הא דאמרן\u0004 \u0005[זו שאמרנו],\u0006 שאין מאמר אחר מאמר, ולדעת ר' יוחנן המאמר השני בטל משום שהמאמר הראשון קנה קנין גמור.","\u0003בית שמאי — דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003שלשה אחין, שנים מהם נשואין לשתי אחיות, ואחד מופנה\u0004 (רווק), \u0003מת אחד מבעלי אחיות, ועשה בה\u0004 (באלמנתו) האח ה\u0003מופנה מאמר, ואחר כך מת אחיו השני\u0004 ונפלה לפניו האחות השניה גם היא לייבום, \u0003בית שמאי אומרים: אשתו,\u0004 כלומר,זו שעשה בה מאמר תשאר \u0003עמו, והלזו,\u0004 האשה השניה, אשת האח האחר שהיא אחותה של בעלת המאמר — \u0003תצא משום אחות אשה.\u0004 הרי שלדעתם המאמר קנה ביבמה הראשונה כקידושין גמורים, שדוחים את אחותה.","\u0003ר' שמעון — דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 בענין יבמה שבא עליה יבם לפני בגרותו בהיותו בן תשע שנים ומעלה, ואחר כך בא עליה אחיו שגם הוא מבן תשע ומעלה, \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' שמעון לחכמים: אם ביאת ראשון\u0004 נחשבת \u0003ביאה —\u0004 אם כן \u0003ביאת שני אינה ביאה\u0004 לפוסלה על הראשון, שכבר קנאה הראשון בביאתו, ו\u0003אם ביאת ראשון אינה ביאה — ביאת שני נמי\u0004 \u0005[גם כן]\u0006 \u0003אינה ביאה. והא\u0004 \u0005[והרי]\u0006 \u0003ביאת בן תשע\u0004 ש\u0003כ\u0004מו \u0003מאמר שויוה רבנן\u0004 \u0005[עשו,\u0006 החשיבו, \u0005אותה חכמים]\u0006 \u0003וקאמר\u0004 \u0005[ואמר]\u0006 \u0003ר' שמעון\u0004 שביאת השני \u0003אינה ביאה,\u0004 משמע שלדעתו ביאת בן תשע שחשובה כמאמר קונה את היבמה, והרי שלדעתו גם אחרי מאמר אין קנין אחר קונה, מאותו טעם.","\u0003בן עזאי — דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003בן עזאי אומר: יש מאמר אחר מאמר בשני יבמין ויבמה אחת, ואין מאמר אחר מאמר בשתי יבמות ויבם אחד.\u0004 שכיון שהוא יבם אחד — קונה אותה מאמרו קנין גמור, ולכן המאמר שעושה ביבמה השניה איננו חל כלל, שכבר קנה מאמר ראשון קנין שלם בראשונה. \u0003ר' נחמיה — דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' נחמיה אומר: אחת בעילה, ואחת חליצה, בין בתחלה בין באמצע בין בסוף — אין אחריה כלום. והא\u0004 \u0005[והרי]\u0006 \u0003ביאה פסולה\u0004 ש\u0003כ\u0004מו \u0003מאמר שויוה רבנן\u0004 \u0005[עשו,\u0006 החשיבו, \u0005אותה חכמים]\u0006 \u0003וקתני\u0004 \u0005[ושנה]:\u0006 \u0003אין אחריה כלום,\u0004 משמע שלדעתו גם אחרי מאמר אין קנין אחר קונה, מאותו טעם.","במשנה, בהתחילה לבאר את הכללים שדובר עליהם קודם, נאמר: \u0003כיצד? עשה מאמר\u0004 ביבמתו ונתן לה גט ו\u0003כו'\u0004"],["ותוהים: וכי \u0003האי\u0004 \u0005[זה]\u0006 \u0003גט אחר גט הוא?\u0004 הרי המשנה מתחילה בנושא של גט אחר גט, וכאן, כשהיא מפרטת, היא מדברת על גט שאחר המאמר! \u0003אמר רב יהודה: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין: \u0003גט אחר הגט, ומאמר אחר מאמר — כדאמרן\u0004 \u0005[כ\u0006מו \u0005שאמרנו]\u0006 ופירשנו בברייתא, אבל ב\u0003יבם אחד ויבמה אחת כיצד התרתן?\u0004 מהי הדרך להתיר את הקשר ההלכתי המורכב שנוצר ביניהם? ומסביר: אם \u0003עשה מאמר ביבמתו ונתן לה גט — צריכה הימנו חליצה.\u0004","שנינו במשנה: \u0003עשה מאמר ובעל — הרי זו כמצותה.\u0004 ומעירים: \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 ש\u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר \u0003לרב הונא,\u0004 ש\u0003אמר רב הונא: מצות יבמה\u0004 לכתחילה ש\u0003מקדש ואחר כך בועל,\u0004 ולא יבעל בלא קידושין. ולכאורה כך גם משתמע מן המשנה. ודוחים: משם אין ראיה גמורה, \u0003אימא\u0004 \u0005[אמור]\u0006 שהכוונה היתה: \u0003אף זה כמצותה,\u0004 שאם עשה בה מאמר ואחר כך בעל — גם זו היא דרך כשרה, אבל לא נאמר במשנה שרק באופן זה מקיימים את המצוה.","ושואלים: אם רק דבר זה רצה לומר — אם כן \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הוא! וכי מדוע נחשוב שעשיית מאמר ביבמה גרעה משהו? ומשיבים: היה צורך לומר זאת, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003כיון\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003העושה מאמר ביבמתו — פרחה\u0004 (נסתלקה) \u0003הימנו זיקת יבמין, וחלה עליו זיקת ארוסין ונשואין,\u0004 וכיון שעשה כך \u0003אימא לאו מצוה קעביד\u0004 \u0005[אמור\u0006 ש\u0005שוב איננו עושה מצוה]\u0006 כאשר הוא מייבם אותה, שהרי כבר אין זיקת ייבום, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שמכל מקום רואים את המאמר והביאה כהמשך אחד, ויש בכך מצוה.","ומוסיפים: \u0003גופא\u0004 \u0005[\u0006ל\u0005גוף\u0006 הדברים\u0005],\u0006 \u0003אמר רב הונא: מצות יבמין — מקדש ואחר כך בועל, ואם בעל ועשה מאמר\u0004 אחר כך — \u0003קנה.\u0004 ותוהים: \u0003אם בעל ועשה מאמר — פשיטא\u0004 \u0005[פשוט]\u0006 שקנה, \u0003דהא קניה\u0004 \u0005[שהרי קנה אותה]\u0006 כבר \u0003בביאה,\u0004 והמאמר אינו מעלה ואינו מוריד! \u0003אלא אימא\u0004 \u0005[אמור],\u0006 תקן כך: \u0003אם בעל\u0004 אשה \u0003בלא מאמר,\u0004 שלא קידש אותה קודם — גם אז \u0003קנה.\u0004","ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שאם בעל בלא מאמר \u0003לוקה!\u0004 ומשיבים: המלקות אינן משום שעבר ולא עשה מאמר, אלא \u0003מכת מרדות\u0004 היא \u0003מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 שמכים אותו על שנהג שלא בדרך צניעות.","שכן \u0003רב מנגיד\u0004 \u0005[\u0006היה \u0005מלקה]\u0006 את כל \u0003מאן\u0004 \u0005[מי]\u0006 שהיה \u0003מקדש\u0004 אשה \u0003בביאה.\u0004 שאף שזו אחת מדרכי הקנין באשה, כיון שהיא דרך פריצות — היה מלקה את מי שעושה כן. \u0003ו\u0004כן היה מלקה את כל \u0003מאן\u0004 \u0005[מי]\u0006 שהיה \u0003מקדש\u0004 אשה \u0003בשוקא\u0004 \u0005[בשוק]\u0006 ולא בבית, שאף היא דרך פריצות. \u0003ו\u0004כן היה מלקה את \u0003מאן\u0004 \u0005[מי]\u0006 שהיה \u0003מקדש\u0004 אשה \u0003בלא שדוכי\u0004 \u0005[שידוכים]\u0006 לפני כן, שאף זה נחשב כפריצות.","\u0003ו\u0004כן היה מלקה את \u0003מאן\u0004 \u0005[מי]\u0006 שהיה \u0003מבטל גיטא\u0004 \u0005[גט]\u0006 שנתן קודם לכן, שמודיע בפני עדים שגט זה בטל, שאף שביטולו מועיל, מכל מקום עבר על דברי חכמים שאסרו לבטל גט, שלא תיכשל אשתו באיסור, שכיון שאינה יודעת על הביטול תינשא לאחר. \u0003ו\u0004כן את \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003מסר מודעא אגיטא\u0004 \u0005[על גט],\u0006 שלפני שנתן את הגט הריהו מוסר בפני שלושה הודעה שהגט שהוא עומד לתת אינו נותנו מרצונו אלא בכפיה, והוא רוצה לבטלו מראש, שאף אז נמצא מכשיל את אשתו הסבורה שזה גט כשר.","\u0003ו\u0004כן את \u0003מאן דפקיר שליחא דרבנן\u0004 \u0005[ו\u0006את \u0005מי שהתחצף\u0006 ב\u0005שליח חכמים]\u0006 אף שהשליח עצמו אינו חכם, כיון שבא בשליחות חכמים — המתחצף כנגדו הריהו כמעליב את החכמים עצמם. \u0003ו\u0004את \u0003מאן דשהי שמתא דרבנן עליה תלתין יומין\u0004 \u0005[מי שהשהה עליו נידוי ש\u0006נידוהו \u0005חכמים\u0006 במשך \u0005שלושים יום]\u0006 \u0003ולא אתי לבי דינא\u0004 \u0005[בא לבית הדין]\u0006 \u0003ו\u0004לא \u0003תבע\u0004 שיבטלו \u0003לשמתיה\u0004 \u0005[את נידויו]\u0006 על ידי שיתקן את מה שחטא ושבגללו הוטל עליו נידוי. שבזה שלא ביקש לבטל את הנידוי הוא מראה שאיננו חושש לגדר זה שגדרו חכמים בנידוי, ולכן ילקוהו.","\u0003ו\u0004כן היה מלקה \u0003על חתנא דדאיר בבי חמוהי\u0004 \u0005[חתן ש\u0006היה \u0005דר בבית חמיו]\u0006 שיש במצב זה חשש של פיתוי לגילוי ערוה בין החתן לחמותו. ושואלים: \u0003דדאיר\u0004 \u0005[\u0006מי \u0005שדר]\u0006 בבית חמיו — \u0003אין\u0004 \u0005[כן]\u0006 היה מלקה אותו, ואולם \u0003דחליף\u0004 \u0005[\u0006מי \u0005ש\u0006רק \u0005חולף]\u0006 ליד בית חמיו לעיתים קרובות — \u0003לא\u0004 היה מלקה? \u0003והא ההוא דחליף אבבא דבי חמוהי ונגדיה\u0004 \u0005[והרי\u0006 מעשה ב\u0005אחד שחלף על פתח בית חמיו והלקהו]\u0006 \u0003רב ששת!\u0004 ומסבירים: שם היתה סיבה מיוחדת לדבר: \u0003ההוא מידם הוה דיים מחמתיה\u0004 \u0005[אותו\u0006 אדם \u0005חשוד על חמותו היה]\u0006 וכיון שעבר סמוך לבית חמותו הלקוהו, משום שהוא מחזק על ידי כך את השמועה הרעה.","\u0003נהרדעי אמרי\u0004 \u0005[\u0006חכמי \u0005נהרדעא\u0006 היו \u0005אומרים]:\u0006 \u0003בכולהו\u0004 \u0005[בכולם]\u0006 \u0003לא מנגיד\u0004 \u0005[\u0006היה \u0005מלקה]\u0006 \u0003רב, אלא ל\u0004זה שהיה \u0003מקדש בביאה ובלא\u0004 לעשות \u0003שדוכי\u0004 \u0005[שידוכים]\u0006 קודם לכן. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שהיה מלקה למקדש בביאה \u0003אפילו בשדוכי נמי\u0004 \u0005[בשידוכים גם כן]\u0006 \u0003משום פריצותא\u0004 \u0005[הפריצות\u0006] שיש בדבר, שהוא מזמין עדים לביאה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 : \u0003כיצד\u0004 דהוא \u0003מאמר? נתן לה כסף או שוה כסף\u0004 ואמר לה: \"הרי את מקודשת לי\", או שקידשה בשטר. ושואלים: \u0003ובשטר כיצד\u0004 דמקדש? על השאלה עצמה תוהים: \u0003בשטר כיצד?! כדאמרן\u0004 \u0005[כ\u0006מו \u0005שאמרנו\u0006] בהלכות כתיבת שטר קידושין לכל אשה: אם \u0003כתב לה על הנייר או על החרס אף על פי שאין בו שוה פרוטה\u0004 (שכן השטר קונה לא מכוח ערכו הממוני, אלא מכוח הכתוב בו): \u0003\"הרי את מקודשת לי\",\u0004 וכמו כן הריהו כותב בשטר קידושי יבמה (\"מאמר\")! \u0003אמר אביי:\u0004 לא על שטר קידושין של יבם שאלו, אלא \u0003הכי קאמר\u0004 \u0005[כך אמר\u0006], כך היתה השאלה: \u0003שטר כתובת יבמין כיצד\u0004 הוא כתוב?","ועל זה משיבים: ש\u0003כתב לה: \"אנא\u0004 \u0005[אני]\u0006 \u0003פלוני בר\u0004 \u0005[בן]\u0006 \u0003פלוני קבילית ית\u0004 \u0005[קיבלתי את]\u0006 \u0003פלונית יבמתי עלי, לזון ולפרנסה כראוי, ובלבד שתהא כתובתה על נכסי בעלה הראשון\".\u0004 ואין אחריות הכתובה על שם היבם, שהרי אמרו שכתובתה היא מנכסי המת. ומעירים: \u0003ואי לית\u0004 \u0005[ואם אין]\u0006 \u0003לה\u0004 אפשרות לגבות \u0003מ\u0004נכסי ה\u0003ראשון,\u0004 שלא היו לו נכסים — \u0003תקינו\u0004 \u0005[תיקנו]\u0006 \u0003לה רבנן\u0004 \u0005[חכמים]\u0006 שתהה כתובתה \u0003מ\u0004ן ה\u0003שני,\u0004 ומאותו טעם שתיקנו כתובה באשה: \u0003כדי שלא תהא קלה בעיניו להוציאה.\u0004 שאם לא יהיה לו בכך הפסד ממון, עלול לגרשה בשל תרעומת כלשהי.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003אביי מרבה: נתן לה\u0004 ליבמה \u0003גט, ואמר\u0004 בנוסח זה: \u0003\"הרי את מגורשת הימני, ואי\u0004 \u0005[ואין]\u0006 \u0003את מותרת לכל אדם\". מהו\u0004 דינו של גט כזה? האם נאמר כי \u0003גט יבמה דרבנן\u0004 \u0005[מדברי חכמים]\u0006 \u0003הוא\u0004 ועשאוהו כגט גמור באשה, ו\u0003גט דמהני\u0004 \u0005[שמועיל]\u0006 \u0003באשת איש — מהני\u0004 \u0005[מועיל]\u0006 גם \u0003ביבמה,\u0004 ו\u0003גט\u0004 ש\u0003לא מהני\u0004 \u0005[מועיל]\u0006 \u0003באשת איש — אף לא מהני\u0004 \u0005[מועיל]\u0006 \u0003ביבמה,\u0004 וכיון שנוסח כזה אין לו תוקף גט כלל באשת איש, גם ביבמה לא ייחשב כלל, \u0003או דלמא אתי לאחלופי בגיטא\u0004 \u0005[שמא יבואו להחליף\u0006 גט זה \u0005בגט\u0006 של ממש\u0005]\u0006 שיאמרו שאף אם נתן לה גט רגיל אין בכך ולא כלום ויכול לשאתה לאחר מכן, ולכך גזרו שידחה את היבמה, ולא יוכל עוד לשאת אותה אף לאחר שנתן לה גט כזה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003חיישינן דלמא אתי לאחלופי בגיטא\u0004 \u0005[חוששים אנו שמא יבואו להחליף\u0006 אותו \u0005בגט\u0006 אחר\u0005]\u0006 ולכן הוא פוסל ביבמה. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבה בר חנן: אלא מעתה\u0004 שאנחנו מחמירים בגט יבמה וחוששים לחילוף, אם \u0003יהיב\u0004 \u0005[נותן]\u0006 \u0003לה ניירא בעלמא\u0004 \u0005[נייר סתם]\u0006 שאין כתוב עליו ענין גירושין — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003פסלה? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 כשנותן לה נייר שאין עליו נוסח גט, אפילו אם יאמר לה \"הרי זה גט\", אין לו תוקף כלל, ו\u0003לא פסיל\u0004 \u0005[פוסל]\u0006 \u0003בכהונה,\u0004 ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 גט כגון זה \u0003קפסיל\u0004 \u0005[פוסל\u0006 על כל פנים\u0005]\u0006 \u0003לכהונה,\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \u0003\"ואשה גרושה מאישה לא יקחו\"\u0004 (ויקרא כא, ז), ולמדו מדיוק הלשון: \u0003אפילו לא נתגרשה אלא מאישה,\u0004 שאמר לה בגט \"הרי את מגורשת ממני ואין את מותרת לכל אדם\" — גם אשה כזו \u0003\"לא יקחו\"\u0004 — אסור להם לשאת. ואשה שקיבלה גט כזה, אף שהגט איננו מועיל להתירה לאחרים כלל, מכל מקום יש בו כדי לפסול אותה לכהן, \u0003והיינו\u0004 \u0005[וזהו]\u0006 הנקרא \u0003\"ריח הגט\" שפוסל בכהונה.\u0004 וכיון שגט בנוסח זה יש לו תוקף כל שהוא, הרי מועיל גט כגון זה גם כדי לפסול את היבמה.","\u0003אמר רמי בר חמא: הרי אמרו\u0004 אם \u0003אמר אחד ללבלר: כתוב\u0004 עכשיו \u0003גט לארוסתי, לכשאכנסנה\u0004 (כאשר אשא אותה) \u0003אגרשנה\u0004 בגט זה. ואמרו, שאם נתן לה גט זה לאחר שכנסה — \u0003הרי זה גט.\u0004 ומדוע — \u0003מפני שבידו לגרשה\u0004 גם בהיותה ארוסה, לכן הגט שהוא כותב בהיותה ארוסה יש לו תוקף."],["\u0003ו\u0004אם כתב ונתן גט \u0003לאשה בעלמא\u0004 \u0005[סתם]\u0006 שאינה קשורה בו כלל, גם אם אחר כך נשא אותה לאשה — \u0003אין\u0004 זה \u0003גט.\u0004 ומדוע — \u0003מפני שאין בידו לגרשה\u0004 בשעה שנכתב הגט, ולכן אין בו ממש. עד כאן דברים ידועים, ועל פיהם \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא:\u0004 אם כתב גט \u0003ליבמתו\u0004 ולא נתן לה, ואחר כך כשכנסה נתנו לה, \u0003מהו?\u0004 האם גט הוא או לא? וצדדי השאלה: \u0003כיון דאגידא ביה\u0004 \u0005[ש\u0006היא \u0005קשורה בו]\u0006 הרי \u0003כארוסתו דמיא\u0004 \u0005[\u0006היא \u0005נחשבת],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003לא עבד\u0004 \u0005[עשה]\u0006 \u0003בה\u0004 עדיין \u0003מאמר לא\u0004 נחשבת אף כארוסה, ואין הגט מועיל? לשאלה זו לא נמצאה תשובה, ומסכמים: \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב חנניה: כתב גט\u0004 ופירש שהוא מנתק בו את \u0003זיקתו\u0004 ליבמתו, \u0003ו\u0004אולם \u0003לא\u0004 את הקשר שביניהם כתוצאה מ\u0003מאמרו\u0004 שעשה בה, וכן אם כתב גט \u0003למאמרו ו\u0004פירש שהוא \u0003לא לזיקתו, מהו\u0004 דינו? האם ה\u0003מאמר עילוי\u0004 \u0005[על]\u0006 ה\u0003זיקה קא רמי\u0004 \u0005[הוא מוטל,\u0006 נסמך\u0005],\u0006 והם נחשבים כקשר אחד מתמשך, \u0003ו\u0004ממילא \u0003הוה ליה\u0004 \u0005[הרי הוא]\u0006 \u0003כמגרש חצי אשה, והמגרש חצי אשה לא עשה ולא כלום, או דלמא\u0004 \u0005[שמא]\u0006 \u0003האי לחודיה קאי והאי לחודיה קאי\u0004 \u0005[זה לעצמו עומד וזה לעצמו עומד]\u0006 ויכול לבטל בגט את הזיקה או את המאמר לבדם.","ושואלים: \u0003ותפשוט ליה\u0004 \u0005[ותפתור לו]\u0006 את הבעיה הזו \u0003מ\u0004דברי \u0003רבא,\u0004 ש\u0003אמר רבא: נתן גט למאמרו — הותרה צרתה,\u0004 שהמאמר שעשה בה בוטל, ונשאר קשר הזיקה במקומו, ולכן צרתה של יבמה זו מותרת עדיין לייבום, משמע שהמאמר והזיקה אינם קשורים זה בזה! ומשיבים: \u0003לרבא פשיטא ליה\u0004 \u0005[\u0006היה \u0005פשוט לו],\u0006 ואולם \u0003לרב חנניה מיבעיא ליה\u0004 \u0005[\u0006היה \u0005מסופק לו],\u0006 ואם כן \u0003מאי\u0004 \u0005[מה\u0006 הוא הדין\u0005]\u0006 בענין זה? וכיון שאין לו הוכחה אחרת ואת דברי רבא שהוא אמורא כמותו אינו מקבל כהוכחה — אין איפוא פתרון לבעיה, ומסכמים: \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","שנינו במשנה: \u0003חלץ ועשה מאמר\u0004 — אין אחר חליצה כלום, ולמאמר זה אין תוקף כלל. \u0003אמר רב יהודה אמר רב: זו דברי ר' עקיבא,\u0004 ש\u0003אמר: אין קדושין תופסין בחייבי לאוין,\u0004 וכיון שחלץ לאשה — הרי היא עליו באיסור של \"לא יבנה\", ולכן אין קידושין תופסים בה. \u0003אבל חכמים אומרים: יש אחר חליצה כלום.\u0004 כי אמנם החלוצה אסורה עליו בלאו, אבל אם מקדש אותה, הקידושין תופסים בה כבשאר חייבי לאוין.","ושואלים: \u0003ומי מצית מוקמת לה\u0004 \u0005[והאם יכול אתה להעמיד,\u0006 להסביר, \u0005אותה\u0006 את משנתנו\u0005]\u0006 \u0003כ\u0004דעת \u0003ר' עקיבא, והא קתני רישא\u0004 \u0005[והרי\u0006 \u0005שנה\u0006 ב\u0005ראשה\u0006 של המשנה\u0005]:\u0006 \u0003נתן גט ועשה מאמר — צריכה גט וחליצה. ואי\u0004 \u0005[ואם]\u0006 דעת \u0003ר' עקיבא\u0004 היא, \u0003כיון דיהב\u0004 \u0005[שנתן]\u0006 \u0003לה גט, מי מהני\u0004 \u0005[האם מועיל]\u0006 \u0003בה מאמר?\u0004","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' עקיבא אומר: מנין לנותן גט ליבמתו שנאסרה עליו עולמית\u0004 ואינו יכול לשאתה שוב לאשה — \u0003שנאמר: \"לא יוכל בעלה הראשון אשר שלחה\u0004 לשוב לקחתה להיות לו לאשה\u0003\"\u0004 (דברים כד, ד), והוא מפרש את המילים המיותרות \"אשר שלחה\" שהכוונה בהם \u0003אחר שילוח,\u0004 שפעמים אפילו אשה שלא נישאה לאחר, אם נתן לה הראשון גט איננו יכול לשאת אותה שוב, ודבר זה הוא ביבמה, שכיון שנתן לה גט נאסרה עליו עולמית.","\u0003אמר רב אשי:\u0004 מכאן אין הוכחה, כי \u0003גט יבמין מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 הוא, \u0003וקרא\u0004 \u0005[והכתוב]\u0006 שהבאנו הוא רק \u0003אסמכתא בעלמא\u0004 \u0005[סמך,\u0006 רמז, \u0005בלבד].\u0006","ומעירים לעצם ההלכה שבענין קידושין אחר חליצה: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003אמר רבי: אין הדברים הללו אמורים אלא לדברי ר' עקיבא, שהיה עושה חלוצה כערוה. אבל חכמים אומרים: יש אחר חליצה כלום. ואני אומר\u0004 לחלק: \u0003אימתי\u0004 יתפסו בה קידושין אחר חליצה — \u0003בזמן שקדשה לשום\u0004 (לשם) \u0003אישות\u0004 בקידושין גמורים כדרך שמקדש אשה סתם ולא במאמר יבמין, \u0003אבל קדשה\u0004 אחר חליצה ופירש שהוא מקדשה \u0003לשום יבמות — אין אחר חליצה כלום.\u0004 שהרי אחר חליצה שוב אין ביניהם זיקת ייבום.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003החולץ ליבמתו וחזר וקדשה, רבי אומר: אם קדשה לשום אישות — צריכה הימנו גט,\u0004 ואם קידשה \u0003לשום יבמות — אין צריכה הימנו גט. וחכמים אומרים: בין שקדשה לשום אישות בין שקדשה לשום יבמות — צריכה הימנו גט,\u0004 שהרי הקידושין תופסים בה.","\u0003אמר רב יוסף: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבי,\u0004 שהמקדש את חלוצתו לשם ייבום לא תפסו בה קידושין, ואם מקדשה סתם, קידושין תופסים בה — כי \u0003עשאוה כ\u0004מו אדם ש\u0003עודר בנכסי הגר\u0004 שמת בלי יורשים, ונכסיו הם עכשיו הפקר, וכל המחזיק בהם זוכה בהם. ואם עודר בנכסי הגר על מנת לזכות בנכסים אלו — קנה, אבל אם היה עודר בנכסי הגר \u0003וכסבור\u0004 בטעות כי האדמות שבהן הוא עודר \u0003שלו הן,\u0004 כיון שלא היתה לו כוונת קנין, אף שעשה מעשה קנין — \u0003דלא קני\u0004 \u0005[שאינו קונה].\u0006 אף כאן, כיון שהוא התכוון לייבום, וזיקת הייבום אינה קיימת עוד — כל המעשה בטל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מי דמי\u0004 \u0005[האם דומה]\u0006 הדוגמא שהבאת לענייננו? \u0003התם לא קא מכוין למיקני\u0004 \u0005[שם,\u0006 בעודר וסבור שזה שלו, \u0005איננו מתכוון לקנות]\u0006 נכסים בזמן שעודר, אבל \u0003הכא קא מכוין למיקני\u0004 \u0005[מתכוון לקנות]\u0006 את האשה! \u0003הא לא דמיא\u0004 \u0005[זה אינו דומה]\u0006 \u0003אלא לעודר בנכסי גר זה\u0004 שמת, \u0003וכסבור של גר אחר הוא, דקני\u0004 \u0005[שקונה],\u0006 אף שלא ידע בדיוק מה הוא קונה. ואף כאן יחול קנין הקידושין למרות טעותו.","\u0003אלא אמר אביי:\u0004 אי אפשר לפרש את מחלוקת רבי וחכמים, אלא \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים],\u0006 \u0003כגון\u0004 ש\u0003אמר לה\u0004 לחלוצה: \u0003התקדשי לי במאמר יבמין. רבי סבר: מאמר עילוי\u0004 \u0005[על]\u0006 \u0003זיקה קא רמי\u0004 \u0005[מוטל,\u0006 נסמך\u0005]\u0006 ואין מקום למאמר אלא במקום שיש זיקה, ומכוח הזיקה, \u0003ו\u0004ממילא \u0003אתאי\u0004 \u0005[באה]\u0006 ה\u0003חליצה אפקעתה\u0004 \u0005[\u0006ו\u0005הפקיעה]\u0006 את ה\u0003זיקה,\u0004 ולכן אין מאמר יבמין קונה עוד בה. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003האי לחודיה קאי והאי לחודיה קאי\u0004 \u0005[זה לבדו עומד וזה לבדו עומד],\u0006 שאף שבטלה הזיקה, מכל מקום הנוסח \"מאמר יבמין\" קונה. וראיה לדבר: \u0003מעיקרא\u0004 \u0005[מתחילה,\u0006 לפני החליצה\u0005]\u0006 \u0003אילו אמר לה \"התקדשי לי במאמר יבמין\" — מי\u0004 \u0005[האם]\u0006 \u0003לא מהני\u0004 \u0005[\u0006היה \u0005מועיל]\u0006 בתורת קידושין, למרות שאין למאמר קשר לזיקה — \u0003השתא נמי מהני\u0004 \u0005[עכשיו גם כן מועיל]\u0006 למרות שהיא חלוצתו.","\u0003רבא אמר: אי\u0004 \u0005[אם]\u0006 ש\u0003אמר לה\u0004 \"התקדשי לי \u0003במאמר יבמין\" — כולי עלמא לא פליגי דמהניא\u0004 \u0005[הכל אינם חלוקים שמועיל]\u0006 והקנין תופס בה. \u0003והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים] —\u0006 \u0003כגון\u0004 ש\u0003אמר לה \"התקדשי לי בזיקת יבמין\".\u0004 וזה ביאור המחלוקת: \u0003רבי סבר\u0004"],["\u0003יש זיקה,\u0004 שהזיקה כשלעצמה יוצרת קשר הלכתי בין היבם והיבמה, והמאמר הוא כנסמך לזיקה. \u0003ו\u0004כאן \u0003אתאי\u0004 \u0005[באה]\u0006 ה\u0003חליצה אפקעתיה\u0004 \u0005[\u0006ו\u0005הפקיעה]\u0006 את ה\u0003זיקה,\u0004 ולכן המאמר איננו קונה. \u0003ו\u0004אילו \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 ש\u0003אין זיקה,\u0004 כלומר, הזיקה כשלעצמה אינה יוצרת קשר בין היבם והיבמה, והמאמר קונה בגדר קידושין, ולא בגלל הזיקה. ולכן, \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003אילו אמר לה \"התקדשי לי בזיקת יבמין\" מי\u0004 \u0005[האם]\u0006 \u0003לא מהני\u0004 \u0005[\u0006היה \u0005מועיל]\u0006 אפילו כשאין זיקה, \u0003השתא נמי מהני\u0004 \u0005[עכשיו\u0006 לאחר חליצה הוא \u0005גם כן מועיל].\u0006","\u0003רב שרביא אמר\u0004 הסבר אחר: \u0003ב\u0004שנעשתה באשה \u0003חליצה כשירה, אי\u0004 \u0005[אם]\u0006 ש\u0003אמר לה\u0004 אחר כך \u0003\"התקדשי לי בזיקת יבמין\" — כולי עלמא לא פליגי דלא מהני\u0004 \u0005[הכל אינם חלוקים שאינו מועיל]\u0006 שהרי בטלה הזיקה. \u0003והכא\u0004 \u0005[וכאן],\u0006 \u0003ב\u0004שנעשתה בה \u0003חליצה פסולה, קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 רבי\u0005]\u0006 \u0003סבר\u0004 ש\u0003חליצה פסולה פוטרת,\u0004 וכיון שהיא פוטרת, אף שצריך עוד להשלימה כדי להתירה לשוק, מכל מקום בטלה הזיקה על ידי חליצה זו, ואינה יכולה להתקדש עוד בזיקת יבמין. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 חכמים\u0005]\u0006 \u0003סבר\u0004 ש\u0003חליצה פסולה אינה פוטרת\u0004 פטור גמור, ונמצא קשר הזיקה עומד בעינו ויכולה להתקדש בזיקת יבמין.","\u0003רב אשי אמר: דכולי עלמא\u0004 \u0005[ש\u0006לדעת \u0005הכל]\u0006 \u0003חליצה פסולה אינה פוטרת\u0004 פטור גמור. \u0003והכא\u0004 \u0005[וכאן]\u0006 מדובר באופן שעשה חליצה והתנה שלא תועיל אלא בתנאי מסויים ואותו תנאי לא התקיים, ו\u0003ב\u0004שאלה האם \u0003יש תנאי בחליצה קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005].\u0006 ש\u0003מר\u0004 \u0005[חכם זה,\u0006 חכמים\u0005]\u0006 \u0003סבר\u0004 ש\u0003יש תנאי בחליצה,\u0004 וכיון שבטל התנאי, בטלה החליצה ויכול עוד לקדש בזיקת יבמים. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 רבי\u0005]\u0006 \u0003סבר\u0004 ש\u0003אין תנאי בחליצה,\u0004 ולכן לא התבטלה החליצה, ומאמר אחריה אינו מועיל.","\u0003רבינא אמר: דכולי עלמא\u0004 \u0005[ש\u0006לדעת \u0005הכל]\u0006 \u0003יש תנאי בחליצה, והכא\u0004 \u0005[וכאן]\u0006 \u0003בתנאי כפול קמיפלגי\u0004 \u0005[חלוקים הם] —\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 רבי\u0005]\u0006 \u0003סבר\u0004 כי \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שאותו תנאי יהיה \u0003תנאי כפול,\u0004 שעליו להתנות בפירוש שאם יתקיים התנאי תהא זו חליצה, ואם לא יתקיים — לא תהיה זו חליצה. ואם לא כפל בתנאי גם את צד החיוב וגם את צד השלילה — התנאי אינו חל, וכיון שלא נעשה תנאי כפול תהא זו חליצה ושוב אין כאן זיקה, ולכן אין קידושין תופסים בה בזיקת יבמים. \u0003ומר\u0004 \u0005[וחכם\u0006 זה, חכמים\u0005]\u0006 \u0003סבר\u0004 ש\u0003לא בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיה תנאי זה \u0003תנאי כפול\u0004 ולכן התנאי חל וביטל את החליצה, ונשארה הזיקה במקומה.","שנינו במשנה: \u0003חלץ ועשה מאמר ונתן גט ובעל —\u0004 אין אחר חליצה כלום. ושואלים: \u0003וניתני נמי\u0004 \u0005[ושישנה גם כן]\u0006 \u0003אין אחר ביאה כלום,\u0004 שהרי שנה שם גם מקרה של בעל ועשה מאמר וכו', ואומרים: אכן \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 \u0003תני\u0004 \u0005[שנה]\u0006 \u0003אין אחר ביאה כלום\u0004 וראוי שייכתב הדבר. ושואלים: \u0003ו\u0004ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 מדוע באמת לא שנה זאת? ומסבירים: \u0003התרת יבמה לשוק עדיפא ליה\u0004 \u0005[עדיפה לו],\u0006 כלומר, התנא העדיף דווקא אותם מקרים שבהם היבמה מותרת לשוק.","שנינו במשנה: \u0003אחד יבמה אחת אחד שתי יבמות,\u0004 הדין שווה בכל האופנים אם נעשה מאמר אחר מאמר וכיוצא בהם. ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003בן עזאי. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003בן עזאי אומר: יש מאמר אחר מאמר בשני יבמין ויבמה אחת, ואין מאמר אחר מאמר בשתי יבמות ויבם אחד.\u0004 ואילו התנא במשנתנו איננו מחלק בין זו לזו.","שנינו במשנה: \u0003כיצד\u0004 בשתי יבמות ליבם אחד? — עשה \u0003מאמר לזו\u0004 וחלץ לזו — הראשונה צריכה גט. ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[\u0006האם \u0005לומר\u0006 ש\u0005מסייע לו]\u0006 הדבר \u0003לשמואל,\u0004 ש\u0003אמר שמואל: חלץ לבעלת מאמר — לא נפטרה צרתה\u0004 על ידי חליצה זו, שהיא חליצה פסולה.","\u0003ו\u0004כן תהיה זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על שיטת \u0003רב יוסף\u0004 שחלק על כך, ולדבריו היה יכול לפטור את השניה בחליצת בעלת המאמר, שנפסלה כבר על ידי הגט, ודוחים: \u0003מי קתני\u0004 \u0005[האם שנה]\u0006 \u0003\"חולץ\"\u0004 לאחרת, שאז משמעות הלשון היא שיש לעשות כך מלכתחילה? \u0003\"חלץ\" קתני\u0004 \u0005[שנה],\u0006 משמע \u0003דיעבד,\u0004 ולא שהוא חייב לחלוץ לשניה, ושמא גם אם היה חולץ לראשונה היתה חליצתו חליצה לפטור את השניה, אלא שבמקרה זה אנו עוסקים כשעשה מאמר בזו וחלץ לזו.","שנינו: נתן \u0003גט לזו וגט לזו\u0004 — צריכות הימנו חליצה. ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[\u0006האם \u0005לומר\u0006 ש\u0005מסייע לו]\u0006 הדבר \u0003לרבה בר רב הונא.\u0004 ש\u0003אמר רבה בר רב הונא: חליצה פסולה — צריכה לחזר על כל האחין.\u0004 כלומר, שלא די בחליצה הפסולה האחת. ואף כאן משמע שכל היבמות צריכות חליצה, כיון שלא היתה זו חליצה כשרה. ודוחים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"צריכות\"\u0004 שנאמר פה — כוונתו: \u0003צריכות דעלמא\u0004 \u0005[בכלל]\u0006 שאין לשון הריבוי מתייחסת דווקא ליבמות הנזכרות במשנתנו, אלא לומר שכל היבמות במקרה כזה צריכות חליצה.","עוד שנינו במשנה: \u0003גט לזו וחלץ לזו\u0004 — אין אחר חליצה כלום. ומציעים: ממה שלא נקט באופן שחלץ לבעלת הגט, אלא שחלץ לאחרת, \u0003לימא מסייע ליה\u0004 \u0005[\u0006האם \u0005לומר\u0006 ש\u0005מסייע לו]\u0006 הדבר \u0003לשמואל,\u0004 שזה שעשה בה מעשה, שוב לא יחלוץ לה אלא לצרתה! \u0003ותהוי\u0004 \u0005[ותהיה\u0006 זאת\u0005]\u0006 \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 על\u0005]\u0006 \u0003רב יוסף!\u0004 ודוחים: \u0003מי קתני\u0004 \u0005[האם שנה]\u0006 בלשון הוראה לכתחילה \u0003\"חולץ\"\u0004 לזו? \u0003\"חלץ\" קתני\u0004 \u0005[שנה]\u0006 לשון \u0003דיעבד\u0004 בלבד, שבאותו מקרה עשה כך.","עוד שנינו במשנה: \u0003חלץ וחלץ או חלץ\u0004 ועשה מאמר \u0003וכו'\u0004 — אין אחר חליצה כלום. ושואלים: \u0003וליתני נמי\u0004 \u0005[ושישנה גם כן]\u0006 \u0003אין אחר ביאה כלום!\u0004 ואומרים: אכן, \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 \u0003תני\u0004 \u0005[שנה]\u0006 \u0003אין אחר ביאה כלום.\u0004 ומסבירים: \u0003ו\u0004ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 שלא שנה זאת — \u0003התרת יבמה לשוק עדיפא ליה\u0004 \u0005[עדיפה לו]\u0006 ולכן הזכיר שעשה חליצה.","שנינו במשנה שאין אחר חליצה כלום, ואין המאמר תופס בה \u0003בין יבם אחד לשתי יבמות,\u0004 בין שני יבמים ליבמה אחת. ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003ר' יוחנן,\u0004 ש\u0003אמר:\u0004 לאחר שחלץ אדם ליבמתו \u0003כולה ביתא בלאו קאי\u0004 \u0005[כל הבית\u0006 נשי אחיו, \u0005ב\u0006איסור \u0005לא תעשה עומד\u0006 עליו\u0005],\u0006 שגם זו שחלץ לה וגם צרותיה אסורות עליו רק באיסור לאו (\"לא יבנה\") לאחר חליצה, ושוב אין בהן איסור כרת של אשת אח, משום כך \u0003איצטריך לאשמועינן\u0004 \u0005[צריך היה להשמיע לנו]\u0006 ש\u0003אין קדושין תופסין\u0004 בצרת החלוצה אף שהיא \u0003ב\u0004כלל \u0003חייבי לאוין,\u0004 וזה כדעת ר' עקיבא.","\u0003אלא ל\u0004דעת \u0003ריש לקיש\u0004 ש\u0003אמר: כולה ביתא\u0004 \u0005[כל הבית\u0006 הזה\u0005]\u0006 \u0003ב\u0004איסור \u0003כרת קאי\u0004 \u0005[עומד]\u0006 עכשיו, שכיון שחלץ שוב אין בטל היתר הייבום, וחוזר איסור אשת אח, האם \u0003איצטריך לאשמועינן\u0004 \u0005[\u0006היה \u0005צריך להשמיענו]\u0006 ש\u0003אין קדושין תופסין בחייבי כריתות,\u0004 והלא הוא דבר ידוע לכל!","\u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003ריש לקיש: וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה רוצה לדייק ממה שהמשנה אומרת לנו דין שהוא לכאורה פשוט, \u0003סיפא דקתני\u0004 \u0005[\u0006ב\u0005סופה\u0006 של אותה משנה \u0005ששנה\u0006 בה\u0005]\u0006 \u0003בעל ועשה\u0004 בה יבם אחר \u0003מאמר\u0004 אין במאמר כלום — וכי \u0003איצטריך לאשמועינן\u0004 \u0005[צריך\u0006 היה \u0005להשמיע לנו]\u0006 ש\u0003אין קדושין תופסין באשת איש,\u0004 שהרי לאחר שבעל את היבמה ונעשתה אשתו שוב אין קידושין של אחר תופסים בה?","\u0003אלא\u0004 חייב אתה לומר שלא בכל דברי המשנה כאן יש מן החידוש, והטעם ששנה בדרך זו: \u0003איידי דתנא\u0004 \u0005[מתוך ששנה]\u0006 קודם \u0003התרת יבם אחד ויבמה אחת, תנא נמי\u0004 \u0005[שנה גם כן]\u0006 \u0003שתי יבמות ויבם אחד, ואיידי דתנא\u0004 \u0005[ומתוך ששנה]\u0006 \u0003שתי יבמות ויבם אחד, תנא נמי\u0004 \u0005[שנה גם כן]\u0006 \u0003שני יבמין ויבמה אחת,\u0004 ופירש את כל המקרים למרות שאין בכל אחד מהם חידוש הלכה."],["שנינו במשנה: \u0003חלץ ועשה מאמר, ונתן\u0004 גט ובעל — אין אחר חליצה כלום. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 את המקרה של \u0003חלץ ועשה מאמר, איצטריך\u0004 \u0005[הוצרך]\u0006 להביאו ולומר שאין אחר חליצה כלום, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003נגזור\u0004 ב\u0003מאמר דבתר\u0004 \u0005[שאחר]\u0006 \u0003חליצה אטו\u0004 \u0005[משום]\u0006 \u0003מאמר דקמי\u0004 \u0005[שלפני]\u0006 \u0003חליצה\u0004 ונאמר שמאמר זה יקנה, על כן \u0003קא משמע לן דלא גזרינן\u0004 \u0005[השמיע לנו שאין אנחנו גוזרים].\u0006 \u0003אלא\u0004 אם יבם אחד \u0003חלץ ונתן גט\u0004 לאותה יבמה \u0003למה לי?\u0004 מה החידוש בכך שגט אחר החליצה אינו כלום?","ומשיבים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 שאתה מחפש חידוש בכל קטע \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של משנתנו: אם יבם אחד \u0003בעל ועשה מאמר, בעל ונתן גט\u0004 אינו כלום — אף כאן, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003בעל ונתן גט — איצטריך\u0004 \u0005[הוצרך\u0006 לומר\u0005],\u0006 כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003נגזור גט דבתר\u0004 \u0005[שאחר]\u0006 \u0003בעילה אטו\u0004 \u0005[משום]\u0006 \u0003גט דקמי\u0004 \u0005[שלפני]\u0006 \u0003בעילה\u0004 ושמא לא יועיל לה גט בלבד ותצטרך גם חליצה, על כן \u0003קא משמע לן דלא גזרינן\u0004 \u0005[השמיע לנו שאין אנו גוזרים],\u0006 \u0003אבל בעל ועשה מאמר למה לי?\u0004 הלא מאחר שבעל אותה, נעשתה כאשתו לכל דבר, ומה לי אם עשה מאמר או לא עשה?","\u0003אלא\u0004 חייבים לומר כי \u0003איידי דתנא\u0004 \u0005[מתוך ששנה]\u0006 תחילה ענין \u0003חלץ ועשה מאמר, תנא נמי\u0004 \u0005[שנה גם כן]\u0006 \u0003בעל ועשה מאמר\u0004 משום השוואת הלשון, \u0003ואיידי דבעי למיתני\u0004 \u0005[ומתוך שרצה לשנות]\u0006 \u0003בעל ונתן גט, תנא נמי\u0004 \u0005[שנה גם כן]\u0006 \u0003חלץ ונתן גט.\u0004 ואין איפוא לדייק מן הייתור בנושאים אלה, הנובע מתוך סגנון דברי המשנה.","שנינו במשנה שהבעילה \u0003בזמן שהיא\u0004 בתחילה — אין אחריה כלום, באמצע ובסוף — יש אחריה כלום. ומעירים: \u0003מתניתין דלא כי האי תנא\u0004 \u0005[משנתנו\u0006 היא \u0005שלא כ\u0006שיטת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אבא יוסי בן יוחנן איש ירושלים אומר משום ר' מאיר: אחת בעילה ואחת חליצה,\u0004 אם נעשו \u0003בתחלה — אין אחריה כלום,\u0004 אם נעשו \u0003באמצע ובסוף,\u0004 שכבר עשה מעשה אחר לפניה — \u0003יש אחריה כלום.\u0004 ולפי המשנה אין אחר חליצה כלום אפילו אם נעשתה באמצע ובסוף. \u0003ו\u0004אם כן אפשר לסכם כי \u0003שלש מחלוקת בדבר,\u0004 כלומר, יש שלוש דעות חלוקות בנושא זה: ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 של משנתנו \u0003סבר\u0004 כי \u0003ביאה\u0004 באמצע, כיון \u0003דאיכא למיגזר\u0004 \u0005[שיש\u0006 מקום \u0005לגזור\u0006 בה\u0005]\u0006 שתגרום לאיסור משום ביאה אחר חליצה או אחר ביאה — \u0003גזרינן\u0004 \u0005[גוזרים אנו]\u0006 בכל ביאה פסולה, ואומרים שאין ביאה פסולה מועילה כביאה כשרה. \u0003חליצה דליכא למיגזר\u0004 \u0005[שאין\u0006 מקום \u0005לגזור\u0006 בה\u0005],\u0006 שכן אף אם יעשה דבר אחריה לא יכולה לקרות כל תקלה — \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים].\u0006","","\u0003ור' נחמיה\u0004 במשנתנו שאמר שאחת זו ואחת זו אין אחריה כלום, \u0003סבר\u0004 כי ב\u0003ביאה נמי\u0004 \u0005[גם כן]\u0006 \u0003ליכא למיגזר\u0004 \u0005[אין\u0006 מקום \u0005לגזור],\u0006 \u0003ודקאמרת\u0004 \u0005[ומה שאמרת]\u0006 כנימוק \u0003ליגזור\u0004 \u0005[שנגזור]\u0006 ב\u0003ביאה אחר הגט משום ביאה אחר חליצה\u0004 — אין לחשוש לכך, ש\u0003כיון\u0004 ש\u0003חליצה\u0004 היא \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003מידע ידעי\u0004 \u0005[יודעים\u0006 אנשים\u0005]\u0006 שיש לה תוקף ואין אחריה כלום, ולא יבואו להחליף בדברים שהם מדברי חכמים בלבד. \u0003ודקאמרת\u0004 \u0005[ומה שאמרת]\u0006 \u0003ליגזור\u0004 \u0005[שנגזור]\u0006 \u0003ביאה אחר מאמר משום ביאה אחר ביאה — כיון\u0004 שקנין \u0003ביאה דאורייתא\u0004 \u0005[מן התורה]\u0006 הוא, \u0003הא מידע ידיעי\u0004 \u0005[\u0006דבר \u0005זה יודעים\u0006 אנשים\u0005]\u0006 ואינם טועים ומחליפים. \u0003ו\u0004לשיטת \u0003אבא יוסי בן חנן\u0004 שבאמצע ובסוף אחת זו ואחת זו יש אחריה כלום \u0003סבר לה כרבנן\u0004 \u0005[סבור כ\u0006דעת \u0005חכמים]\u0006 \u0003דגזרי\u0004 \u0005[שגוזרים]\u0006 \u0003בביאה,\u0004 אלא שהוא הוסיף \u0003וגזר חליצה משום ביאה,\u0004 ולכן אינו מחלק בין חליצה וביאה כלל.","","\u0003הבא על יבמתו, בין\u0004 אם היה זה \u0003בשוגג,\u0004 שלא ידע שהיא יבמתו, ובא עליה משום שחשב שהיא אשתו או אשה אחרת, \u0003בין\u0004 היה זה \u0003במזיד,\u0004 לשם זנות, ולא התכוון למצוה, \u0003בין באונס בין ברצון, אפילו\u0004 היה \u0003הוא שוגג\u0004 בדבר \u0003והיא מזידה,\u0004 או שהיה \u0003הוא מזיד והיא שוגגת,\u0004 וכן אם היה \u0003הוא אנוס והיא לא אנוסה,\u0004 או \u0003היא אנוסה והוא לא אנוס.\u0004 ואף אין חילוק בדרכי הביאה, אלא \u0003אחד המערה\u0004 שעושה רק חלק מן הביאה \u0003ואחד הגומר\u0004 את ביאתו — בכל המקרים הללו \u0003קנה\u0004 את היבמה בביאה זו, שזוכה בנכסי אחיו ואינו פוטרה אלא בגט. \u0003ולא חילק בין ביאה\u0004 כדרכה \u0003לביאה\u0004 שלא כדרכה.","\u0003וכן\u0004 הדין לגבי \u0003הבא על אחת מכל העריות שבתורה, או\u0004 נשים ה\u0003פסולות\u0004 לו, \u0003כגון אלמנה לכהן גדול\u0004 וכן \u0003גרושה\u0004 או \u0003חלוצה לכהן הדיוט,\u0004 או \u0003ממזרת\u0004 או \u0003נתינה לישראל,\u0004 וכן \u0003בת ישראל לממזר\u0004 או \u0003לנתין — פסלה\u0004 לכהונה בביאה, בכל דרך שנעשתה, ובממזרת ונתינה לישראל שהיא פסולה ממילא לכהונה — לוקה על ביאה זו, \u0003ולא חילק בין ביאה לביאה.\u0004","שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הלשון \u0003\"אפילו\u0004 הוא שוגג והיא מזידה\", מה החידוש בכך? שהרי כבר אמרנו שאין חילוק בין שוגג למזיד בקנין יבמה!","ומשיבים: בלשון \u0003לא מיבעיא קאמר\u0004 \u0005[נצרכה אמר];\u0006 \u0003לא מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 כשהיה \u0003הוא שוגג והיא קמכוונה\u0004 \u0005[מתכוונת]\u0006 \u0003למצוה, אי נמי\u0004 \u0005[או גם כן]\u0006 אם היה \u0003הוא מזיד והיא קמכוונה\u0004 \u0005[מתכוונת]\u0006 \u0003למצוה,\u0004 שקנה אותה, \u0003אלא אפילו\u0004 אם היה \u0003הוא שוגג והיא מזידה, דתרוייהו לא קמכווני\u0004 \u0005[ששניהם אינם מתכוונים]\u0006 \u0003לשם מצוה\u0004 בכך — \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003קנה. תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: אפילו\u0004 היו \u0003שניהם שוגגים,\u0004 או \u0003שניהם מזידים,\u0004 או \u0003שניהם אנוסים,\u0004 גם כן קנאה. שהקנין ביבמה נעשה על ידי ביאה, בלא התחשבות בצד הרצון שבדבר.","לגוף ההלכה במשנה שואלים: \u0003אנוס דמתניתין\u0004 \u0005[ש\u0006ב\u0005משנתנו]\u0006 \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 באיזה מקרה של אונס מדובר פה לגבי הגבר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003כשאנסוהו גוים,\u0004 שאיימו עליו שיהרגו אותו אם לא יבוא עליה, \u0003ובא עליה — והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא\u0004 בענין זה: \u0003אין אונס\u0004 ביחס \u0003ל\u0004בועל \u0003ערוה!\u0004 שאין אדם יכול לטעון שביאתו היתה באונס, אף על פי שעשאה שלא מרצונו החפשי, \u0003לפי שאין קישוי\u0004 של האבר \u0003אלא לדעת.\u0004 ולכן, גם כשמאיימים עליו לעשות זאת — הרי בסופו של דבר הוא עושה זאת מדעתו, ואם כן, לענייננו אין הבדל בין בא באונס לבא ברצון. \u0003אלא,\u0004 יש לומר שאונס זה הוא באופן אחר, \u0003בישן,\u0004 שאברו נתקשה כשהוא ישן, ויבמתו הביאתו עליה. \u0003ו\u0004אולם \u0003האמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה:\u0004",""],["\u0003ישן לא קנה ביבמתו,\u0004 שכיון שלא התכוון כלל לביאה אינו יכול לקנותה. \u0003אלא\u0004 תאמר שמדובר \u0003ב\u0004אופן שנתקשה לאשתו ו\u0003נתקע\u0004 בתוך כך ביבמתו כתוצאה מתאונה — \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רבה: נפל מן הגג ונתקע\u0004 באשה כעין ביאה \u0003חייב בארבעה דברים\u0004 שמשלם כל מזיק אדם, כלומר: נזק, צער, ריפוי ושבת, אבל אינו חייב בבושת שהרי לא התכוון לכך, \u0003וב\u0004מקרה שהיתה זו \u0003יבמתו לא קנה\u0004 בכגון זה.","\u0003אלא\u0004 אונס שאמרו \u0003כגון שנתכוון לאשתו, ותקפתו\u0004 (והחזיקה בו בכוח) \u0003יבמתו, ובא עליה.\u0004 ושואלים עוד: אם כן, \u0003\"שניהם אנוסים\" דבי\u0004 \u0005[ש\u0006שנה ב\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' חייא היכי דמי\u0004 \u0005[כיצד הוא בדיוק\u0006 לפי זה\u0005]?\u0006 ומשיבים: \u0003כגון שנתכוון לאשתו, ותקפוהו\u0004 (והחזיקו בו) \u0003גוים ודבקום\u0004 אותו ואת יבמתו \u0003זה בזה, ובא עליה.\u0004","ושואלים למקורן של הלכות אלה: \u0003מנא הני מילי\u0004 \u0005[מניין הדברים הללו]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 הכתוב \u0003\"יבמה יבא עליה\"\u0004 (דברים כה, ה) בא ללמד שביאה זו \u0003מצוה\u0004 היא יותר מן החליצה. \u0003דבר אחר: \"יבמה יבא עליה\",\u0004 כוונתו: יבוא עליה, מכל מקום — \u0003בין בשוגג בין במזיד בין באונס בין ברצון.\u0004","ושואלים: \u0003והא אפיקתיה\u0004 \u0005[והרי הוצאתו],\u0006 למדת כבר, מפסוק זה שביאה זו \u0003מצוה\u0004 היא, ואיך אפשר ללמוד ממנו דבר נוסף? ומשיבים: \u0003ל\u0004ענין הלימוד של \u0003\"מצוה\" מ\u0004הכתוב \u0003\"ואם לא יחפץ האיש\"\u0004 (שם ז) \u0003נפקא\u0004 \u0005[יוצא\u0006 נלמד\u0005],\u0006 שאנו מדייקים: \u0003הא\u0004 \u0005[הרי]\u0006 אם הוא \u0003חפץ — יבם\u0004 \u0005[מייבם],\u0006 שיש בייבום מצוה יותר מבחליצה. \u0003וכי אתא קרא\u0004 \u0005[וכאשר בא הכתוב\u0006 הזה\u0005]\u0006 \"יבמה יבא עליה\", כוונתו: \u0003בין בשוגג בין במזיד בין באונס בין ברצון.\u0004","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 הכתוב \u0003\"יבמה יבא עליה\",\u0004 משמעו, שקונה אותה בביאה \u0003כדרכה,\u0004 ומה שנאמר \u0003\"ולקחה\"\u0004 (שם) — לומר שקונה אותה אפילו בביאה \u0003שלא כדרכה.\u0004 אם היה כתוב רק \u0003\"\u0004יבמה יבוא עליה \u0003ויבם\"\u0004 הרי זה די כדי ללמדנו ש\u0003ביאה גומרת בה\u0004 את קניינה, \u0003ו\u0004אולם \u0003אין כסף ושטר גומרין בה\u0004 קנין אישות כבאשה אחרת, ואילו ההדגשה בכתוב \u0003\"ויבמה\"\u0004 באה ללמד כי קונה אותה אפילו \u0003בעל כרחה. דבר אחר:\u0004 הכתוב \u0003\"יבמה יבא עליה\",\u0004 כוונתו: \u0003בין בשוגג\u0004 בין במזיד ו\u0003כו'.\u0004","ושואלים: \u0003והא אפיקתיה\u0004 \u0005[והרי הוצאתו],\u0006 למדת כבר, מפסוק זה \u0003ל\u0004ענין ביאה \u0003כדרכה!\u0004 ומשיבים: \u0003ההוא\u0004 \u0005[אותו]\u0006 ענין של ביאה כדרכה יש לו מקור אחר — \u0003מ\u0004מה שנאמר ביבם \u0003\"להקים לאחיו שם\"\u0004 (שם ז) \u0003נפקא\u0004 \u0005[יוצא],\u0006 לומר שבא עליה \u0003במקום שמקים שם.\u0004 כלומר, ביאה כזו שעל ידה יש אפשרות שתהיה הולדה. \u0003וכי אתא קרא\u0004 \u0005[וכאשר בא הכתוב],\u0006 הרי זה ללמדנו שקונה אותה בביאה, \u0003בין\u0004 שהיתה זו \u0003בשוגג, בין במזיד, בין באונס, בין ברצון.\u0004","בדיון הקודם הוזכרו כמה הלכות, ודנים עכשיו ל\u0003גופא\u0004 \u0005[\u0006ל\u0005גופה]\u0006 של הלכה זו, \u0003אמר רב יהודה:\u0004 הבא על אשה כשהוא \u0003ישן\u0004 — \u0003לא קנה ביבמתו,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"יבמה יבא עליה\"\u0004 (שם ה), וכוונתו: \u0003עד\u0004 ש\u0003מכוין לה לשם ביאה,\u0004 והישן, שלא נתכוון לביאה, אינו קונה. ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 בדין המייבם: הבא על יבמתו \u0003בין ער בין ישן\u0004 — קנה! ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן כך: \u0003בין\u0004 היא \u0003ערה בין\u0004 היא \u0003ישנה\u0004 — קנה, מפני שבבעילה של יבמה אין הדבר צריך להיות מדעתה.","ומקשים: \u0003והתניא\u0004 \u0005[הרי שנינו\u0006 ברייתא אחרת\u0005],\u0006 שבה אי אפשר לפרש כך: \u0003בין ער הוא בין ישן הוא, בין ערה היא בין ישנה היא!\u0004 ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן,\u0006 במה שאמרנו שהישן קנה, \u0005במה אנו עוסקים]\u0006 — לא בישן ממש אלא \u0003במתנמנם.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד זה בדיוק]\u0006 \u0003מתנמנם? אמר רב אשי: נים\u0004 \u0005[ישן]\u0006 \u0003ולא נים\u0004 \u0005[ישן]\u0006 \u0003תיר\u0004 \u0005[ער]\u0006 \u0003ולא תיר\u0004 \u0005[ער],\u0006 ו\u0003כגון\u0004 שהוא במצב \u0003דקרו ליה ועני, ולא ידע לאהדורי סברא, וכי מדכרו ליה מדכר\u0004 \u0005[ש\u0006כאשר \u0005קוראים לו ו\u0006הוא \u0005עונה, ואינו יודע להשיב\u0006 דבר התלוי ב\u0005מחשבה, וכאשר מזכירים לו\u0006 מה שאירע — הוא \u0005נזכר],\u0006 זהו הקרוי מתנמנם.","וענין נוסף שהזכרנו ודנים ל\u0003גופא\u0004 \u0005[\u0006ל\u0005גופו],\u0006 \u0003אמר רבה: נפל מן הגג ונתקע\u0004 באשה כעין ביאה — \u0003חייב בארבעה דברים, ו\u0004בביאה \u0003ביבמתו\u0004 בדרך זו — \u0003לא קנה.\u0004 ובמה חייב — \u0003בנזק\u0004 אם גרם לאשה, \u0003בצער, בשבת\u0004 (שישלם על ביטול מלאכה עד לריפוי), ו\u0003ברפוי. אבל\u0004 על ה\u0003בושת\u0004 שנגרמה לה \u0003לא מיחייב\u0004 \u0005[חייב]\u0006 לשלם. ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003אין\u0004 אדם \u0003חייב על הבושת\u0004 שגרם לאחר \u0003עד שיתכוון\u0004 לביישו. ובודאי זה שנפל מן הגג לא נתכווין לביישה ולכך אין לחייבו בשל כך.","\u0003אמר רבא: נתכוון להטיח\u0004 להכניס איברו שלא לשם ביאה \u0003בכותל,\u0004 ונזדמן \u0003והטיח\u0004 (בעל) בלי כוונה \u0003ביבמתו — לא קנה,\u0004 שכן לא התכוון לביאה. ואם התכוון \u0003להטיח\u0004 (לבעול) \u0003בבהמה והטיח ביבמה — קנה, דהא קמכוין\u0004 \u0005[שהרי\u0006 הוא \u0005מתכוון]\u0006 על כל פנים \u0003לשם ביאה בעולם,\u0004 לאיזו שהיא ביאה, שאף שאין זו ביאה כדרך הטבע, בכל זאת ביאה היא.","שנינו במשנה ש\u0003אחד המערה\u0004 ואחד הגומר — קנה. \u0003אמר עולא: מנין להעראה\u0004 (השלב הראשון של ביאה) שדי בה \u0003מן התורה\u0004 לענין רוב ההלכות הנוגעות לביאה, ואין צורך בגמר ביאה? \u0003שנאמר: \"ואיש אשר ישכב את אשה דוה וגלה את ערותה את מקרה הערה\"\u0004 (ויקרא כ, יח), ו\u0003מכאן\u0004 אנחנו למדים מקור \u0003ל\u0004ענין זה של \u0003העראה,\u0004 שפירוש ביאה: גילוי (פתיחה), שאין צורך שתהא ביאה גמורה כדי להתחייב עליה \u0003מן התורה.\u0004","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא מקור לדין זה ב\u0003נדה,\u0004 ואולם לענין \u0003שאר עריות מנין\u0004 שגם בהן חייב על העראה בלבד? \u0003וכי תימא נילף\u0004 \u0005[ואם תאמר\u0006 ש\u0005נלמד\u0006 דבר זה\u0005]\u0006 \u0003מנדה —\u0004 אולם יש הבדל בין הדינים, שכן \u0003מה לנדה\u0004 שהיא חמורה יותר — \u0003שכן מטמאה את בועלה,\u0004 שהבא על הנידה נעשה טמא כמותה, מה שאין כן בעריות אחרות!","\u0003אלא אתיא\u0004 \u0005[בא\u0006 נלמד\u0005]\u0006 הדבר \u0003מאשת אח, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואיש אשר יקח את אשת אחיו נדה היא\"\u0004 (שם כא) — \u0003וכי אשת אחיו לעולם נדה היא\u0004 ואינה פוסקת? \u0003אלא\u0004 ודאי הכוונה היא שדינה \u0003כנדה,\u0004 ונלמד מכאן בין השאר: \u0003מה נדה\u0004 חייב עליה אף \u0003בהעראה\u0004 בלבד — \u0003אף אשת אח\u0004 די \u0003בהעראה\u0004 כדי לחייבו עליה.","ועדיין שואלים: \u0003מה ל\u0004איסור \u0003אשת אח\u0004 יש בו צד מיוחד — \u0003שכן בידו\u0004 של אדם \u0003לרבות\u0004 הרבה נשים שיהיו אסורות על אחיו באיסור אשת אח, \u0003דאי בעי\u0004 \u0005[שאם\u0006 הוא \u0005רוצה]\u0006 הריהו \u0003מקדש ואזיל\u0004 \u0005[והולך]\u0006 \u0003כי אלפא\u0004 \u0005[כדי אלף\u0006 נשים\u0005]\u0006 וכולן נאסרות על אחיו. וכיון שיש באיסור הזה צד מיוחד, אין ללמוד ממנו לאיסורים אחרים שאין בידו לרבות.","\u0003אלא אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר \u0003מאחות אב ואחות אם, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וערות אחות אמך ואחות אביך לא תגלה כי את שארו הערה\"\u0004 (שם יט), שלשון \"העראה\" כתובה שם במפורש, ומכאן ללמוד לשאר איסורי ביאה. ועדיין מקשים: \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005לפרוך,\u0006 לשבור, לסתור\u0005]\u0006 את ההשוואה לכל איסורי ביאה: \u0003מה לאחות אב ואחות אם\u0004 שהם איסורים מיוחדים מצד אחר — \u0003שכן איסור הבא מאליו,\u0004 שאיסור זה אינו בא על ידי מעשה קידושין, אלא הוא בא מעצם העובדה שפלונית היא אחות אביו או אחות אמו, ולכן אינו דומה לאיסורים אחרים הבאים מכוח קידושין.","ואומרים: \u0003מחדא\u0004 \u0005[מאחת]\u0006 מההוכחות הללו \u0003לא אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005],\u0006 ההלכה הכללית לגבי העראה, ובכן, \u0003תיתי חדא מתרתי\u0004 \u0005[תבוא,\u0006 תילמד, \u0005אחת משתים],\u0006 ושואלים: \u0003מהי תיתי\u0004 \u0005[מאיזו\u0006 מהן \u0005תבוא,\u0006 תילמד\u0005]?\u0006 אם תאמר כי \u0003תיתי\u0004 \u0005[תבוא,\u0006 תילמד\u0005]\u0006 \u0003מאשת אח ואחות אב ואחות אם\u0004 — מהם אי אפשר ללמוד לכל איסורי ביאה, שהרי אפשר לומר \u0003מה להנך\u0004 \u0005[לאלה]\u0006 \u0003שכן אסורין משום שאר\u0004 (קירבת משפחה), ואין בהם איסור אחר ואין ללמוד מהם איפוא אלא לאיסורי שאר אחרים, ולא לשאר איסורי ביאה.","\u0003אלא תיתי\u0004 \u0005[תבוא,\u0006 תילמד\u0005]\u0006 הלכה זו \u0003מנדה ואחות אב ואחות אם,\u0004 שנידה אינה אסורה משום שאר. ודוחים: גם מאלה אין ללמוד לכל מקרה, כי \u0003מה להנך\u0004 \u0005[לאלה]\u0006 \u0003שכן\u0004 שניהם \u0003איסור הבא מאליו,\u0004 שאיסורים אלה אינם נובעים ממעשה קידושין אלא נוצרים מעצמם בין בנידה ובין באחות אב ואחות אם. \u0003אלא תיתי\u0004 \u0005[תבוא,\u0006 תילמד\u0005]\u0006 הלכה זו \u0003מנדה ואשת אח. דמאי פרכת\u0004 \u0005[שמה אתה\u0006 יכול עוד \u0005לפרוך,\u0006 להקשות\u0005],\u0006 שכל פירכה שאתה מפריך נכונה לגבי אחד אבל לא לגבי השני. שהרי איסור נידה הוא איסור הבא מעצמו ואינו איסור שאר, ואי אפשר להרבות בו. ואשת אח הוא איסור שאינו בא מעצמו אלא מכח קידושין.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: מה לנדה ואשת אח\u0004 שיש בהם צד מיוחד, \u0003שכן אין להם היתר בחיי אוסרן,\u0004 כלומר, שכל זמן שהגורם לאיסור קיים אין לאיסור זה היתר, שאין הנידה מותרת כל זמן שרואה דם נידות, ולא אשת אח כל זמן שהאח חי, \u0003תאמר באשת איש, שכן יש לה היתר בחיי אוסרה\u0004 על ידי גט!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדפתי לרבינא: אטו\u0004 \u0005[וכי]\u0006 \u0003נדה ואשת אח בחיי אוסרן הוא\u0004 ש\u0003אין להם היתר, אבל לאחר מכאן יש להם היתר?\u0004 הלא \u0003נדה\u0004"],["אפילו אם פסקה לראות, עדיין אסורה היא, שכן \u0003ביומי תליא מילתא\u0004 \u0005[בימים תלוי הדבר]\u0006 ולא בראיית הדם דווקא, שהרי כל שבעת הימים אסורה היא, גם אם אין דם שופע ממנה. ואף \u0003אשת אח — בבנים תליא רחמנא\u0004 \u0005[תלתה התורה]\u0006 את איסורה, שאם יש לה בנים — אסורה לעולם אפילו אם מת בעלה־אחיו.","\u0003אלא פריך הכי\u0004 \u0005[הקשה כך],\u0006 בלשון שונה: \u0003מה לנדה ואשת אח שכן אין אוסרן,\u0004 כלומר, הדבר שגורם שתיאסרנה, אינו זה ה\u0003מתירן,\u0004 שההיתר בא מצד אחר; בנידה — כאשר חולפים שבעה ימים. ובאשת אח כאשר במותו אינו משאיר בנים — \u0003תאמר באשת איש ש\u0004ה\u0003אוסרה\u0004 (בעלה) הוא עצמו \u0003מתירה\u0004 בגט!","\u0003אלא,\u0004 עלינו לחזור בנו מהוכחות אלה ולסמוך על מה ש\u0003אמר ר' יונה, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב הונא בריה דרב יהושע: אמר קרא\u0004 \u0005[הכתוב]\u0006 בסוף פרשת העריות: \u0003\"כי כל אשר יעשה מכל התועבת האלה ונכרתו הנפשות העשת\"\u0004 (ויקרא יח, כט) — \u0003הוקשו\u0004 (הושוו) \u0003כל העריות כולן\u0004 זו לזו וממילא גם \u0003לנדה\u0004 המוזכרת באותה פרשה, ויש לומר: \u0003מה נדה\u0004 חייב עליה \u0003בהעראה\u0004 (\"את מקורה הערה\"), \u0003אף\u0004 לחייב את \u0003כל\u0004 שאר העריות די \u0003בהעראה.\u0004","ושואלים: אם מכאן למדים, \u0003ואלא \"נדה\" דכתיבא\u0004 \u0005[שנאמרה]\u0006 \u0003גבי אשת אח למה לי?\u0004 שהרי לענין העראה למדים את כל העריות מנידה בהיקש! ומשיבים: כתוב זה צריך \u0003לכ\u0004 פי שאמר \u0003רב הונא,\u0004 ש\u0003אמר רב הונא: רמז ליבמה מן התורה מנין,\u0004 ומיד תוהים על הלשון: \u0003מנין?!\u0004 מה מקום לשאלה זו? \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 במפורש: \u0003\"יבמה יבא עליה\"\u0004 (דברים כה, ה)! \u0003אלא: רמז ליבמה שאסורה\u0004 לאח בעלה \u0003בחיי בעלה\u0004 גם לאחר שגירשה, \u0003מנין\u0004 יודעים זאת.","ומוסיפים לתהות: הלא גם לדבר זה אין צורך בהוכחה מיוחדת, שכן \u0003האי\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 \u0003סברא היא, מדאמר רחמנא\u0004 \u0005[מ\u0006מה \u0005שאמרה התורה]\u0006 ש\u0003לאחר מיתת בעלה שריא\u0004 \u0005[מותרת\u0006 האשה\u0005],\u0006 \u0003מכלל\u0004 הדברים אתה למד ש\u0003בחיי בעלה אסורה\u0004 היא לאחיו!","\u0003ו\u0004דוחים: אפשר היה לומר \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003לאחר מיתת בעלה — מצוה\u0004 לשאתה, \u0003בחיי בעלה — רשות? אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לומר ש\u0003לאחר מיתת בעלה — אין\u0004 \u0005[כן],\u0006 מותרת, \u0003בחיי בעלה — לא,\u0004 ויש בכך רק לאו הבא מכלל עשה, שאין זה איסור לאו מפורש אלא רק ביטול ושלילה של מצות עשה, \u0003ולאו הבא מכלל עשה\u0004 — דינו כ\u0003עשה,\u0004 ולא יותר,","ולכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ואיש אשר יקח את אשת אחיו נדה היא\"\u0004 (ויקרא כ, כא), ויש להבין: \u0003וכי אשת אחיו\u0004 לעולם \u0003נדה היא\u0004 ואינה פוסקת? \u0003אלא\u0004 הריהי \u0003כנדה, מה נדה אף על פי שיש לה היתר לאחר מכאן\u0004 בתום שבעה ימים לראייתה, בכל אופן \u0003בשעת איסורא\u0004 \u0005[האיסור]\u0006 עובר הבא עליה \u0003בכרת, אף אשת אח נמי\u0004 \u0005[גם כן]\u0006 \u0003אף על פי שיש לה היתר לאחר מכאן\u0004 כשמת בעלה בלא ילדים — \u0003בחיי בעלה\u0004 נענש עליה האח הבא עליה \u0003בכרת.\u0004","ושואלים: \u0003אלא העראה דכתיבא\u0004 \u0005[שנאמרה]\u0006 \u0003גבי\u0004 (אצל) \u0003אחות אב ואחות אם, למה לי?\u0004 אם למדים דין זה בהיקש?","ומשיבים: דבר זה מועיל לפתור בעיה אחרת, \u0003לכדבעא מיניה\u0004 \u0005[לכ\u0006 מו זה \u0005ששאל אותו]\u0006 \u0003רבינא מרבא: המערה בזכור\u0004 (משכב זכר) \u0003מהו?\u0004 האם גם כאן העראה דינה כביאה גמורה, או לא? ותוהים: \u0003בזכור\u0004 אין צורך בהוכחה מיוחדת! הלא \u0003\"משכבי אשה\" כתיבא\u0004 \u0005[נאמר]\u0006 בו (\"ואת זכר לא תשכב משכבי אשה\". שם יח, כב) ומכאן יודעים כי כל הנתפס במושג ביאה ביחס לאשה יכול להיתפס גם בזכר.","\u0003אלא,\u0004 השאלה היא בענין \u0003המערה בבהמה, מהו?\u0004 האם זו נחשבת כביאה או לא? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אם\u0004 ביטוי זה הכתוב בתורה \u0003אינו ענין,\u0004 שאינו בא ללמד, \u0003להעראה, דכתיבא\u0004 \u0005[שנאמרה]\u0006 \u0003גבי אחות אב ואחות אם, דאתיא בהקישא\u0004 \u0005[ש\u0006הרי \u0005באה,\u0006 נלמדת הלכה זו \u0005בהיקש]\u0006 \u0003מ\u0004דברי \u0003ר' יונה, תנהו ענין להעראה\u0004 של \u0003בהמה.\u0004 שמייתור ההלכה בענין זה, למדים לדין אחר באותו תחום, שכל דיני ביאות יש להם צד שווה בהעראה.","ושואלים: \u0003מכדי\u0004 \u0005[הלא]\u0006 ביאה על \u0003בהמה חייבי מיתות בית דין היא, מאי טעמא כתיב\u0004 \u0005[מה טעם\u0006 אם כן \u0005נאמר]\u0006 ענין \u0003העראה דידה\u0004 \u0005[שלה]\u0006 \u0003גבי\u0004 (אצל) \u0003חייבי כריתות,\u0004 אחות אב ואחות אם? \u0003לכתוב\u0004 \u0005[שיאמר]\u0006 אותה ל\u0003גבי\u0004 עריות שחייבים עליהם כמותה ב\u0003מיתת בית דין, ונילף\u0004 \u0005[ונלמד]\u0006 \u0003מיתת בית דין\u0004 של בהמה \u0003ממיתת בית דין\u0004 של עריות!","ומשיבים: \u0003איידי דכוליה קרא לדרשא אתי\u0004 \u0005[כיון שכל הכתוב\u0006 של אחות אב ואחות אם כולו \u0005לדרשה בא],\u0006 \u0003כתיב ביה נמי הא מילתא לדרשא\u0004 \u0005[נאמר בו גם דבר זה לדרשה],\u0006 שכן פסוק זה עצמו אינו בא ללמדנו דבר חדש, אלא רק מסקנות היוצאות ונובעות מעבר לדברים המפורשים בו.","ושואלים: \u0003מאי דרשא\u0004 \u0005[מה\u0006 היא \u0005הדרשה]\u0006 הזו? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"ערות אחות אביך לא תגלה\"\u0004 (שם יח, יב), משמע: \u0003בין\u0004 שהיא אחותו של אב \u0003מן האב, בין\u0004 שהיא אחותו \u0003מן האם. אתה אומר\u0004 שאחות זו היא \u0003בין מן האב בין מן האם, או אינו אלא\u0004 אחות אביו \u0003מן האב\u0004 דווקא \u0003ולא מן האם.\u0004","\u0003ו\u0004לכאורה אין צורך בכתוב מפורש, שהרי \u0003דין הוא\u0004 ואפשר ללמוד זאת מן הסברה: \u0003חייב כאן\u0004 באחות אביו \u0003וחייב באחותו, מה אחותו\u0004 חייב עליה \u0003בין\u0004 שהיא \u0003מן האב בין\u0004 שהיא \u0003מן האם — אף כאן\u0004 באחות אביו, חייב עליה \u0003בין\u0004 שהיא \u0003מן האב בין\u0004 שהיא \u0003מן האם.\u0004","אולם אם לדון רק על פי השוואה, יש גם אפשרות אחרת, \u0003או כלך\u0004 \u0005[לך]\u0006 \u0003לדרך זו\u0004 ונשווה להלכה אחרת: \u0003חייב כאן וחייב בדודתו\u0004 שהיא אשת אחי אביו, \u0003מה דודתו\u0004 האסורה לו היא דווקא זו הנשואה לאחי אביו \u0003מן האב ולא מן האם\u0004 (אשת אחי אביו מן האם), \u0003אף כאן — לא אסרה התורה אלא את אחות אביו מן האב ולא מן האם?!\u0004","ודנים: \u0003נראה למי דומה\u0004 למה אפשר להשוות? \u0003דנין איסור הבא מאליו\u0004 כאיסור אחות אב, \u0003מאיסור\u0004 אחותו שלו \u0003הבא מאליו,\u0004 ששניהם איסורים שאינם תלויים בקשרי נישואין, אלא בקירבה, \u0003ואל תוכיח דודתו, שאין\u0004 זה \u0003איסור הבא מאליו,\u0004 אלא על ידי נישואין.","אלא שאפשר לדחות ולטעון: \u0003או כלך\u0004 \u0005[לך]\u0006 \u0003לדרך זה\u0004 ואמור: \u0003דנין קרובי האב מקרובי האב, ואל תוכיח אחותו שקרובי עצמו\u0004 היא, ואם כן אין להביא הוכחה מכרעת מן הסברה —","\u0003תלמוד לומר\u0004 מן הכתוב היתר: \u0003\"ערות אחות אביך לא תגלה\",\u0004 ללמדנו — \u0003בין מן האב בין מן האם.\u0004 וכן למדים \u0003\"ערות אחות אמך לא תגלה\"\u0004 (שם יג) — \u0003בין מן האב בין מן האם,\u0004","ושואלים: \u0003למה לי,\u0004 מדוע היה צריך \u0003למכתבא\u0004 \u0005[לומר]\u0006 אותו דבר \u0003באחות אב, למה לי למכתבא\u0004 \u0005[לומר]\u0006 אותו דבר \u0003באחות אם?\u0004 די היה שייכתב באחד מהם! \u0003אמר ר' אבהו: צריכי\u0004 \u0005[צריכים\u0006 הם\u0005],\u0006 \u0003דאי כתב רחמנא\u0004 \u0005[שאם היתה אומרת התורה]\u0006 רק \u0003באחות אב,\u0004 היינו אומרים שהיא שונה, \u0003שכן יש לה חייס\u0004 (ייחוס), משום שייחוס המשפחה הולך אחרי האב, \u0003אבל אחות אם אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 משום שמשפחת אם איננה קרויה משפחה.","ולהיפך: \u0003ואי כתב רחמנא\u0004 \u0005[אם היתה אומרת התורה]\u0006 \u0003באחות אם,\u0004 הייתי אומר — \u0003שכן ודאית,\u0004 שהרי הקשר של אדם עם אמו הוא ודאי, ולכן יש לאסור את אחותו מן האם, \u0003אבל אחות אב אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 נאסור אותה עליו, שכן אבהות לעולם אינה ודאית, ויתכן שאינה אחותו כלל, ולכן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 ההלכה להיאמר בשתיהן.","ושואלים: \u0003ודודתו דפשיטא ליה\u0004 \u0005[שפשוט לו]\u0006 \u0003לתנא\u0004 שהיא דווקא אשת אחי אביו \u0003מן האב ולא מן האם מנא ליה\u0004 \u0005[מניין לו]\u0006 דבר זה?","\u0003אמר רבא: אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר מגזירה שווה של המילים \u0003\"דודו\" \"דודו\". כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"ערות דדו גלה\"\u0004 (שם כ, כ), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 בדיני גאולת קרקע של אדם על ידי בני משפחתו: \u0003\"או דדו או בן דדו יגאלנו\"\u0004 (שם כה, מט), \u0003מה להלן\u0004 בענייני גאולה בקרובים אין חובת הגאולה מוטלת אלא על דודו \u0003מן האב ולא מן האם, אף כאן\u0004 בדיני ערוה, דודו זה — ודאי שהוא \u0003מן האב ולא מן האם.\u0004","ושואלים: \u0003והתם\u0004 \u0005[ושם]\u0006 בדיני גאולה \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 שאין מדובר בדוד מן האם? ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ממשפחתו יגאלנו\"\u0004 (שם), וידוע כי רק \u0003משפחת אב קרויה משפחה,\u0004 ואילו \u0003משפחת אם אינה קרויה משפחה,\u0004 שייחוס האדם הוא לפי משפחת האב.","\u0003והדתנן\u0004 \u0005[וזה ששנינו\u0006 במשנה\u0005]\u0006 \u0003אמרו לו\u0004 לאדם: \u0003מתה אשתך, ו\u0004הוא \u0003נשא\u0004 את \u0003אחותה\u0004 של אשתו \u0003מ\u0004צד \u0003אביה,\u0004 ולאחר מכן אמרו לו: \u0003מתה\u0004 האחות הזו, אשתו השניה, \u0003ונשא\u0004 את \u0003אחותה מאמה\u0004 של אשתו השניה, ושוב אמרו לו ש\u0003מתה\u0004 אף זו, \u0003ונשא\u0004 את \u0003אחותה מאביה\u0004 של השלישית, ואמרו לו שגם זו \u0003מתה, ונשא אחותה מאמה\u0004 — אם התברר אחר כך כי כל השמועות הללו היו שמועות שקר, וכל הנשים חיות, אם כן חלק מן הנישואין הללו לא היו נישואין כלל, לפי שנשא אחות אשתו בחייה,","ולכן \u0003מותר ב\u0004אשתו ה\u0003ראשונה ובשלישית\u0004 שאיננה קרובת אשתו מכל צד, \u0003ובחמישית\u0004 שאינה קרובה לא לאשתו הראשונה ולא לאחרת, ונישואיהן נישואין גמורים הם, \u0003ופוטרות\u0004 את \u0003צרותיהן,\u0004 שאם נפלו לייבום ונחלצה (או נבעלה) אחת מהם — נפטרו כולן. אבל \u0003אסור בשניה וברביעית\u0004 משום שכל אחת מהן היא אחות אשתו בחייה ונשא אותה באיסור, \u0003ואין ביאת אחת מהן פוטרת צרתה,\u0004 שאינה אשת אחיו שהרי לא תפסו בהן קידושין.","\u0003ואם\u0004 אכן מתה הראשונה, ו\u0003בא על השניה לאחר מיתת הראשונה,\u0004 הרי אז \u0003מותר בשניה, וברביעית\u0004 (שהרי אינה קרובה לשניה) ונישואיהן נישואין גמורים היו, \u0003ופוטרות צרותיהן, ואסור בשלישית ובחמישית,\u0004 משום אחות אשתו בחייה."],["\u0003אלמא\u0004 \u0005[מכאן]\u0006 ממשנה זו אנו למדים ש\u0003אחות אשתו בין מן האב בין מן האם — אסורות. מנלן\u0004 \u0005[מניין לנו]\u0006 דבר זה שאיסור אחות אשתו הוא גם באחותה מצד אחד? ואומרים: \u0003יליף\u0004 \u0005[לומד\u0006 הוא\u0005]\u0006 \u0003מאחותו. מה אחותו\u0004 אסורה עליו \u0003בין\u0004 שהיא אחותו \u0003מן האב בין\u0004 שאינה אחותו אלא \u0003מן האם — אף כאן\u0004 באחות אשתו אסור בה \u0003בין\u0004 שהיא \u0003מן האב בין\u0004 שהיא \u0003מן האם.\u0004","ומקשים: \u0003ולילף\u0004 \u0005[ושילמד]\u0006 \u0003מדודתו,\u0004 כך: \u0003מה דודתו\u0004 אסורה בין שהיא אשת אחי אביו \u0003מן האב ולא מן האם, אף כאן\u0004 אחות אשתו אינה אסורה לו אלא כשהיא אחותה \u0003מן האב ולא מן האם!\u0004 ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 ש\u0003מאחותו הוה ליה למילף\u0004 \u0005[היה לו ללמוד]\u0006 \u0003שכן\u0004 הוא לומד \u0003קרובי עצמו מקרובי עצמו,\u0004 ודודתו אסורה עליו מפני קרובת אביו.","ודוחים: \u0003אדרבה\u0004 (להיפך), \u0003מדודתו הוה ליה למילף\u0004 \u0005[היה לו ללמוד]\u0006 \u0003שכן\u0004 כך הוא לומד אחות אשתו, שהיא \u0003דבר\u0004 שנאסר \u0003על ידי קדושין, מדבר ש\u0004אף איסורו אינו אלא \u0003על ידי קדושין\u0004 (דודתו)! \u0003אלא,\u0004 יש לומר כי אחות אשה \u0003מאשת אח ילפינן\u0004 \u0005[אנו לומדים],\u0006 \u0003דשכן\u0004 שניהם הם \u0003דבר על ידי קדושין, וקרובי עצמו.\u0004","ושואלים: \u0003ואשת אח גופה\u0004 \u0005[עצמה]\u0006 \u0003מנא לן\u0004 \u0005[מניין לנו]\u0006 שאסורה בין כשהוא אחיו מאביו בין כשהוא אחיו מאמו? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \u0003\"ערות אשת אחיך לא תגלה\"\u0004 (ויקרא יח, טז), וכוונתו: אסורה עליך אשת אחיך, \u0003בין\u0004 באחיך \u0003מן האב בין מן האם.\u0004","ודנים: \u0003אתה אומר\u0004 שאיסור אשת אח הוא \u0003בין\u0004 באשת אח \u0003מן האב בין מן האם, או אינו\u0004 אסור \u0003אלא\u0004 באשת אח \u0003מן האב\u0004 בלבד \u0003ולא מן האם? ו\u0004לכאורה \u0003דין הוא,\u0004 שאפשר להוכיח את הדבר מן הסברה: שכן \u0003חייב כאן\u0004 באשת אח, \u0003וחייב באחותו, מה אחותו\u0004 חייב עליה \u0003בין\u0004 שהיא אחותו \u0003מן האב בין מן האם — אף כאן\u0004 אשת אחיו אסורה עליו \u0003בין\u0004 באח \u0003מן האב בין מן האם.\u0004","\u0003או\u0004 אפשר גם לומר, \u0003כלך לדרך זו: חייב כאן וחייב בדודתו, מה דודתו\u0004 אינה אסורה עליו אלא כשהיא אשת אחי אביו \u0003מן האב ולא מן האם — אף כאן\u0004 אשת אחיו אינה אסורה אלא באח \u0003מן האב ולא מן האם?!\u0004","ודנים: \u0003נראה למי דומה, דנין קרובי עצמו\u0004 (אשת אחיו) \u0003מקרובי עצמו\u0004 (אחותו) \u0003ואל תוכיח\u0004 מ\u0003דודתו ש\u0004היא \u0003קרובי האב\u0004 לאשת אחיו שהיא קרובתו. אולם אפשר לדון גם להיפך, \u0003או כלך לדרך זו: דנין דבר ש\u0004איסורו \u0003על ידי קדושין\u0004 (אשת אחיו, שנאסרה עליו משום קידושי אחיו), \u0003מדבר ש\u0004אף הוא אסור עליו \u0003על ידי קדושין\u0004 (כדודתו שאסורה משום שקידשה דודו), \u0003ואל תוכיח אחותו, ש\u0004היא \u0003איסור הבא מאליו\u0004 (מעצמו) בלא קידושין.","וכיון שאין להוכיח מן הסברה — \u0003תלמוד לומר\u0004 מה שכפל בסוף אותו פסוק: \u0003\"ערות אחיך היא\"\u0004 (שם) להדגיש שאסורה היא בכל מקרה, \u0003בין מן האב בין מן האם.\u0004","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 בתחילת הפסוק ובסופו מדובר \u0003באשת אח מן האב,\u0004 והריבוי שבתורה בא לומר: \u0003חדא\u0004 \u0005[אחת]\u0006 לאסור את זו ש\u0003יש לה בנים בחיי בעלה, וחדא\u0004 \u0005[ואחת]\u0006 לאסור את זו ש\u0003אין לה בנים בחיי בעלה,\u0004 שאף אם גירשה אחיו — אסורה האשה עליו. ומשיבים: הלא זו ש\u0003אין לה בנים בחיי בעלה מ\u0004דברי \u0003רב הונא\u0004 (לעיל יבמות נד, ב) \u0003נפקא\u0004 \u0005[יוצאת,\u0006 נלמדת\u0005]\u0006 ואינה צריכה למקור נוסף.","ומקשים מצד אחר: \u0003ואימא\u0004 \u0005[ואמור]\u0006 \u0003אידי ואידי\u0004 \u0005[זו וזו]\u0006 \u0003באשת אח מן האב, חדא\u0004 \u0005[אחת]\u0006 ש\u0003יש לה בנים בחיי בעלה\u0004 וגירשה, \u0003וחדא\u0004 \u0005[ואחת]\u0006 ש\u0003יש לה בנים לאחר מיתת בעלה!\u0004","ומשיבים: זו ש\u0003יש לה בנים לאחר מיתת בעלה — לא צריכה קרא\u0004 \u0005[אינה צריכה כתוב]\u0006 מיוחד, \u0003מדאמר רחמנא\u0004 \u0005[מ\u0006כיון \u0005שאמרה התורה]\u0006 שזו \u0003שאין לה בנים מותרת\u0004 לאח, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003יש לה בנים אסורה.\u0004","ומקשים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 נאמר כך: אם \u0003אין לה בנים — אסורה לעלמא\u0004 \u0005[לכול]\u0006 \u0003ושריא\u0004 \u0005[ומותרת]\u0006 \u0003ליבם\u0004 כמפורש בתורה, אבל אם \u0003יש לה בנים — שריא לעלמא ושריא\u0004 \u0005[מותרת לכול ומותרת]\u0006 גם \u0003ליבם! אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר היה לומר: אם אשת אחיו \u0003אין לה בנים — מצוה\u0004 ליבמה, ואולם אם \u0003יש לה בנים — רשות,\u0004 שמותר לאחי בעלה לשאתה אם ירצה!","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 נאמר כך: זו ש\u0003אין לה בנים — אין\u0004 \u0005[כן]\u0006 מותרת ליבם, וזו ש\u0003יש לה בנים — לא,\u0004 אולם כיון שאיסור זה נובע רק ממה שאינו במצות ייבום, אם כן \u0003ו\u0004יהיה זה בגדר \u0003לאו הבא מכלל עשה\u0004 ולאו כזה דינו הוא רק כ\u0003עשה,\u0004 ולכן נצרך ייתור הפסוק \"ערות אחיך היא\" ללמד שיש עליה עונש כרת!","ומשיבים: שיש עונש כרת אנו למדים מזה ש\u0003כתב קרא אחרינא\u0004 \u0005[נאמר כתוב אחר]:\u0006 \u0003\"ערות אחיו גלה\u0004 ערירים יהיו\u0003\"\u0004 (ויקרא שם כ, כא), לומר שיש בה איסור כרת.","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 ש\u0003אשת אח מן האם\u0004 יהא דינה \u0003כאשת אח מן האב; מה אשת אח מן האב לאחר מיתת בעלה שריא\u0004 \u0005[מותרת]\u0006 ליבם (אם לא היה למת בנים) — \u0003אף אשת אח מן האם, לאחר מיתת בעלה שריא\u0004 \u0005[מותרת]\u0006 ליבם! ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"היא\",\u0004 שמכתוב זה למדים איסור אשת אח מן האם, להדגיש ולצמצם ולומר: \u0003בהוייתה תהא,\u0004 תישאר כמות שהיא באיסורה, שלזו אין היתר.","לאחר שביררנו ענין זה, שואלים: כיון שנלמדו כל העריות זו מזו והושוו כולן לחיוב כרת מהכתוב \"ונכרתו הנפשות העושות\", אם כן, \u0003אחותו\u0004 ש\u0003כתב בה כרת\u0004 במפורש \u0003למה לי?\u0004","ומשיבים: בא הדבר ללמד \u0003לכ\u0004 מו שאמר \u0003ר' יוחנן,\u0004 ש\u0003אמר ר' יוחנן: שאם עשאן כולם בהעלם אחת,\u0004 כלומר, שבשגגה אחת בא על כל העריות — \u0003חייב על כל אחת ואחת.\u0004 שלא נחשוב שאיסור עריות הוא איסור כללי, וכל סוג וסוג של עבירה זו הוא רק חלק מאיסור כולל זה, ואם עשה אותן בשגגה אחת אינו חייב אלא בקרבן אחד, לכן כתב כרת באחותו ללמד שכל אחת מהן הוא איסור פרטי, וחייב עליו בפני עצמו.","ושואלים: \u0003ולר' יצחק\u0004 ש\u0003אמר\u0004 בפירוש הפסוק כך: \u0003כל חייבי כריתות בכלל\u0004 אחד \u0003היו,\u0004 שנאמר: \"ונכרתו הנפשות העושות\", \u0003ולמה יצתה\u0004 (יצאה) \u0003כרת\u0004 במפורש \u0003באחותו?\u0004 ללמדנו שיש \u0003לדונו בכרת ולא במלקות.\u0004 שחייבי כרת אין מלקים אותם, אף שנאמר בהם לא תעשה, לפי שעונשם חמור יותר, ואם כן דינו של ר' יוחנן \u0003לחלק\u0004 את האיסורים ולחייב על כל ערוה בפני עצמה, \u0003מנלן\u0004 \u0005[מניין לנו]?\u0006","ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו,\u0006 לומד הוא\u0005]\u0006 דבר זה \u0003מ\u0004מה שכתוב \u0003\"ואל אשה בנדת טמאתה\"\u0004 (שם יח, יט), \u0003לחייב על כל אשה ואשה\u0004 שהיא ערוה לו בפני עצמה.","ושואלים עוד: כיון שלמדנו מן הכתוב שכל העריות בכרת, אם כן, \u0003דודתו דכתב\u0004 \u0005[שאמרה]\u0006 \u0003בה רחמנא\u0004 \u0005[התורה]\u0006 \u0003\"ערירים יהיו\"\u0004 (שם כ, כב) \u0003למה לי?\u0004 והרי מיתת הבנים היא בכלל עונש כרת! ומשיבים: שנצרך הדבר \u0003לכפי\u0004 שאמר \u0003רבה.\u0004 ש\u0003רבה רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 בכתוב אחד, בענין הבא על אשת אחיו \u0003\"ערירים יהיו\"\u0004 (שם כא) \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בענין הבא על דודתו \u0003\"ערירים ימתו\"\u0004 (שם כ), \u0003הא כיצד\u0004 ניישב הבדל זה בין הכתובים? אם \u0003יש לו\u0004 כבר \u0003בנים — קוברן, אין לו בנים — הולך ערירי\u0004 ולא יוולדו לו.","ומעירים: \u0003ואיצטריך למכתב\u0004 \u0005[והוצרך לומר]\u0006 לשון \u0003\"ערירים יהיו\" ואיצטריך למכתב\u0004 \u0005[והוצרך לומר]\u0006 גם לשון \u0003\"ערירים ימתו\". דאי כתב רחמנא\u0004 \u0005[שאילו אמרה התורה]\u0006 רק \u0003\"ערירים יהיו\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 שימותו בנים שהיו לו \u0003עד\u0004 זמן \u0003חטאיה\u0004 \u0005[חטאו],\u0006 \u0003אבל\u0004 בנים שנולדו לו \u0003מחטאיה\u0004 \u0005[מחטאו]\u0006 \u0003ואילך — לא\u0004 ימותו, על כן \u0003כתב רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003\"ערירים ימתו\"\u0004 שגם אם נולדו לו ילדים אחר כך — ימותו, וישארו ערירים. \u0003ו\u0004כן, \u0003אי כתב רחמנא\u0004 \u0005[אם\u0006 היתה \u0005אומרת התורה\u0006 כך\u0005]\u0006 \u0003\"ערירים ימתו\" הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שמדובר בבנים שנולדו \u0003מחטאיה\u0004 \u0005[מחטאו]\u0006 \u0003ואילך אבל מעיקרא\u0004 \u0005[מתחילה]\u0006 אלה שנולדו עד לזמן החטא — \u0003לא\u0004 ייענשו, על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 לומר בשני האופנים.","למדנו איפוא דין העראה בכל חייבי כריתות על פי ההיקש שמשווה את כולם זה לזה, ולמדים מאותם המקרים שהעראה מפורשת בהם, אבל ש\u0003העראה\u0004 אסורה ונחשבת כביאה גמורה אף ב\u0003חייבי לאוין מנלן\u0004 \u0005[מניין לנו]?\u0006","ומשיבים: \u0003מדגלי רחמנא\u0004 \u0005[מ\u0006מה \u0005שגילתה התורה]\u0006 ופירשה \u0003\"שכבת זרע\" גבי שפחה חרופה\u0004 (\"ואיש כי ישכב את אשה שכבת זרע והיא שפחה נחרפת לאיש...\". ויקרא יט, כ), לומר שרק בענין זה אין די בהעראה, וחייב רק על ביאה גמורה (\"שכבת זרע\"), ו\u0003מכלל\u0004 זה אתה למד כי \u0003חייבי לאוין\u0004 אחרים — \u0003בהעראה\u0004 בלבד מתחייבים עליהם. שאם לא כן לא היה צריך לפרש בשפחה חרופה.","ודוחים: \u0003אדרבה\u0004 (להיפך), אפשר לטעון: \u0003מדגלי רחמנא\u0004 \u0005[מ\u0006מה \u0005שגילתה התורה]\u0006 חיוב על \u0003העראה בחייבי כריתות, מכלל\u0004 זה נלמד שב\u0003חייבי לאוין\u0004 חייבים רק \u0003בגמר ביאה! אמר רב אשי: אם כן,\u0004 אילו חייבי לאוין היו מתחייבים רק על גמר ביאה — \u0003לשתוק קרא\u0004 \u0005[שישתוק הכתוב]\u0006 ולא יפרש ב\u0003שפחה חרופה\u0004 שאין חייבים עליה אלא בביאה גמורה ויהא דינה כשאר חייבי לאוין, וכיון שהוצרך דין זה להתפרש בה — הרי זו הוכחה ששפחה חרופה היא היוצאת מן הכלל, שלא כשאר חייבי לאוין.","ושואלים עוד: \u0003העראה\u0004 שדינה כביאה ב\u0003חייבי לאוין\u0004 שאסורים דווקא ל\u0003כהונה מנלן\u0004 \u0005[מניין לנו]?\u0006 כי אין ללמוד דינים אלה משאר איסורי לאו של עריות, שכן דינים אלה אינם שוים בכל ישראל. ומשיבים: \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה של המילים \u0003\"קיחה\" \"קיחה\".\u0004 שלשון זו נאמרה באיסור שיש בו חיוב כרת, כגון \"ואיש אשר יקח את אחותו\" (שם כ, יז) ונאמרה גם באיסורי כהונה \"לא יקחו\" (שם כא, ז).","ושואלים: והעראה שבאיסורי ביאה של \u0003חייבי עשה,\u0004 כגון בגר מצרי ואדומי שנאמר בהם שרק \"דור שלישי יבוא להם בקהל ה'\" (דברים כג, ט), וגר מצרי עצמו, או בנו, אסורים בגלל עשה זה — \u0003מנא לן\u0004 \u0005[מניין לנו]\u0006 שגם בהם העראה דינה כביאה גמורה?"],["\u0003אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה, מהמלה \u0003\"ביאה\" \"ביאה\"\u0004 האמורה גם בחייבי לאוין (כגון: \"לא יבוא ממזר\". דברים כג, ג), וכן זו האמורה בחייבי עשה (\"דור שלישי יבוא להם\" שם ט).","ושואלים: \u0003יבמה\u0004 שנבעלה בהעראה בלבד \u0003ל\u0004אדם מן ה\u0003שוק\u0004 לפני החליצה, \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 שהיא עוברת בכך עבירה? ומשיבים: כאן אין צורך בלימוד מיוחד, שכן \u0003אי למאן דאמר לאו\u0004 \u0005[אם ל\u0006דעת \u0005מי שאומר\u0006 שיש בכך איסור \u0005לא\u0006 תעשה\u0005],\u0006 אם כן הרי זה \u0003לאו\u0004 כמו האחרים, ונלמד מהם, \u0003אי למאן דאמר\u0004 \u0005[אם ל\u0006דעת \u0005מי שאומר]\u0006 שיש בכך איסור \u0003עשה\u0004 — אם כן זה \u0003עשה\u0004 כמו אחרים.","\u0003אלא\u0004 השאלה היא: \u0003יבמה ליבם מנלן\u0004 \u0005[מניין לנו]\u0006 שהיא נקנית לו בהעראה בלבד? ומשיבים: \u0003אתיא\u0004 \u0005[בא\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה \u0003\"ביאה\" \"ביאה\",\u0004 שכן נאמר ביבמה: \"יבמה יבא עליה\" (שם כה, ה), ונאמר גם באיסורי לאוים לשון ביאה.","ומוסיפים לברר: \u0003אשה לבעלה מנלן\u0004 \u0005[מניין לנו]\u0006 שהיא נקנית לו בקידושי ביאה על ידי העראה בלבד? ומשיבים: \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה \u0003\"קיחה\" \"קיחה\",\u0004 שנאמרה קיחה בנשיאת אשה: \"כי יקח איש אשה ובעלה\" (שם כד, א) ונאמרה קיחה באיסורי עריות (כגון: \"ואיש אשר יקח את אשה ואת אמה\". ויקרא כ, יד), ולמדים שהעראה נחשבת כביאה בשני המקרים.","\u0003אמר רבא:\u0004 כיון שלמדנו שבדרך כלל העראה נחשבת כביאה גמורה, אם כן, \u0003למה לי דכתב רחמנא\u0004 \u0005[שאמרה התורה]\u0006 \u0003\"שכבת זרע\" ב\u0004ביאת \u0003שפחה חרופה\u0004 (\"ואיש אשר ישכב את אשה שכבת זרע והיא שפחה נחרפת לאיש\". שם יט, כ), וכן כתבה \u0003\"שכבת זרע\" באשת איש\u0004 (\"ואל אשת עמיתך לא תתן שכבתך לזרע\". ויקרא יח, כ), וכן כתבה \u0003\"שכבת זרע\" בסוטה\u0004 (\"ושכב איש אותה שכבת זרע\". במדבר ה, יג)?","ומסבירים: זה שנאמר ב\u0003שפחה חרופה — כדאמרן\u0004 \u0005[כפי שאמרנו],\u0006 שבא הדבר ללמד שאין חייב על שפחה חרופה אלא אם כן בא עליה ביאה גמורה, הראויה לשכבת זרע. וביטוי זה שנאמר ב\u0003אשת איש,\u0004 בא ללמד, שכל הבא על אשת איש חייב, \u0003פרט ל\u0004זה ה\u0003משמש מת,\u0004 כלומר, למי שבא על אשה בלא קישוי אבר, שאינו יכול להוליד.","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 כי ה\u0003משמש מת בעריות פטור,\u0004 שאין זו נחשבת ביאה, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שאף בזה \u0003חייב, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 \u0003אלא\u0004 לשיטה זו בא הכתוב, ללמד: \u0003פרט למשמש מתה,\u0004 שאם בועל אשה מתה אינו חייב. \u0003דסלקא דעתך אמינא\u0004 \u0005[שיעלה על דעתך לומר]\u0006 \u0003הואיל\u0004 ו\u0003לאחר מיתה נמי איקרי\u0004 \u0005[גם כן\u0006 היא \u0005קרויה]\u0006 \u0003\"שארו\",\u0004 לגבי בעלה, ואם כן \u0003אימא ליחייב עלה\u0004 \u0005[אמור שיתחייב עליה]\u0006 אחר הבא עליה משום ניאוף \u0003באשת איש,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שביאת מתה אינה קרויה ביאה, ואינו חייב עליה.","והביטוי הזה (\"שכבת זרע\") שנאמר ב\u0003סוטה למה לי? לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005],\u0006 מה שנאמר: \u0003\"\u0004ושכב איש אותה \u0003שכבת זרע\"\u0004 (שם), הרי זה \u0003פרט לדבר אחר.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"דבר אחר\"?\u0004 למה הכוונה בביטוי מרמז זה? \u0003אמר רב ששת: פרט ל\u0004מקרה \u0003שקינא לה\u0004 בעלה והזהירה שלא תיבעל לאחר ביאה \u0003שלא כדרכה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 הלא \u0003\"משכבי אשה\" כתיב\u0004 \u0005[נאמר]\u0006 בסוטה, ומכאן למדים שיש איסור בכל סוגי משכבות באשה!","\u0003אלא אמר רבא: פרט לשקינא לה\u0004 שלא תיסתר עם אחר — והזהיר אותה לא על בעילה אלא על מגע האבר \u0003דרך אברים\u0004 אחרים, ואת זה ממעט הכתוב, שאין אשה נאסרת בכך. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 וכי \u0003פריצותא אסר רחמנא\u0004 \u0005[פריצות אסרה התורה]?\u0006 שאכן דבר זה הוא בגדר פריצות, אבל איננו נכלל במונח \"ביאה\"!","\u0003אלא אמר אביי: פרט לשקינא לה\u0004 שלא תיסתר עם איש שאינו בא עליה ביאה גמורה אלא \u0003בנשיקה,\u0004 כלומר, שמשיק את איברו באיברה בנשיקה (בהשקה) — במגע בלבד. ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 \u0003העראה זו הכנסת עטרה\u0004 של איבר הזכר לתוך איבר הנקיבה. ולכן מגע (\"נשיקה\") בלבד אינו קרוי ביאה, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 העראה \u0003זו נשיקה,\u0004 ועצם המגע בלבד נקרא העראה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 איך אפשר למעט נשיקה?","\u0003אלא, לעולם\u0004 יש לחזור לפירוש ראשון, ו\"דבר אחר\" פירושו פרט \u0003לשקינא לה\u0004 ממגע אבר אדם זר \u0003דרך אברים\u0004 אחרים, \u0003ואיצטריך\u0004 \u0005[והוצרך]\u0006 הדבר להיאמר שאין זה קינוי, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003בקפידא\u0004 \u0005[ב\u0006מידת ה\u0005הקפדה]\u0006 של ה\u0003בעל תלה רחמנא\u0004 \u0005[תלתה התורה]\u0006 את הקינוי, שהרי הדבר תלוי ברצונו לקנא, \u0003והא קא קפיד\u0004 \u0005[והרי\u0006 הוא \u0005מקפיד]\u0006 גם על מגע כזה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין היא נאסרת אלא בביאה ממש.","בעניין ההגדרה המדוייקת מהי העראה, \u0003אמר שמואל: העראה זו נשיקה.\u0004 כלומר, מגע של איבר הזכר והנקיבה זה בזה, ומדוע אנחנו אומרים שהמגע הזה נחשב כביאה — \u0003משל לאדם שמניח אצבעו על פיו, אי אפשר שלא ידחוק הבשר\u0004 משהו. ולכן גם מגע האבר, אי אפשר שלא ייכנס בפנים משהו ולכן אף זה קרוי ביאה.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבה בר בר חנה\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן: גמר ביאה\u0004 האמור \u0003בשפחה חרופה — זו הכנסת עטרה\u0004 ולא יותר מזה. \u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב ששת\u0004 ממה ששנינו: כיון שנאמר בשפחה חרופה \u0003\"שכבת זרע\",\u0004 משמע ש\u0003אינו חייב\u0004 בה \u0003אלא על ביאת המירוק,\u0004 כלומר, ביאה גמורה. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה — \u0003מירוק גיד\u0004 (כל האיבר)?! ודוחים: \u0003לא,\u0004 אפשר לומר זה ש\u0003מירוק\u0004 הכוונה לגמר הכנסת \u0003עטרה\u0004 בלבד.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן\u0004 אחרת: \u0003העראה — זו הכנסת עטרה. אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003והא רבה בר בר חנה לא אמר הכי\u0004 \u0005[כך],\u0006 שהרי הוא מסר בשם ר' יוחנן שהכנסת עטרה היא ביאה גמורה! \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003או איהו שקראי\u0004 \u0005[הוא שיקר]\u0006 \u0003או אנא שקרי\u0004 \u0005[אני משקר],\u0006 כלומר, ברור שיש כאן סתירה ואחד מאיתנו לא מסר את הדברים כראוי.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן: העראה זו הכנסת עטרה.\u0004 ומעירים: על \u0003רבה בר בר חנה ודאי פליג\u0004 \u0005[\u0006הוא \u0005חולק],\u0006 שהרי רבה בר בר חנה אמר שהכנסת עטרה היא גמר ביאה, והשאלה היא: על \u0003שמואל\u0004 שאומר שהעראה זו נשיקה \u0003מי לימא פליג\u0004 \u0005[האם לומר\u0006 ש\u0005חולק\u0006 הוא\u0005]?\u0006","ודוחים: \u0003לא,\u0004 אפשר לומר שאין הם חולקים, אלא \u0003מנשיקה ועד הכנסת עטרה\u0004 — \u0003העראה קרי\u0004 \u0005[קורא]\u0006 \u0003לה\u0004 רבין בשם ר' יוחנן וביותר מזה קרוי ביאה.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב שמואל בר יהודה\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן: העראה — זו הכנסת עטרה, גמר ביאה\u0004 זה \u0003גמר ביאה ממש.\u0004"],["\u0003מכאן ואילך,\u0004 כלומר, פחות מכן — \u0003אינו אלא נשיקה, ופטור עליה. ופליג\u0004 \u0005[וחולק]\u0006 על דברי \u0003שמואל,\u0004 שלדבריו נשיקה היא העראה וחייב עליה.","שנינו במשנה: \u0003אחד המערה ואחד הגומר\u0004 — \u0003קנה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003קנה? רב אמר: קנה לכל,\u0004 כלומר, הרי זו ביאה גמורה והיא נחשבת כאשתו לכל דבר, ואם כהן הוא — רשאית לאכול בתרומה. \u0003ושמואל אמר: לא קנה\u0004 בהעראה או בשאר ביאות גרועות כיוצא בה \u0003אלא לדברים האמורים בפרשה\u0004 של ייבום, שהם: \u0003לירש בנכסי אחיו, ולפוטרה מן הייבום,\u0004 שאם מת היבם אחרי שהערה בה, והשאיר בנים מאשה אחרת, הרי היא כאשת אח שיש לו בנים ופטורה מן הייבום.","ומעירים: אם היתה יבמה \u0003מן הנשואין — לדברי הכל אכלה\u0004 \u0005[אוכלת]\u0006 גם בתרומה, כאשר בא עליה בביאה כל שהיא. \u0003דהא הות קאכלה מעיקרא\u0004 \u0005[שהרי היתה אוכלת מתחילה]\u0006 על ידי ביאת האח המת, שאף ביאה גרועה מספקת כדי להמשיך להאכילה בתרומה. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה כשהיתה יבמה \u0003מן האירוסין. רב אמר: אוכלת, דהא רבי רחמנא\u0004 \u0005[שהרי ריבתה התורה]\u0006 \u0003ביאת שוגג\u0004 שתהיה \u0003כ\u0004ביאה ב\u0003מזיד\u0004 והעראה כגמר ביאה.","\u0003ושמואל אמר: כי רבי רחמנא\u0004 \u0005[כאשר ריבתה התורה]\u0006 גם ביאה זו, הרי זה \u0003לאוקמיה\u0004 \u0005[להעמידו],\u0006 את היבם, \u0003במקום\u0004 ה\u0003בעל,\u0004 אבל \u0003לאלומי\u0004 \u0005[לחזק]\u0006 אותו יותר \u0003מן\u0004 ה\u0003בעל — לא.\u0004 וכיון שבעלה לא האכיל אותה עדיין בתרומה, שהרי היתה ארוסה בלבד — אף היבם (שלא בא עליה ביאה גמורה) אינו יכול לעשות זאת.","ומעירים: \u0003ואזדא\u0004 \u0005[והלך]\u0006 \u0003שמואל לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רב נחמן אמר שמואל: כל שהבעל מאכיל\u0004 בתרומה — גם \u0003יבם מאכיל, וכל שאין הבעל מאכיל\u0004 — גם \u0003יבם אינו מאכיל.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך, ממה ששנינו: \u0003בת ישראל פקחת\u0004 (בת דעת), שנישואיה נישואין גמורים, \u0003שנתארסה לכהן פקח, ולא הספיק לכונסה עד שנתחרש\u0004 (שנעשה חרש) ואינו עוד בן דעת גמור — \u0003אינה אוכלת\u0004 בתרומה, כי נישואיו וקניינו של החרש אינם מועילים להאכיל את אשתו בתרומה מן התורה. ואם \u0003מת\u0004 היבם החרש, \u0003ונפלה\u0004 היבמה \u0003לפני יבם חרש — אוכלת, ובזו יפה כח היבם מכח הבעל.\u0004","\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב ניחא\u0004 \u0005[נוח]\u0006 שאף שאצל הבעל החרש לא היתה אלא כארוסה ולא אכלה בתרומה, עכשיו שבא עליה היבם החרש — אוכלת, כיון שהוא קונה אותה מכוח ביאתו, שאין היא גרועה מביאת שוגג, וקניינו זה הוא קנין גמור, \u0003אלא ל\u0004שיטת \u0003שמואל קשיא\u0004 \u0005[קשה]!\u0006 שלדבריו אין כוחו של היבם יכול להיות יפה יותר מכוח הבעל שמת.","ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003שמואל: אימא הכי\u0004 \u0005[אמור\u0006 ותקן \u0005כך]\u0006 את הגירסה: \u0003ולא הספיק לכונסה עד שנתחרש — אינה אוכלת בתרומה, כנס ואחר כך נתחרש — אוכלת.\u0004 ואם לאחר שכנסה ונתחרש \u0003מת\u0004 היבם, \u0003ונפלה לפני יבם חרש — אוכלת.\u0004","\u0003ומאי\u0004 \u0005[ומה]\u0006 איפוא הכוונה של \u0003\"בזו\u0004 יפה כוח היבם\u0003\"\u0004— אין הכוונה למקרה זה דווקא, אלא בכלל, ש\u0003אילו\u0004 היה ה\u0003בעל חרש מעיקרא\u0004 \u0005[מתחילה],\u0006 \u0003לא\u0004 היתה \u0003אוכלת\u0004 בתרומה, ורק מפני שנשאה בעודו פיקח וקנאה בנישואין גמורים — אוכלת. \u0003ואילו יבם חרש מעיקרא אכלה\u0004 \u0005[מתחילה\u0006 לפני הייבום, \u0005אוכלת]\u0006 ובזה יפה כוחו.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שמחלוקת רב ושמואל היתה באופן אחר, שאם נתאלמנה \u0003מן האירוסין\u0004 ובא עליה היבם ביאה גרועה — \u0003דברי הכל לא אכלה\u0004 \u0005[אינה אוכלת],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 בעודה ארוסה \u0003לא אכלה\u0004 \u0005[אינה אוכלת]\u0006 תרומה \u0003בחיי בעל.\u0004","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו],\u0006 הרי זה כשנתאלמנה \u0003מן הנשואין\u0004 — \u0003רב אמר: אוכלת, דהא הות אכלה מעיקרא\u0004 \u0005[שהרי היתה אוכלת מתחילה],\u0006 \u0003ושמואל אמר: אינה אוכלת.\u0004 ומדוע? — \u0003כי רבי רחמנא\u0004 \u0005[כאשר ריבתה תורה]\u0006 \u0003ביאת שוגג\u0004 שתהיה \u0003כ\u0004ביאה ב\u0003מזיד\u0004 — הרי זה \u0003לדברים האמורים בפרשה\u0004 של ייבום (לירש את אחיו, ולפוטרה מיבום אם בא עליה היבם ומת מיד ולו בנים מאשה אחרת), \u0003אבל לכל מילי\u0004 \u0005[דבר]\u0006 — \u0003לא.\u0004","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב נחמן אמר שמואל\u0004 עצמו: \u0003כל שהבעל מאכיל — יבם מאכיל,\u0004 ואם כן גם פה היה צריך להאכיל! ומשיבים: \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 כך: \u0003כל ביאה שהבעל מאכיל בה — יבם מאכיל בה, וכל ביאה שאין הבעל מאכיל בה — אין היבם מאכיל בה.\u0004 ולכן ביאת שוגג וכיוצא בה, שאין עושה קנין של קידושין על ידי ביאה זו, אף היבם אינו מאכיל בה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך מן הברייתא: \u0003בת ישראל פקחת שנתארסה לכהן פקח, ולא הספיק לכונסה עד שנתחרש — אינה אוכלת. מת, ונפלה לפני יבם חרש — אוכלת, ובזו יפה כח יבם מכח בעל. בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב\u0004 — \u0003מתרץ כדתריץ מעיקרא\u0004 \u0005[כפי שתירץ בתחילה]\u0006 לשיטתו של שמואל, שתיקנו את הגירסה. \u0003אלא ל\u0004שיטת \u0003שמואל\u0004 לפי נוסח זה \u0003קשיא\u0004 \u0005[קשה]!\u0006 ומסכמים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בת ישראל פקחת שנתארסה לכהן פקח ולא הספיק לכונסה עד שנתחרש — אינה אוכלת\u0004 בתרומה. \u0003נולד לה בן\u0004 מן הכהן — \u0003אוכלת\u0004 בתרומה, בגלל בנה. \u0003מת הבן\u0004 — \u0003ר' נתן אומר: אוכלת, וחכמים אומרים: אינה אוכלת.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' נתן? אמר רבה: הואיל שכבר אכלה\u0004 בהיתר בעוד בנה בחיים, מתירים לה שתהא אוכלת גם הלאה כיון שבכל זאת היא נשואה לכהן נישואין כל שהם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה,\u0004 לפי נימוק זה, \u0003בת ישראל שניסת לכהן ומית ליה\u0004 \u0005[ומת לו]\u0006 בלי בנים, \u0003תיכול\u0004 \u0005[תאכל]\u0006 בתרומה, משום \u0003שכבר אכלה! אלא\u0004 ודאי הוא כי \u0003כיון דמית ליה\u0004 \u0005[שמת לו]\u0006 \u0003פקע ליה קדושתיה מינה\u0004 \u0005[פקעה לה קדושתו ממנה],\u0006 ושוב אין עליה קדושת כהונה, והיא כבת ישראל לכל דבר. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003כיון דמית ליה\u0004 \u0005[שמת לו\u0006 הבן\u0005]\u0006 \u0003פקע קדושתיה מינה\u0004 \u0005[פקעה קדושתו\u0006 של הכהן \u0005ממנה],\u0006 ולכן לא תאכל בתרומה! ונדחה טעמו של רבה.","\u0003אלא אמר רב יוסף: קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' נתן\u0004 כי \u0003נשואי חרש\u0004 שקידש אשה כשהוא פיקח \u0003מאכילין\u0004 מן התורה \u0003בתרומה,\u0004 אף שמגזירת חכמים אינה אוכלת אלא משעת הנישואין, כיון שיש לחשוש שמא תאכיל מן התרומה לאחיה — במקרה כזה שקידשה כשהוא פיקח וכבר נישאה ואין מקום לחשש זה, לא גזרו בו חכמים, \u0003ולא גזרינן\u0004 \u0005[ואין אנו גוזרים]\u0006 \u0003נשואי חרש\u0004 וביאתו \u0003אטו\u0004 \u0005[בגלל]\u0006 \u0003קדושי חרש.\u0004 שאמנם קידושי חרש אינם קונים, כיון שאין בו דעת, אבל לאחר שקידשה כשהוא בן דעת, אף שנתחרש — הנישואין מועילים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אי הכי\u0004 \u0005[אם כך]\u0006 וזה הוא הנימוק, \u0003נולד לה בן למה לי?\u0004 שהרי לדעת ר' נתן אוכלת בתרומה גם אם לא נולד בן! השיב לו: \u0003משום רבנן\u0004 \u0005[\u0006דברי \u0005חכמים]\u0006 אמר זאת. שאמנם לדעת ר' נתן עצמו אין הבדל, אבל לדעת חכמים יש הבדל אם היה או לא היה לה בן.","וחזר והקשה: \u0003וליפלוג\u0004 \u0005[ושיחלוק]\u0006 \u0003ר' נתן עלייהו ברישא\u0004 \u0005[עליהם בתחילה],\u0006 גם בקטע הראשון, לפני שהוזכר המקרה שנולד לה בן! ענה לו רב יוסף: \u0003שביק להו לרבנן עד דמסיימי מילתייהו והדר פליג עלייהו\u0004 \u0005[הניח להם\u0006 ר' נתן \u0005לחכמים עד שיסיימו את דבריהם וחזר\u0006 אחר כך ו\u0005חלק עליהם\u0006 בכול\u0005].\u0006 ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 וזה הוא הטעם, \u0003ליתני\u0004 \u0005[שישנה]\u0006 קודם \u0003מת הבן אינה אוכלת,\u0004 ואחר כך \u0003ר' נתן אומר: אוכלת,\u0004 ולמה הקדים קודם את דברי ר' נתן, היה לו להניח קודם לחכמים לסיים לגמרי את דבריהם! ומסכמים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 לדעת רב יוסף.","שנינו במשנה: \u0003וכן הבא על אחת מכל העריות\u0004 שבתורה, אפילו בביאה כל שהיא — חייב. \u0003אמר רב עמרם: הא מלתא\u0004 \u0005[דבר זה]\u0006 \u0003אמר לן\u0004 \u0005[לנו]\u0006 \u0003רב ששת,\u0004"],["\u0003ואנהרינהו לעיינין ממתניתין\u0004 \u0005[והאיר את עינינו ממשנתנו]\u0006 להראות שדבריו נסמכים עליה. וכך אמר רב ששת: \u0003אשת ישראל שנאנסה, אף על פי שמותרת לבעלה,\u0004 אם ישראל הוא — \u0003פסולה לכהונה,\u0004 שאם מת בעלה — לא תינשא עוד לכהן. \u0003ותנא תונא\u0004 \u0005[ושנה התנא\u0006 שלנו\u0005]:\u0006 \u0003וכן הבא על אחת מכל העריות האמורות בתורה, או פסולות.\u0004","\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"וכן\"? מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה ש\u0003לא שנא\u0004 \u0005[שונה]\u0006 אם היה הדבר \u0003בשוגג, ולא שנא\u0004 \u0005[שונה]\u0006 אם היה הדבר \u0003במזיד, ו\u0004כן \u0003לא שנא\u0004 \u0005[שונה]\u0006 אם היה הדבר \u0003באונס, ולא שנא\u0004 \u0005[שונה]\u0006 אם היה הדבר \u0003ברצון, וקתני\u0004 \u0005[ושנה]:\u0006 \u0003פסלה.\u0004 משמע, שביאה מכל סוג, גם אם היתה באונס — פוסלת. ואף על פי שאינה אוסרת לישראל — פוסלת לכהנים.","את הראיה הזו דוחים: \u0003לא,\u0004 אין הכוונה פה לביאת שוגג ומזיד וכיוצא באלה, אלא לסוגי הביאה. ו\u0003מאי\u0004 \u0005[\u0006ו\u0005מה\u0006 פירוש\u0005]\u0006 \u0003\"וכן\" — על העראה,\u0004 שגם היא פוסלת. ושואלים: \u0003העראה דמאן\u0004 \u0005[של מי],\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 של \u0003עריות, למימרא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 שדיני העראה ב\u0003עריות ילפינן\u0004 \u0005[למדים אנו]\u0006 \u0003מיבמה?\u0004 — \u0003אדרבה\u0004 (להיפך) \u0003יבמה ילפינן\u0004 \u0005[למדים אנו]\u0006 \u0003מעריות,\u0004 ש\u0003עיקר\u0004 ענין \u0003העראה בעריות כתיב\u0004 \u0005[נאמר]\u0006 ולא בדיני יבמות!","\u0003אלא,\u0004 חוזרים מן הפירוש הקודם, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"וכן\" —\u0004 על ביאה \u0003שלא כדרכה\u0004 של \u0003עריות.\u0004 ודוחים: \u0003אדרבה, עיקר \"משכבי אשה\"\u0004 שמשם לומדים על ביאה שלא כדרכה \u0003בעריות כתיב\u0004 \u0005[נאמר]\u0006 ולא ביבמה!","\u0003אלא, מאי \"וכן\"\u0004 בענין ביאה \u0003שלא כדרכה\u0004 ב\u0003חייבי לאוין,\u0004 שבהם לא נתפרש הדבר בכתוב.","\u0003אמר רבא: אשת כהן שנאנסה,\u0004 אם יבוא עליה \u0003בעלה\u0004 הכהן לאחר מכן — \u0003לוקה עליה משום זונה.\u0004 ותוהים: \u0003משום זונה אין\u0004 \u0005[כן],\u0006 \u0003משום טומאה לא?\u0004 שהרי היא אסורה לו גם משום טומאה כמו כל אשה שנאסרה לבעלה אחרי שנבעלה על ידי אחר, שנקראת בתורה טמאה! ומתקנים: \u0003אימא\u0004 \u0005[אמור]\u0006 לוקה \u0003אף משום זונה.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003ר' זירא,\u0004 נאמר בסוטה: \u0003\"והיא לא נתפשה\"\u0004 (במדבר ה, יג), כלומר, זו שלא נתפסה (שלא נאנסה) — \u0003אסורה, הא\u0004 \u0005[הרי]\u0006 אם \u0003נתפשה\u0004 (נאנסה) — \u0003מותרת.\u0004 וכיון שכתוב \"והיא\" לשון דיוק וצמצום, הרי זה בא ללמד: \u0003ויש לך אחרת שאף על פי שנתפשה\u0004 בכוח ונאנסה — \u0003אסורה. ואי זו — זו אשת כהן.\u0004","\u0003ו\u0004אם כן האיסור באשת כהן שנאנסה הוא \u0003לאו הבא מכלל עשה,\u0004 וכלל הוא שאינו אלא \u0003עשה\u0004 ולא איסור לאו. וכיון שאין בטומאה זו לאו — אין לוקים עליה!","\u0003אמר רבא\u0004 באופן אחר: \u0003הכל,\u0004 כל הנשים הנשואות שנבעלו תחת בעליהן, \u0003היו בכלל זונה,\u0004 שכל אשה שנבעלה (ברצון או באונס) בעילה שיש בה חיוב כרת — קרויה זונה, ו\u0003כשפרט לך הכתוב גבי\u0004 (אצל) \u0003אשת ישראל \"והיא לא נתפשה\"\u0004 לומר שהיא \u0003אסורה, הא\u0004 \u0005[הרי]\u0006 אם כן \u0003נתפשה — מותרת. מכלל\u0004 הדברים אתה למד כי \u0003אשת כהן\u0004 שנאסרה, כיון שלא הותרה — \u0003כדקיימא קיימא\u0004 \u0005[כמו שעמדה עמדה]\u0006 ולא בטל ממנה איסור זונה.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 בלשון אחרת, \u0003אמר רבה: אשת כהן שנאנסה\u0004 — \u0003בעלה לוקה עליה משום טומאה.\u0004 ושואלים: \u0003משום טומאה אין\u0004 \u0005[כן]\u0006 \u0003משום זונה לא? אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003באונס לא קרינא ביה\u0004 \u0005[אין קוראים אנו בכך]\u0006 \u0003זונה.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003ר' זירא\u0004 ממה ששנינו \u0003\"והיא לא נתפשה\",\u0004 כלומר, זו שלא נאנסה \u0003— אסורה, הא\u0004 \u0005[הרי]\u0006 זו ש\u0003נתפשה — מותרת. ויש לך אחרת, שאף על פי שנתפשה אסורה, ואיזו — זו אשת כהן. ולאו הבא מכלל עשה — עשה,\u0004 משמע שיש עליה איסור עשה בלבד, ולא איסור לאו שלוקים עליו!","\u0003אמר רבא: הכל,\u0004 כל הנשים הנשואות שנבעלו תחת בעליהן, \u0003היו בכלל \"\u0004לא יוכל בעלה... לשוב לקחתה... \u0003אחרי אשר הטמאה\"\u0004 (דברים כד, ד), \u0003כשפרט לך הכתוב גבי\u0004 (אצל) \u0003אשת ישראל \"והיא לא נתפשה\" אסורה, הא\u0004 \u0005[הרי]\u0006 אם \u0003נתפשה מותרת, מכלל\u0004 הדברים אתה למד כי \u0003אשת כהן כדקיימא קיימא\u0004 \u0005[כמו שעמדה עמדה]\u0006 ונשארה באיסור טומאה, ויש על בעלה לאו של \"לא ישוב לקחתה\".","\u0003אלמנה לכהן גדול, גרושה וחלוצה לכהן הדיוט,\u0004 אפילו \u0003מן האירוסין\u0004 בלבד, שעדיין לא באו עליהם, אם היו בנות כהנים — \u0003לא יאכלו בתרומה\u0004 שקידושין כאלה מחללים את הנשים מקדושת כהונה, שהרי הן אסורות למקדשיהן. \u0003ר' אלעזר ור' שמעון מכשירין\u0004 בארוסות, משום שאין העבירה נעשית אלא בביאה, וכל עוד שלא באו עליהן — לא נתחללו.","אם נשים אלה \u0003נתארמלו\u0004 (נתאלמנו) \u0003או נתגרשו,\u0004 אם היה זה \u0003מן הנשואין — פסולות\u0004 לכהונה, ופסולות מלאכול בתרומה שהרי על ידי הביאה נעשו חללות. אם נתאלמנו או נתגרשו \u0003מן האירוסין — כשרות.\u0004","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' מאיר: קל וחומר\u0004 הוא, \u0003ומה קדושי רשות\u0004 כגון ישראל המקדש בת כהן — \u0003אין מאכילין\u0004 בה, שכן היא נפסלת מלאכול בתרומת אביה על ידי קידושיה לשאינו כהן — \u0003קדושי עבירה\u0004 שמקדשה כהן שהיא אסורה לו \u0003לא כל שכן\u0004 שפוסלים אותה מלאכול תרומה?!","\u0003אמרו לו: לא,\u0004 אין מכאן ראיה. \u0003אם אמרת בקידושי רשות — שכן אין לו להאכיל במקום אחר,\u0004 שהרי ישראל זה אינו יכול להאכיל את הכהנת בתרומה בכל מקרה, שהרי ישראל הוא, \u0003תאמר בקדושי עבירה, שכן יש לו\u0004 לאותו כהן יכולת \u0003להאכיל במקום אחר,\u0004 שאם לא היתה אשה זו אסורה לו — היה מאכיל אותה בתרומה. ולכן אפשר לומר שקידושי הכהן לבדם אינם פוסלים אותה לאכול בתרומה אפילו כשהיו בעבירה.","\u0003אמר ר' אלעזר אמר ר' אושעיא: פצוע דכא כהן שקדש בת ישראל\u0004 שאסור לו לבוא עליה, שנאמר: \"לא יבוא פצוע דכה... בקהל ה'\" (שם כג, ב), \u0003באנו\u0004 בענין זה \u0003למחלוקת ר' מאיר ור' אלעזר ור' שמעון.\u0004 וכיצד?","\u0003לר' מאיר\u0004 ש\u0003אמר: משתמרת\u0004 (ממתינה, מוכנה) \u0003לביאה פסולה דאורייתא\u0004 \u0005[מן התורה],\u0006 כלומר, אשה שנתקדשה לאדם שאם תיבעל לו תהא זו ביאה פסולה מן התורה \u0003לא אכלה\u0004 \u0005[אינה אוכלת]\u0006 בתרומה, אם כן \u0003הא נמי לא אכלה\u0004 \u0005[זו גם כן אינה אוכלת]\u0006 שהרי ביאתו של פצוע דכא פוסלת אותה. ו\u0003לר' אלעזר ור' שמעון דאמרי\u0004 \u0005[שאומרים]\u0006 כי זו ה\u0003משתמרת לביאה פסולה דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003אכלה\u0004 \u0005[אוכלת]\u0006 בתרומה כל זמן שלא נבעלה ונפסלה,"],["\u0003הא נמי אכלה\u0004 \u0005[זו גם כן אוכלת],\u0006 שעד שאינו בועל אותה ראוי הוא להאכילה בתרומה. ודוחים: \u0003ממאי\u0004 \u0005[ממה,\u0006 מניין\u0005]\u0006 מסיק אתה דברים אלה? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי\u0004 \u0005[אמרו]\u0006 \u0003ר' אלעזר ור' שמעון התם\u0004 \u0005[שם]\u0006 \u0003אלא\u0004 באותם כהנים ש\u0003יש לו להאכיל במקום אחר,\u0004 שהרי אם נושא אשה כשרה הוא מאכילה בתרומה. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בפצוע דכא ש\u0003אין לו להאכיל במקום אחר,\u0004 שהרי אסור לו לשאת אשה מקהל ה' — \u0003לא.\u0004","\u0003וכי תימא: הכא נמי\u0004 \u0005[ואם תאמר כאן גם כן]\u0006 \u0003יש לו להאכיל\u0004 על כל פנים \u0003בבת גרים,\u0004 שכיון שאינה מקהל ישראל רשאי פצוע דכא לשאתה, \u0003ו\u0004אולם \u0003הא מיבעיא בעי ליה\u0004 \u0005[והרי שאל אותה]\u0006 \u0003ר' יוחנן מר' אושעיא ולא פשיט ליה\u0004 \u0005[פתר לו]\u0006 אם פצוע דכא כהן שנשא בת גרים מאכילה בתרומה. ואם כן יש לחלק בין פצוע דכא לשאר כהנים המקדשים נשים הנפסלות בביאתם.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 בפתרון הבעיה בענין פצוע דכא כהן, \u0003אביי אמר:\u0004 יכול הוא להאכיל את ארוסתו, \u0003הואיל\u0004 ויש אופן ש\u0003מאכילה\u0004 כש\u0003לא ידעה.\u0004 שכהן שהיה נשוי לאשה בכשרות, ונעשה פצוע דכא, אם לא ידעה (לא בא עליה) מאז (שאם בא עליה הריהו פוסל אותה כחללה) — ממשיכה היא לאכול בתרומה כאשתו.","\u0003רבא אמר\u0004 שאוכלת מטעם אחר: \u0003הואיל ו\u0004כהן זה \u0003מאכיל\u0004 על כל פנים \u0003בעבדיו ושפחותיו הכנענים.\u0004 וכיון שיש לו כוח להאכיל אחרים, שהרי עבדיו אוכלים בתרומה — אף את ארוסתו יכול הוא להאכיל בתרומה מאותו טעם.","ומסבירים את שיטותיהם: \u0003אביי לא אמר כרבא,\u0004 כי \u0003קנין\u0004 של \u0003אישות מקנין\u0004 של \u0003אישות ילפינן\u0004 \u0005[לומדים אנו],\u0006 \u0003ולא ילפינן\u0004 \u0005[ואיננו לומדים]\u0006 \u0003קנין\u0004 של \u0003אישות מקנין\u0004 של \u0003עבדים.\u0004","\u0003ורבא לא אמר כאביי,\u0004 וטעמו: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 כשלא בא עליה מאז שנעשה פצוע דכא, \u0003שכבר אכלה\u0004 קודם לכן, לפני שנעשה פצוע דכא, ולכן היא ממשיכה לאכול. \u0003ואביי\u0004 הלא כבר אמר שלדעתו הנימוק \u0003שכבר אכלה לא אמרינן\u0004 \u0005[אין אנו אומרים].\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך]\u0006 שאין בטעם זה ממש. אם כן \u0003בת ישראל שניסת לכהן ומית\u0004 \u0005[ומת]\u0006 בלא בנים \u0003תיכול\u0004 \u0005[תאכל]\u0006 בתרומה מן הטעם \u0003ש\u0004הרי \u0003כבר אכלה. ורבא\u0004 משיב שאין להשוות את הדברים: \u0003התם\u0004 \u0005[שם]\u0006 כשמת \u0003פקע קניניה\u0004 \u0005[קניינו],\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003לא פקע קניניה\u0004 \u0005[קניינו],\u0006 שעדיין היא אשתו.","הזכרנו קודם את השאלה ששאל ר' יוחנן מר' אושעיא, ומעתה דנים בה \u0003גופא\u0004 \u0005[לגופה],\u0006 \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' יוחנן מר' אושעיא: פצוע דכא כהן שנשא בת גרים. מהו שיאכילנה בתרומה? אישתיק\u0004 \u0005[שתק]\u0006 \u0003ולא אמר ליה\u0004 \u0005[לו]\u0006 \u0003ולא מידי\u0004 \u0005[כלום],\u0006 שלא מצא תשובה לשאלתו. \u0003לסוף אתא גברא רבה אחרינא ובעא מיניה מילתא אחריתא ופשט ליה\u0004 \u0005[ל\u0006ב\u0005סוף בא אדם גדול אחר ושאל ממנו דבר אחר ופתר לו]\u0006 ר' אושעיא את שאלתו. \u0003ומנו\u0004 \u0005[ומי]\u0006 היה זה השואל האחר — \u0003ריש לקיש. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יהודה נשיאה\u0004 \u0005[הנשיא]\u0006 \u0003לר' אושעיא: אטו\u0004 \u0005[האם]\u0006 \u0003ר' יוחנן לאו גברא רבה\u0004 \u0005[לא אדם גדול]\u0006 \u0003הוא,\u0004 שאין אתה רואה צורך לענות לשאלותיו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דקבעי מינאי מילתא דלית לה פתרי\u0004 \u0005[ששאל ממני דבר שאין לו פתרון]\u0006 ולכן לא יכולתי לענות על שאלתו.","ומסבירים: \u0003למאן\u0004 \u0005[ל\u0006דעת \u0005מי],\u0006 לפי איזו שיטה היתה שאלה זו; \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004דעת \u0003ר' יהודה,\u0004 אם כן, \u0003בין\u0004 אם כהן זה הפצוע דכא \u0003בקדושתיה קאי\u0004 \u0005[בקדושתו עומד]\u0006 \u0003בין לאו בקדושתיה קאי\u0004 \u0005[\u0006ש\u0005אינו עומד בקדושתו],\u0006 שאינו קדוש עוד בקדושת כהונה, ומותר לו לשאת נשים האסורות לכהנים, מכל מקום — \u0003לא אכלה\u0004 \u0005[אוכלת]\u0006 בתרומה. וכך טעמם של דברים: \u0003אי בקדושתיה קאי, לא אכלה\u0004 \u0005[אם בקדושתו עומד, אינה אוכלת],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003בת גר זכר\u0004 דינה \u0003כבת חלל זכר\u0004 ואסורה לכהן, וממילא אינה יכולה לאכול בתרומה.","וגם \u0003אי לאו בקדושתיה קאי, לא אכלה\u0004 \u0005[אם אינו עומד בקדושתו, אינה אוכלת],\u0006 \u0003דהא אמרינן\u0004 \u0005[שהרי אומרים אנו]\u0006 לשיטת ר' יהודה: \u0003קהל גרים איקרי\u0004 \u0005[נקרא]\u0006 \u0003קהל,\u0004 וכל האיסורים לבוא בקהל ה' כוללים גם גרים, ולכן אסור לפצוע דכא לשאת אותה מטעם זה.","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003ל\u0004שיטת \u0003ר' יוסי\u0004 — \u0003בין בקדושתיה קאי\u0004 \u0005[\u0006ש\u0005עומד בקדושתו]\u0006 \u0003בין לאו בקדושתיה קאי\u0004 \u0005[\u0006ש\u0005לא\u0006 \u0005עומד בקדושתו] —\u0006 \u0003אכלה\u0004 \u0005[\u0006היא \u0005אוכלת],\u0006 \u0003בקדושתיה קאי\u0004 — \u0003אכלה\u0004 \u0005[\u0006אם \u0005בקדושתו עומד\u0006 — \u0005אוכלת],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר\u0004 ר' יוסי: \u0003אף גר שנשא גיורת — בתו כשרה לכהונה,\u0004 וכל שכן אם נשא בת ישראל, ואם כן מותר לכהן לשאת אותה. \u0003אי לאו בקדושתיה קאי אכלה\u0004 \u0005[\u0006ו\u0005אם לא עומד בקדושתו\u0006 — היא \u0005אוכלת],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר\u0004 ר' יוסי: \u0003קהל גרים לא איקרי\u0004 \u0005[נקרא]\u0006 \u0003קהל\u0004 וכל האסורים לבוא בקהל — מותרים בגרים.","\u0003אלא\u0004 יש לומר כי \u0003אליבא דהאי תנא\u0004 \u0005[לפי שיטתו של תנא זה]\u0006 שאל ר' יוחנן, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר: אשה בת גרים לא תנשא לכהונה עד שתהא אמה מישראל.\u0004","\u0003והכי קמיבעיא ליה\u0004 \u0005[וכך נסתפקה לו],\u0006 שתוכנה הפנימי של השאלה היה: גיורת זו שאימה מישראל, ומותרת להינשא לכהונה, האם הטעם הוא כי \u0003כשרות מיתוספא\u0004 \u0005[נוספה]\u0006 \u0003בה,\u0004 שחשש הפסול שיש בגיורת גמורה אינו קיים בה, והיא נעשית כשרה גם לכהן, אבל מכל מקום אינה נחשבת \"קהל ה\"' ומותרת לפצוע דכא, \u0003ו\u0004לכן \u0003אכלה\u0004 \u0005[ואוכלת]\u0006 משום כך בתרומה, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003קדושה מיתוספא\u0004 \u0005[נוספה]\u0006 \u0003בה\u0004 שהיא נכנסת אז לקדושת \"קהל ה'\" \u0003ו\u0004ממילא \u0003לא אכלה\u0004 \u0005[אוכלת]\u0006 בתרומה משום שפצוע דכא אסור בקהל ה'.","לשאלה זו מציעים פתרון, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003ר' אחא בר חיננא מדרומא\u0004 \u0005[מן הדרום],\u0006 \u0003אתא ואייתי מתניתא בידיה\u0004 \u0005[בא והביא ברייתא\u0006 זו \u0005בידו]:\u0006 \u0003מנין לפצוע דכא כהן שנשא בת גרים שמאכילה בתרומה — שנאמר \"וכהן כי יקנה נפש קנין כספו\u0004 הוא \u0003יאכל בו\"\u0004 (ויקרא כב, יא), ואף אשה קרויה לענין זה \"קנין כספו\", ואוכלת בתרומה.","ומעתה נברר \u0003למאן\u0004 \u0005[ל\u0006שיטת \u0005מי]\u0006 נאמרה ברייתא זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ל\u0004שיטת \u0003ר' יהודה — האמר\u0004 \u0005[הרי אמר]\u0006 כי \u0003בין\u0004 שכהן זה \u0003בקדושתיה קאי\u0004 \u0005[עומד בקדושתו]\u0006 \u0003בין לאו בקדושתיה קאי\u0004 \u0005[\u0006ש\u0005לא\u0006 \u0005עומד בקדושתו]\u0006 \u0003לא אכלה\u0004 \u0005[אוכלת],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003ל\u0004שיטת \u0003ר' יוסי — למה לי קרא\u0004 \u0005[כתוב]\u0006 מיוחד ללמוד על כך, \u0003האמר\u0004 \u0005[הרי אמר]\u0006 כי \u0003בין\u0004 שכהן זה \u0003בקדושתיה קאי\u0004 \u0005[עומד בקדושתו]\u0006 \u0003בין לאו בקדושתיה קאי\u0004 \u0005[\u0006ש\u0005לא\u0006 \u0005עומד בקדושתו]\u0006 \u0003אכלה\u0004 \u0005[אוכלת]!\u0006 \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003ל\u0004דעת \u0003ר' אליעזר בן יעקב\u0004 נאמר הדבר, \u0003ושמע מינה\u0004 \u0005[ולמד ממנה,\u0006 מכאן\u0005]\u0006 כי רק \u0003כשרות איתוספא\u0004 \u0005[נוספה]\u0006 \u0003בה ואכלה\u0004 \u0005[ו\u0006היא \u0005אוכלת]\u0006 בתרומה. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הדבר.","אגב עיוננו בנושא זה מביאים מחלוקת בנושא קרוב: \u0003איתמר\u0004 \u0005[נאמר]\u0006 שחלקו אמוראים בשאלה הבאה, \u0003רב אמר:\u0004"],["\u0003יש חופה לפסולות.\u0004 שאם לקח כהן אשה האסורה לו והיא בת כהן, והכניסה לחופה בלא שקידשה קודם לכן, אף שלא בא עליה, הרי עצם הכניסה לחופה עושה אותה כנשואה לו, והיא נפסלת משעה זו לכהונה ונאסרת לאכול בתרומת אביה. \u0003ושמואל אמר: אין חופה לפסולות.\u0004 שעצם הכנסת נשים פסולות לחופה, אינה פוסלת, אלא ביאה בלבד היא שפוסלת אותן.","\u0003אמר שמואל: ומודה לי אבא\u0004 (רב, ששמו הפרטי היה אבא) \u0003בתינוקת פחותה מבת שלש שנים ויום אחד,\u0004 שאף שיכול אביה לקדשה, והיא נחשבת כארוסה לכל דבר, מכל מקום, גם אם נכנסה לחופה, אינה נפסלת, שהרי הטעם לפוסלה בחופה הוא משום שלאחר החופה עתיד לבוא עליה, וזו \u0003הואיל ואין לה ביאה,\u0004 שאף אם יבוא עליה אין בכך כלום, שהרי ביאת הפחותה מבת שלוש אינה נחשבת כביאה כלל, כל שכן ש\u0003אין לה חופה,\u0004 שאין חופתה נחשבת כנישואין.","\u0003אמר רבא: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 כך, שבפחות מבת שלוש שנים אין ביאה וחופה נחשבות. ששנינו: \u0003בת שלש שנים ויום אחד — מתקדשת בביאה, ואם בא עליה יבם — קנאה, וחייבין עליה\u0004 אדם אחר הבא עליה, אם היתה נשואה, \u0003משום אשת איש, ומטמאה את בועלה\u0004 אם היתה נידה \u0003לטמא משכב תחתון כעליון.\u0004 שיש טומאה מיוחדת בבא על הנידה יותר מאשר במגע בה בלבד, שהבא עליה מיטמא כנידה עצמה.","ואם \u0003נשאת לכהן — אוכלת בתרומה.\u0004 ואם \u0003בא עליה אחד מכל הפסולין\u0004 שפוסלים לכהונה בביאתם, כגון חלל — \u0003פסלה\u0004 מן התרומה.","ונדייק מכאן: \u0003בת שלש שנים ויום אחד הוא דמפסלה\u0004 \u0005[שנפסלת]\u0006 \u0003בביאה\u0004 — ולכן גם \u0003מפסלה\u0004 \u0005[נפסלת]\u0006 \u0003בחופה. הא\u0004 \u0005[הרי]\u0006 \u0003פחותה מבת שלש שנים ויום אחד,\u0004 ש\u0003לא מפסלה\u0004 \u0005[נפסלת]\u0006 \u0003בביאה\u0004 — \u0003לא מפסלה נמי\u0004 \u0005[נפסלת גם כן]\u0006 \u0003בחופה,\u0004 שהרי לא שנה שום פרט לגבי פחות מבת שלוש שנים שתהא ביאתה נחשבת. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה].\u0006","\u0003אמר רמי בר חמא:\u0004 בשאלה זו אם \u0003יש חופה לפסולות — באנו\u0004 בעצם \u0003למחלוקת ר' מאיר ור' אלעזר ור' שמעון\u0004 של משנתנו, והדברים קשורים זה בזה."],["\u0003לר' מאיר\u0004 ש\u0003אמר\u0004 כי \u0003קדושין פסלי\u0004 \u0005[פוסלים],\u0006 אם כן \u0003חופה נמי פסלה\u0004 \u0005[גם כן פוסלת].\u0006 \u0003לר' אלעזר ור' שמעון דאמרי\u0004 \u0005[שאומרים]\u0006 כי \u0003קדושין לא פסלי\u0004 \u0005[פוסלים],\u0006 אם כן \u0003חופה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא פסלה\u0004 \u0005[פוסלת].\u0006","את ההסבר הזה דוחים: \u0003וממאי\u0004 \u0005[וממה,\u0006 מהיכן\u0005]\u0006 מסיק אתה שזו דעתם בענין חופה? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' מאיר התם\u0004 \u0005[שם]\u0006 \u0003אלא בקדושין, דקני לה\u0004 \u0005[שקונים אותה]\u0006 ולכן הם פוסלים אותה, \u0003אבל חופה\u0004 ש\u0003לא קנה לה\u0004 \u0005[קונה אותה]\u0006 — \u0003לא,\u0004 שכן חופה כשלעצמה אין בה משום קנין, ולכן יש לומר שחופה בלבד אינה פוסלת.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לומר מצד שני: \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי\u0004 \u0005[אמרו]\u0006 \u0003ר' אלעזר ור' שמעון התם\u0004 \u0005[שם]\u0006 \u0003אלא בקדושין, דלא קריבי\u0004 \u0005[שאינם קרובים]\u0006 \u0003לביאה,\u0004 ואינה נפסלת משום הקידושין עצמם, ומאחר שהם קנין הם מכשירים אותה לאכול בתרומה, \u0003אבל חופה דקריבא\u0004 \u0005[שקרובה]\u0006 \u0003לביאה,\u0004 שכן החופה היא מקום הייחוד של הבעל והאשה, והוא ענין \"כניסה\" של האשה לבית בעלה — \u0003הכי נמי דפסלה\u0004 \u0005[כך גם כן שפוסלת].\u0006","\u0003אלא אי איכא למימר\u0004 \u0005[אם יש לומר]\u0006 שנושא זה כבר נידון על ידי ראשונים, הרי הוא \u0003בפלוגתא דהני תנאי\u0004 \u0005[במחלוקת של תנאים אלה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003נישאו זו וזו,\u0004 כלומר, \u0003כשרות ופסולות\u0004 שנישאו לכהן, \u0003או שנכנסו לחופה ולא נבעלו — אוכלות משלו, ואוכלות\u0004 גם \u0003בתרומה.\u0004","מתחילה מתקנים את לשון הברייתא כדי להעמידה בגירסה נכונה. נאמר \u0003נכנסו\u0004 לחופה ולא נבעלו, \u0003מכלל\u0004 הדברים אתה למד \u0003ש\u0004האמור קודם \u0003\"נישאו\"\u0004 כוונתו — \u0003נישאו ממש?!\u0004 אולם אי אפשר לומר כך, שאם נישאו ונבעלו ממש — ודאי שנפסלו על ידי ביאה פסולה זו ואינן יכולות לאכול בתרומה.","\u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 יש לפרש כך: לא בשני עניינים אלא בענין אחד, נישאו — \u0003כגון שנכנסו לחופה ולא נבעלו. וקתני\u0004 \u0005[ושנה]\u0006 שם: \u0003אוכלות משלו ואוכלות בתרומה,\u0004 משמע שכניסתן לחופה (אף שביאתן תפסול אותן) אינה פוסלת אותן לאכול בתרומה.","ואילו \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה אומר: כל שביאתה מאכילתה\u0004 בתרומה — \u0003חופתה מאכילתה, וכל שאין ביאתה מאכילתה — אין חופתה מאכילתה.\u0004 משמע שהם חלוקים ממש בשאלה זו, אם יש חופה או אין חופה לפסולות.","ודוחים: \u0003ממאי\u0004 \u0005[ממה,\u0006 מהיכן\u0005]\u0006 מסיק אתה זאת? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה כ\u0004שיטת \u0003ר' מאיר סבירא ליה\u0004 \u0005[סבור הוא]?\u0006 ש\u0003אמר,\u0004 שב\u0003קדושין\u0004 של אשה המשתמרת לביאה פסולה \u0003לא אכלה\u0004 \u0005[אינה אוכלת],\u0006 שעצם הקידושין אינם מאכילים אותה בתרומה,","ותוהים: איך אפשר לומר כן? אם כן \u0003האי\u0004 \u0005[זה]\u0006 הביטוי בברייתא, \u0003\"כל שאין ביאתה מאכילתה אין חופתה מאכילתה\"\u0004 אינו מתאים לשיטה זו, כי \u0003\"כל שאין ביאתה מאכילתה אין כספה\u0004 (כסף קידושיה) \u0003מאכילתה\" מיבעי ליה\u0004 \u0005[צריך\u0006 היה \u0005לו]\u0006 לומר, שהרי לדעת ר' מאיר זה עיקר הטעם! ודוחים: זו אינה ראיה, כי \u0003דלמא, איידי\u0004 \u0005[שמא מתוך]\u0006 ש\u0003אמר\u0004 ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003חופה — אמר איהו נמי\u0004 \u0005[הוא גם כן]\u0006 \u0003חופה,\u0004 אבל לאמיתו של דבר הכוונה היא שנפסלה כבר משעת הקידושין.","\u0003אמר רב עמרם: הא מילתא אמר לן\u0004 \u0005[דבר זה אמר לנו]\u0006 \u0003רב ששת, ואנהרינהו לעיינין ממתניתין\u0004 \u0005[והאיר עינינו ממשנתנו]\u0006 שבה מרומז הדבר, וכך אמר: \u0003יש חופה לפסולות.\u0004 שאם לקח כהן אשה האסורה לו והיא בת כהן, והכניסה לחופה בלא שקידשה קודם לכן, אף שלא בא עליה, הרי עצם הכניסה לחופה עושה אותה כנשואה לו, והיא נפסלת משעה זו לכהונה ונאסרת לאכול בתרומת אביה. \u0003ותנא תונא\u0004 \u0005[ושנה\u0006 ה\u0005תנא\u0006 שלנו\u0005]\u0006 שהסוטה, כאשר מביאים אותה לבית המקדש לשתות את המים המרים, היא עונה \u0003אמן,\u0004 על השבעת הכהן שמשביע אותה שלא זינתה. ופירושו: אמן \u0003שלא שטיתי\u0004 בהיותי \u0003ארוסה, ו\u0004לא בהיותי \u0003נשואה,\u0004 ולא \u0003שומרת יבם, ו\u0004לא \u0003כנוסה.\u0004","ונברר: \u0003האי\u0004 \u0005[זו]\u0006 ה\u0003ארוסה היכי דמי\u0004 \u0005[כיצד היא בדיוק]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003דקני\u0004 \u0005[שקינא]\u0006 \u0003לה\u0004 והזהיר אותה שלא תיסתר עם איש פלוני \u0003כשהיא ארוסה, וקא משקה לה\u0004 \u0005[ומשקה אותה]\u0006 את המים גם כן \u0003כשהיא ארוסה\u0004 — אולם האם \u0003ארוסה בת משתיא\u0004 \u0005[שתיה]\u0006 \u0003היא\u0004 שאפשר להשקותה? \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003ארוסה ושומרת יבם,\u0004 שקינא להן הבעל, או היבם — \u0003לא שותות,\u0004 שאין דין שתיית המים אלא באשה נשואה בלבד, \u0003ולא נוטלות כתובה\u0004 אם נסתרו, שהרי עברו על ההזהרה ונהגו בדרך של פריצות!","\u0003אלא\u0004 תאמר \u0003דקני\u0004 \u0005[שקינא]\u0006 \u0003לה כשהיא ארוסה ואיסתתרה\u0004 \u0005[ונסתרה],\u0006 \u0003וקמשקה לה\u0004 \u0005[ומשקה אותה]\u0006 \u0003כשהיא נשואה\u0004 כבר, אולם במקרה זה \u0003מי בדקי לה מיא\u0004 \u0005[האם בודקים אותה המים]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 נאמר בכתוב: \u0003\"ונקה האיש מעון\u0004 והאשה ההיא תשא את עוונה\u0003\"\u0004 (במדבר ה, לא), לומר: \u0003בזמן שהאיש מנוקה מעון — המים בודקין את אשתו, אין האיש מנוקה מעון — אין המים בודקין את אשתו.\u0004 ומאחר שנסתרה ארוסה זו עם אחר, והיא חשודה כסוטה — אסורה היא על בעלה, וכיון שבכל זאת נשא אותה לאשה — כבר אינו נקי מעוון ואין שתיית המים פועלת עליה!","\u0003אלא,\u0004 צריך לומר \u0003דקני לה\u0004 \u0005[שקינא לה]\u0006 \u0003כשהיא ארוסה, ואיסתתרה\u0004 \u0005[ונסתרה],\u0006 \u0003ונכנסה לחופה ולא נבעלה,\u0004 ואז הביא אותה אל הכהן ונתקיימה אז השקייתה במים המאררים כשהיא נשואה, ובכל זאת לא עבר עבירה משום שלא בא עליה. אולם אם כן \u0003שמע מינה\u0004 \u0005[למד ממנה,\u0006 מכאן\u0005]\u0006 כי \u0003יש חופה לפסולות,\u0004 שחופה זו קונה את האשה הזו קנין גמור שתיחשב כאשתו למרות שביאתו היא ביאה פסולה שהרי קינא לה ונסתרה.","\u0003אמר רבא: ותסברא דהא מתרצתא\u0004 \u0005[וסבור אתה ש\u0006ברייתא \u0005זו מתורצת,\u0006 מיושרת\u0005]\u0006 \u0003היא,\u0004 ואפשר לסמוך עליה? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003ר' אחא בר חנינא מדרומא\u0004 \u0005[מן הדרום],\u0006 \u0003אתא ואייתי מתניתא בידיה\u0004 \u0005[בא והביא ברייתא בידו]\u0006 וזו היא: נאמר בהשבעת הסוטה \u0003\"\u0004ויתן איש בך את שכבתו \u0003מבלעדי אישך\"\u0004 (שם כ), לומר: \u0003מי שקדמה שכיבת בעל לבועל, ולא שקדמה שכיבת בועל לבעל.\u0004 ובמקרה שלנו, כיון שקודם נסתרה עם אחר ועדיין לא בא עליה בעלה, נמצא שקדמה שכיבת הבועל לשכיבת הבעל, ובמצב זה אין המים בודקים!","\u0003אמר רמי בר חמא: משכחת לה\u0004 \u0005[\u0006יכול \u0005אתה למצוא אותה]\u0006 באופן כזה: \u0003כגון שבא עליה ארוסה בבית אביה\u0004 קודם שנסתרה, ואחר כך קינא לה ונסתרה, ואז קדמה שכיבת בעל לשכיבת הבועל, ועדיין נקראת ארוסה מכיון שלא בעל אותה בביתו.","ושואלים: אם כן, אתה צריך לפרש \u0003דכוותה\u0004 \u0005[כיוצא בה]\u0006 \u0003גבי\u0004 (אצל) \u0003שומרת יבם\u0004 גם כן, ששומרת יבם זו, היא \u0003שבא עליה יבם בבית חמיה\u0004 לשם זנות, ואחר כך קינא לה ונסתרה,"],["\u0003שומרת יבם קרית\u0004 \u0005[קורא אתה]\u0006 \u0003לה?\u0004 כיון שבא עליה — \u0003אשתו מעליא\u0004 \u0005[מעולה,\u0006 גמורה\u0005]\u0006 \u0003היא, דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר רב:\u0004 הבא על יבמה בכל דרך שהיא ואף בשוגג או לזנות — \u0003קנה לכל!\u0004 ודוחים: צריכים לפרש \u0003כ\u0004שיטת \u0003שמואל,\u0004 ש\u0003אמר: לא קנה אלא לדברים האמורים בפרשה,\u0004 ולא לכל ענין, ואף לא לקרותה אשתו לענין סוטה.","ומשיבים: \u0003מידי הוא טעמא\u0004 \u0005[הרי\u0006 כל \u0005הטעם\u0006 של הוכחתנו אינו \u0003אלא ל\u0004שיטת \u0003רב\u0004 שאמר שיש חופה לפסולות, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר רב: קנה לכל.\u0004 ואם כן משיטת רב עצמו קשה! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנחנו עוסקים] —\u0006 \u0003כגון דעבד\u0004 \u0005[שעשה]\u0006 \u0003בה\u0004 היבם \u0003מאמר\u0004 ואחר כך בא עליה בבית חמיה \u0003ו\u0004דעת \u0003בית שמאי היא, דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]:\u0006 \u0003מאמר קונה קנין גמור\u0004 ופסקה ממנה זיקת הייבום.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, ביבמה שעשה בה מאמר — \u0003היינו\u0004 \u0005[הרי היא]\u0006 \u0003ארוסה\u0004 ומה ההבדל? ועונים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 ולשיטתך\u0005]\u0006 שאתה מדקדק בכך, מה שכתוב במשנה \u0003נשואה וכנוסה לאו חדא מילתא\u0004 \u0005[\u0006האם \u0005לא דבר אחד]\u0006 \u0003היא?! אלא\u0004 יש לומר שכאן מדובר בשני מקרים דומים זה לזה, וההבדל ביניהם הוא: \u0003נשואה\u0004 היא זו \u0003דידיה\u0004 \u0005[שלו],\u0006 אשה שהוא עצמו נשא אותה מדעתו, \u0003וכנוסה\u0004 היא \u0003דחבריה\u0004 \u0005[של חבירו],\u0006 כלומר, יבמה, שלא הוא בחר בה לשאת אותה מתחילה, אלא כנס אותה לאחר שנפלה לייבום. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 תאמר ש\u0003ארוסה\u0004 מדובר בזו \u0003דידיה\u0004 \u0005[שלו],\u0006 \u0003ושומרת יבם — דחבריה\u0004 \u0005[של חבירו].\u0006","\u0003רב פפא אמר:\u0004 אפשר לפתור את שאלת רבא באופן אחר, שאינו נוגע כלל לענין זה של חופה לפסולות, וברייתא זו — \u0003האי תנא הוא\u0004 \u0005[\u0006כשיטת \u0005תנא זה היא],\u0006 שאינו חושש לענין מנוקה האיש מעוון, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין מקנין לה לארוסה להשקותה כשהיא ארוסה, אבל מקנין אותה להשקותה כשהיא נשואה\u0004 על מה שנסתרה בהיותה ארוסה.","\u0003רב נחמן בר יצחק אמר:\u0004 מעיקרו של דבר אין זו שאלה, כי מדובר פה בהשבעה \u0003על ידי גלגול.\u0004 שבאמת אינו רשאי להשקות אותה כשהיא ארוסה, אלא אם משקה אותה לאחר נישואיה על שנסתרה כשהיא נשואה, הריהו רשאי לגלגל עליה גם שבועה זו, שתישבע שגם כשהיתה ארוסה לא סטתה.","\u0003שלח רב חנינא משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן: העושה מאמר ביבמתו, ויש לו אח, אפילו הוא\u0004 היבם \u0003כהן, והיא כהנת,\u0004 כלומר, בת כהן — \u0003פסלה מן התרומה,\u0004 ואינה אוכלת עד שיכנוס אותה. והטעם הוא: מכיון שעדיין לא כנסה יכול האח השני לעשות בה מאמר או לבוא עליה, וביאתו היא ביאה פסולה, שבמאמר שעשה בה אחיו קנה אותה לו במקצת, ונמצא שהיא כמשתמרת לביאה פסולה.","ושואלים: \u0003למאן\u0004 \u0005[ל\u0006דעת \u0005מי]\u0006 היא קרויה משתמרת לביאה פסולה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי \u0003ל\u0004דעת \u0003ר' מאיר — אימר\u0004 \u0005[אמור]\u0006 ש\u0003אמר ר' מאיר\u0004 כי \u0003משתמרת לביאה פסולה לא אכלה\u0004 \u0005[אוכלת]\u0006 בתרומה, הרי זה כשמדובר בביאה פסולה \u0003מדאורייתא\u0004 \u0005[מן התורה]\u0006 אבל בביאה פסולה מ\u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר?\u0004 שהרי כאן בעילה זו אינה פוסלת אלא משום המאמר, ומאמר זה הוא רק מדרבנן. \u0003ואלא\u0004 תאמר שהוא \u0003ל\u0004דעת \u0003ר' אלעזר ור' שמעון — השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 לשיטתם \u0003משתמרת לביאה פסולה דאורייתא\u0004 \u0005[שמן התורה],\u0006 \u0003אכלה\u0004 \u0005[אוכלת]\u0006 בתרומה \u0005—\u0006 בחשש ביאה פסולה מ\u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?!\u0006","\u0003אלא,\u0004 ודאי לא כך נאמרו הדברים, ו\u0003כי אתא\u0004 \u0005[\u0006ו\u0005כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם ר' יוחנן בנוסח מתוקן: אם \u0003עשה בה\u0004 היבם \u0003מאמר ביבמתו\u0004 ויש לו אח — \u0003דברי הכל אכלה\u0004 \u0005[אוכלת]\u0006 בתרומה, אבל אם \u0003יש לו אח חלל\u0004 (שנשא אביהם של האחים גם גרושה, ונולד אח זה, שהוא חלל) — \u0003דברי הכל אינה אוכלת,\u0004 שהרי מן התורה היא זקוקה גם לאח החלל, והואיל שאם יבוא עליה יפסול אותה בביאתו, הרי זו כמשתמרת לביאה פסולה. ו\u0003לא נחלקו אלא\u0004 כאשר \u0003נתן לה גט\u0004 ליבמה. \u0003ר' יוחנן אמר: אוכלת\u0004 בתרומה, משום שלאחר קבלת הגט היא נחשבת כחוזרת לבית אביה, ורשאית לאכול בתרומה של בית אביה. \u0003ריש לקיש אמר: אינה אוכלת.\u0004","ומסבירים את שיטותיהם: \u0003ר' יוחנן אמר אוכלת, אפילו לר' מאיר\u0004 ש\u0003אמר אינה אוכלת — הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים כאשר \u0003משתמרת לביאה פסולה דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003אבל\u0004 אם היא רק ביאה פסולה מ\u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 שאם יבוא עליה היבם לאחר שנתן לה גט, יעבור רק על דברי סופרים — \u0003אכלה\u0004 \u0005[אוכלת].\u0006","\u0003וריש לקיש אמר: אינה אוכלת.\u0004 והוא מסביר, \u0003אפילו ל\u0004דעת \u0003ר' אלעזר ור' שמעון, דאמרי\u0004 \u0005[שאומרים]\u0006 \u0003אוכלת — הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 דווקא במי ש\u0003יש לו להאכיל במקום אחר, אבל הכא\u0004 \u0005[כאן],\u0006 \u0003כיון\u0004 ש\u0003אין לו להאכיל במקום אחר,\u0004 שהרי מדובר כאן בגירושין, וכהן שגירש אשה אינו מאכילה על ידי כך — \u0003לא\u0004 תאכל בתרומה, שהיא משתמרת לביאה פסולה.","\u0003וכי תימא הכא נמי\u0004 \u0005[ואם תאמר כאן גם כן]\u0006 בגירושין \u0003יש לו להאכילה בחוזרת\u0004 כגון זר שמגרש כהנת, ואז היא חוזרת לבית אביה לאכול בתרומה, יש לחלק: \u0003חוזרת פסקה מיניה\u0004 \u0005[נפסקה,\u0006 נקטעה \u0005ממנו],\u0006 \u0003וקרובה לבי נשא\u0004 \u0005[לבית אביה]\u0006 וחוזרת לאכול בתרומה מכוחו, \u0003אבל הא אגידא ביה\u0004 \u0005[זו\u0006 היבמה שנתן לה גט הרי עדיין \u0005קשורה בו]\u0006 ביבם, עד שיחלוץ לה ומשום כך היא נפסלת.","שנינו במשנה שאלמנה לכהן גדול וכיוצא בו, אם \u0003נתארמלו או נתגרשו\u0004 מן הנישואין — פסולות, מן האירוסין — כשירות. \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' חייא בר יוסף משמואל: כהן גדול שקדש את הקטנה ובגרה תחתיו,\u0004 שלדעת רוב התנאים אסור לכהן גדול לשאת בוגרת, מפני שאינה קרויה עוד \"אשה בבתוליה\", אולם כיון שבגרה בזמן שהיתה מאורסת לו,"],["יש מקום לדון \u0003מהו\u0004 הדין, האם מותר לו לשאת אותה? וצדדי השאלה: האם \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003נישואין אזלינן\u0004 \u0005[הולכים אנו]\u0006 והרי בזמן הנישואין לא היתה ראויה לו, \u0003או בתר\u0004 \u0005[אחר]\u0006 ה\u0003אירוסין אזלינן\u0004 \u0005[הולכים אנו]\u0006 ובשעת קידושין, ראויה היתה.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם אותה]\u0006 ויש במשנה תשובה לשאלה זו. ששנינו: \u0003נתארמלו או נתגרשו, מן הנשואין — פסולות, מן האירוסין — כשרות.\u0004 משמע שבפסול כהונה הכל הולך אחר הנישואין ולא אחר האירוסין.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לשוויה\u0004 \u0005[\u0006לענין זה \u0005לעשות אותה]\u0006 \u0003חללה לא קמיבעיא\u0004 \u0005[נסתפק]\u0006 \u0003לי,\u0004 ש\u0003ביאה היא דמשוויה\u0004 \u0005[שעושה אותה]\u0006 \u0003חללה\u0004 וכל עוד לא בא עליה, ודאי איננה חללה. \u0003כי קמיבעיא לי\u0004 \u0005[כאשר,\u0006 מה ש\u0005נסתפק לי]\u0006 היה בענין אחר: מה שנאמר בכהן גדול \u0003\"והוא אשה בבתוליה יקח\"\u0004 (ויקרא כא, יג), \u0003מאי\u0004 \u0005[מה]\u0006 עניינו? האם כבר ב\u0003קיחה\u0004 של \u0003קדושין בעינן\u0004 \u0005[צריכים אנו]\u0006 שתהיה בבתוליה, כלומר, קטנה או נערה, \u0003או\u0004 אף ב\u0003קיחה\u0004 של \u0003נישואין בעינן\u0004 \u0005[צריכים אנו]\u0006 שתהיה בבתוליה.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הא נמי תניתוה\u0004 \u0005[זו גם כן שניתם אותה]\u0006 ששנינו: \u0003אירס את האלמנה ו\u0004אחר כך \u0003נתמנה להיות כהן גדול — יכנוס,\u0004 למרות שכהן גדול אסור באלמנה, משמע שהולכים אחר זמן האירוסין, ולא אחר זמן הנישואין. ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בלשון ריבוי \u0003\"יקח אשה\"\u0004 (שם יד), ללמד שרשאי לשאת אשה שהיתה ארוסה לו מקודם, אם נתמנה להיות כהן גדול בין אירוסין לנישואין.","ומקשים: \u0003הכא נמי כתיב\u0004 \u0005[כאן גם כן נאמר]\u0006 \u0003\"אשה\"\u0004 (\"והוא אשה בבתוליה יקח\"), ושמא גם זה בא לרבות! ומשיבים: \"אשה\" שנאמרה שם באה למעט רק אשה \u0003אחת\u0004 (שדנים אותה לפי זמן האירוסין) \u0003ולא שתים\u0004 או יותר, שהלימוד מוגבל לאשה אחת.","ושואלים: \u0003ומה ראית\u0004 במה עדיף לרבות את האלמנה ולהוציא את הבוגרת ולא להיפך? ענה לו: \u0003הא\u0004 \u0005[זו],\u0006 הבוגרת — \u0003אישתני\u0004 \u0005[השתנה]\u0006 \u0003גופה\u0004 בינתיים, ולכן היה מקום לפסול אותה גם אם בגרה כשהיתה ארוסתו. \u0003והא\u0004 \u0005[ו\u0006אילו \u0005זו]\u0006 באלמנה — \u0003לא אישתני\u0004 \u0005[השתנה]\u0006 \u0003גופה,\u0004 אלא מעמדו שלו הוא שהשתנה, ולכן יש מקום להתירה.","\u0003כהן גדול לא ישא אלמנה, בין אלמנה מן האירוסין, בין אלמנה מן הנשואין. ולא ישא את הבוגרת,\u0004 אלא קטנה או נערה. \u0003ר' אלעזר ור' שמעון מכשירין בבוגרת,.ולא ישא את מוכת עץ,\u0004 כלומר, אשה שנפגעו בתוליה לא על ידי ביאה אלא כתוצאה מתאונה, כגון מחבלה מעץ.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 בכהן הגדול נאמר \u0003\"אלמנה... לא יקח\"\u0004 (שם יד), והכוונה — \u0003בין אלמנה מן האירוסין, בין אלמנה מן הנשואין.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 הרי נאמר אלמנה סתם! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003לילף\u0004 \u0005[שנלמד]\u0006 \u0003\"אלמנה\" \"אלמנה\"\u0004 בגזירה שווה \u0003מתמר\u0004 כלת יהודה, שנאמר בה \"ויאמר יהודה לתמר כלתו שבי אלמנה בית אביך\" (בראשית לח, יא); \u0003מה להלן,\u0004 בתמר, אלמנה \u0003מן הנשואין\u0004 היתה — \u0003אף כאן\u0004 אינו אסור אלא באלמנה \u0003מן הנשואין,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא לאסור אף את האלמנה מן האירוסין.","ושואלים: ובאמת, \u0003ואימא הכי נמי\u0004 \u0005[ואמור כך גם כן]\u0006 שאסור רק באלמנה מן הנישואין?! ומשיבים: \u0003דומיא\u0004 \u0005[\u0006ב\u0005דומה]\u0006 ל\u0003גרושה, מה גרושה — בין מן הנישואין בין מן האירוסין, אף אלמנה — בין מן האירוסין בין מן הנישואין.\u0004","שנינו במשנה: \u0003ולא ישא את הבוגרת. תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר בכהן גדול: \u0003\"והוא אשה בבתוליה יקח\"\u0004 (שם יג), ולמדו מזה \u0003פרט לבוגרת,\u0004 ומדוע — מפני \u0003שכלו לה בתוליה.\u0004 שאין הבתולים בה שלמים כמו בקטנה, אלו \u0003דברי ר' מאיר. ר' אלעזר ור' שמעון מכשירין בבוגרת.\u0004","ושואלים: \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון \u0005נחלקו]?\u0006 ומסבירים, \u0003ר' מאיר סבר:\u0004 אילו נאמר \u0003\"בתולה\"\u0004 הייתי אומר ש\u0003אפילו מקצת בתולים משמע,\u0004 כלומר, בתולה כלשהי. אך כיון שנאמר \u0003\"בתוליה\" — עד דאיכא\u0004 \u0005[שיש]\u0006 \u0003כל הבתולים\u0004 משמע, למעט את הבוגרת. ומה שנוספה האות \"ב\" שנאמר: \u0003\"בבתוליה\",\u0004 בא ללמד שבביאה \u0003כדרכה,\u0004 במקום הבתולים — \u0003אין\u0004 \u0005[כן],\u0006 היא נפסלת בתור בעולה, אבל אם נבעלה \u0003שלא כדרכה — לא.\u0004","\u0003ור' אלעזר ור' שמעון סברי\u0004 \u0005[סבורים]:\u0006 אילו היה כתוב \u0003\"בתולה\" — בתולה שלימה משמע,\u0004 וצורת הכינוי \u0003\"בתוליה\"\u0004 משמעה: \u0003ואפילו מקצת בתולים,\u0004 ולרבות אף בוגרת בכלל ההיתר. ומה שנאמר \u0003\"בבתוליה\" — עד שיהיו כל בתוליה קיימין,\u0004 שלא תהא בעולה כלל, \u0003בין בכדרכה, בין שלא כדרכה.\u0004","\u0003אמר רב יהודה אמר רב: נבעלה שלא כדרכה — פסולה\u0004 להינשא \u0003ל\u0004מי שמשמש ב\u0003כהונה\u0004 גדולה. \u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רבא,\u0004 נאמר באונס אשה: \u0003\"ולו תהיה לאשה\"\u0004 (דברים כב, יט), ודרשו חכמים — \u0003באשה הראויה לו, פרט לאלמנה\u0004 שנאנסה על ידי \u0003כהן גדול,\u0004 או \u0003גרושה\u0004 או \u0003חלוצה\u0004 שנאנסה על ידי \u0003כהן הדיוט,\u0004 שאלו אינם נושאים את אנוסותיהם.","ומעתה נברר: \u0003היכי דמי\u0004 \u0005[במה בדיוק\u0006 מדובר\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שאנס אותה כהן זה \u0003ב\u0004ביאה \u0003כדרכה — מאי איריא\u0004 \u0005[מה שייך],\u0006 מדוע נתן טעם \u0003משום אלמנה? תיפוק ליה\u0004 \u0005[תצא לו,\u0006 ילמד\u0005]\u0006 הלכה זו \u0003משום דהויא לה\u0004 \u0005[שהרי היא]\u0006 כבר \u0003בעולה, אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 מדובר באופן שאנס אותה \u0003שלא כדרכה, ומשום אלמנה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 היא אסורה, אולם \u0003משום בעולה\u0004 — \u0003לא,\u0004 משמע שבעולה שלא כדרכה איננה מוגדרת כבעולה להיות פסולה לכהן גדול!"],["\u0003הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי\u0006 היא\u0005],\u0006 כדעת \u0003ר' מאיר היא,\u0004 הסבור שבעולה שלא כדרכה, מותרת לכהן גדול, \u0003ו\u0004אילו \u0003רב\u0004 ש\u0003אמר,\u0004 מה שאמר — \u0003כ\u0004דעת \u0003ר' אלעזר\u0004 הפוסל בעולה שלא כדרכה אמר דבריו.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004דעת \u0003ר' אלעזר,\u0004 אם כן \u0003מאי איריא\u0004 \u0005[מה שייך],\u0006 מדוע אמר שאסורה \u0003משום בעולה?\u0004 הלא יש סיבה אחרת לפוסלה \u0003תיפוק ליה דהויא לה\u0004 \u0005[תצא לו,\u0006 תילמד הלכה זו בגלל \u0005שהרי היא]\u0006 \u0003זונה? דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר ר' אלעזר:\u0004 אפילו \u0003פנוי הבא על הפנויה,\u0004 אם בא עליה \u0003שלא לשם אישות — עשאה זונה\u0004 על ידי ביאה זו, ואם כן, זו שנבעלה שלא כדרכה, אפילו שהיתה פנויה — הרי היא זונה, ואסורה גם לכהן הדיוט לדעת ר' אלעזר.","\u0003אמר רב יוסף:\u0004 מה שאמר רב שהבעולה שלא כדרכה פסולה לכהונה גדולה, מדובר \u0003כגון שנבעלה לבהמה, דהתם\u0004 \u0005[ששם]\u0006 \u0003משום בעולה איכא\u0004 \u0005[יש]\u0006 פסול בכך, שהרי בעולה היא, ואילו \u0003משום זונה ליכא\u0004 \u0005[אין]\u0006 בכך פסול.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ממה נפשך\u0004 בכל אופן אין זו תשובה כי \u0003אי\u0004 \u0005[אם]\u0006 כ\u0003בעולה הויא\u0004 \u0005[היא\u0006 נחשבת\u0005],\u0006 אם כן כ\u0003זונה נמי הויא\u0004 \u0005[גם כן היא\u0006 נחשבת\u0005],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003זונה לא הויא\u0004 \u0005[אינה\u0006 נחשבת\u0005]\u0006 \u0003— בעולה נמי לא הויא\u0004 \u0005[גם כן\u0006 היא \u0005אינה\u0006 נחשבת\u0005].\u0006 \u0003וכי תימא מידי דהויא\u0004 \u0005[ואם תאמר: כדרך שהוא]\u0006 ב\u0003מוכת עץ שלא כדרכה\u0004 שאינה בתולה עוד ובכל זאת אינה אסורה משום זונה, גם זו שנבעלה שלא כדרכה על ידי בהמה תיחשב כך, אולם אי אפשר לומר שמוכת עץ שלא כדרכה, תיפסל לכהונה, ש\u0003אם כן, אין לך אשה שכשרה לכהונה\u0004 גדולה, שלא יתכן \u0003שלא נעשית מוכת עץ על ידי צרור\u0004 של בית הכסא, שקינחה בו. ובודאי אין זה קרוי מוכת עץ כלל.","\u0003אלא, אמר ר' זירא:\u0004 רב דיבר \u0003ב\u0004יתומה קטנה שהשיאוה אחיה ואמה, ונבעלה שלא כדרכה, ולאחר מכן היתה \u0003ממאנת\u0004 בבעלה, שהרי היא כאילו לא נישאה מעולם ואין בה אם כן פסול אלמנות או גירושין, ואף על פי כן ביאתה לא היתה ביאת זנות, שהרי בזמן שנבעלה היתה נשואה, והבעילה היתה כשרה, ובאופן כזה אף שאינה אלמנה, בכל אופן נפסלה לכהונה משום שאינה בתולה.","\u0003אמר רב שימי בר חייא: נבעלה לבהמה\u0004 — הרי היא כמוכת עץ ו\u0003כשרה לכהונה\u0004 ואינה קרויה זונה. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003נבעלה למי שאינו איש, אף על פי\u0004 שאם עשתה זאת במזיד והיו עדים והתרו בה עונשה \u0003בסקילה,\u0004 מכל מקום \u0003כשרה לכהונה.\u0004","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר: מעשה בריבה\u0004 (נערה) \u0003אחת ב\u0004כפר \u0003היתלו שהיתה מכבדת\u0004 (מטאטאת) \u0003את הבית, ורבעה כלב כופרי\u0004 (כלב ציד קטן) \u0003מאחריה,\u0004 כלומר, שלא כדרכה, \u0003והכשירה רבי לכהונה,\u0004 מפני שלא נעשתה זונה בכך. \u0003אמר שמואל: ו\u0004אפילו \u0003לכהן גדול,\u0004 התירה רבי, משום שהיא נחשבת עדיין בתולה. ותוהים: וכי \u0003בימי רבי כהן גדול מי הוה\u0004 \u0005[האם היה]?\u0006 הלא רבי חי כמה דורות לאחר חורבן בית המקדש! \u0003אלא\u0004 כוונתו היתה — ש\u0003ראויה\u0004 אפילו \u0003לכהן גדול.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא מפרקין לרב אשי: מנא הא מילתא דאמור רבנן\u0004 \u0005[מניין דבר זה שאמרו חכמים\u0006 ככלל\u0005]\u0006 \u0003שאין זנות לבהמה?\u0004 אמר לו, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא תביא אתנן זונה ומחיר כלב\u0004 בית ה' אלהיך לכל נדר כי תועבת ה' אלהיך גם שניהם\u0003\"\u0004 (דברים כג, יט),","\u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003אתנן כלב,\u0004 שאם נתן אדם כסף כדי לבעול או להיבעל לכלב, \u0003ו\u0004כן \u0003מחיר זונה\u0004 אם החליף או קנה זונה בכסף מסויים — \u0003מותרין\u0004 לבית המקדש, \u0003משום שנאמר \"גם שניהם\",\u0004 ללמד: \u0003שנים\u0004 הם האסורים (אתנן זונה ומחיר כלב) \u0003ולא ארבעה\u0004 (גם מחיר זונה ואתנן כלב), ומכאן למדנו שבכלב אין דין של זנות.","\u0003תנו רבנן:\u0004 \u0005[שנו חכמים]:\u0006 את \u0003אנוסת עצמו ומפותת עצמו לא ישא\u0004 כהן גדול, שהרי מצווה הוא לשאת רק בתולה, \u0003ואם\u0004 עבר ו\u0003נשא — נשוי. אנוסת חבירו ומפותת חבירו — לא ישא, ואם נשא — ר' אליעזר בן יעקב אומר: הולד חלל, וחכמים אומרים: הולד כשר.\u0004","ומבארים ברייתא זו, אמרנו \u0003\"אם נשא — נשוי\". אמר רב הונא אמר רב: ומוציא בגט,\u0004 כלומר, בכל זאת כופים אותו לגרשה. ושואלים: \u0003ואלא הא דקתני\u0004 \u0005[זו ששנה]\u0006 \u0003\"אם נשא — נשוי\",\u0004 הלא ברור שהקידושין תופסים, ובודאי היתה הכוונה שמותר לו לקיימה! \u0003אמר רב אחא בר יעקב:\u0004 לא, \u0003לומר\u0004"],["\u0003שאין משלם קנס במפותה,\u0004 שמי שפיתה אשה ואינו רוצה לשאתה — צריך לשלם קנס, וזה, כיון שנשאה, אף שצריך להוציאה — אינו משלם קנס, משום שכבר נשאה.","מסופר: כאשר \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רב גביהה מ\u0004מקום הנקרא \u0003בי כתיל, אמרה לשמעתא\u0004 \u0005[את ההלכה]\u0006 הזו שאמר רב הונא שאם נשאה צריך לגרשה \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב אשי. אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב ור' יוחנן דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003בוגרת ומוכת עץ לא ישא\u0004 כהן גדול, \u0003ואם נשא — נשוי.\u0004","\u0003אלמא\u0004 \u0005[מכאן],\u0006 שטעם הלכה זו, מאחר ש\u0003סופה להיות בוגרת תחתיו\u0004 כשתהיה עמו, וכן \u0003סופה להיות מוכת עץ תחתיו,\u0004 כלומר, בסופו של דבר הרי לא תשאר בתולה, לכן \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 במפותת עצמו קיים אותו נימוק, כיון ש\u0003סופה להיות בעולה תחתיו,\u0004 ואם כן אם נשא — לא יגרש. ומסכמים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 לדברי רב הונא.","שנינו בברייתא: \u0003אנוסת חבירו ומפותת חבירו לא ישא. ואם נשא\u0004 — \u0003ר' אליעזר בן יעקב אומר: הולד חלל, וחכמים אומרים: הולד כשר. אמר רב הונא אמר רב: הלכה כר' אליעזר בן יעקב. וכן אמר רב גידל אמר רב: הלכה כר' אליעזר בן יעקב.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בנוסח אחר, ש\u0003אמר רב הונא אמר רב: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר בן יעקב\u0004 — משום ש\u0003סבר לה\u0004 \u0005[\u0006ש\u0005סבור\u0006 הוא\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' אלעזר\u0004 שפנוי הבא על הפנויה — עשאה זונה, ולכן, אנוסת חבירו ומפותת חבירו, כיון שביאתן היתה לשם זנות, ממילא נחשבת אותה אשה זונה, ואסורה לכהן, והוולד הנולד לה חלל.","ושואלים: \u0003ומי סבר לה כותיה\u0004 \u0005[האם סבור\u0006 הוא באמת \u0005כמותו]?\u0006 \u0003והא קיימא לן\u0004 \u0005[והרי מוחזק לנו]\u0006 כי \u0003משנת ר' אליעזר בן יעקב קב ונקי,\u0004 כלומר, מעטה היא, אבל בכל מה שאמר — הלכה כמותו. ואם כן הלכה כמותו גם בענין זה, \u0003ואילו בהא\u0004 \u0005[ב\u0006הלכה \u0005זו]\u0006 של ר' אלעזר \u0003אמר רב עמרם אמר רב: אין הלכה כר' אלעזר.\u0004 ומעירים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","\u0003רב אשי אמר:\u0004 לא זה טעם המחלוקת, אלא \u0003ב\u0004שאלה האם \u0003יש חלל\u0004 מביאה על \u0003חייבי עשה קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 שהרי שאר איסורי כהונה הם מצוות לא תעשה, ואילו בבעולה לכהן גדול יש רק איסור עשה. ש\u0003ר' אליעזר בן יעקב סבר: יש חלל מחייבי עשה, ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003אין חלל מחייבי עשה.\u0004","ו\u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר בן יעקב — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אלמנה וגרושה וחללה זנה את אלה לא יקח כי אם בתולה\u0004 מעמיו יקח אשה\u0003\"\u0004 (ויקרא כא, יד), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בהמשך: \u0003\"ולא יחלל זרעו בעמיו\"\u0004 (שם טו), ולדעתו חילול זה מוסב \u0003אכולהו\u0004 \u0005[על כולם],\u0006 שבכל מקום שנשא אשה שאינה ראויה לו, בין כשהיא עליו בלא תעשה ובין שהיא עליו בעשה, הריהו מחלל את זרעו.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם אומרים על כך — לדעתם הביטוי \u0003\"אלה\" הפסיק הענין,\u0004 שרק בנשים שנאמר בהן \"את אלה לא יקח\" נאמר שהוא מחלל את זרעו. \u0003ור' אליעזר בן יעקב אמר: \"אלה\"\u0004 שנאמר שם בא, \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003נדה,\u0004 שאם בא כהן על אשה נידה, למרות שביאה זו היא ביאת איסור — מכל מקום הוולד איננו חלל, משום שאיסור זה אינו מאיסורי כהונה.","ושואלים: \u0003כמאן אזלא\u0004 \u0005[כ\u0006דעת \u0005מי הולכת]\u0006 \u0003הא דתניא\u0004 \u0005[\u0006שיטה \u0005זו ששנינו\u0006 בברייתא\u0005]:\u0006 דווקא הנולדים \u0003מ\"אלה\"\u0004 הנזכרים בפרשה כאסורים לכהונה \u0003אתה עושה חלל, ואי אתה עושה חלל\u0004 את הנולד \u0003מ\u0004כהן הבא על ה\u0003נדה. כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 — \u0003כ\u0004דעת \u0003ר' אליעזר בן יעקב.\u0004 ושואלים: \u0003ו\u0004לדעת \u0003ר' אליעזר בן יעקב\u0004 אם כן \u0003נכתביה\u0004 \u0005[שיכתוב]\u0006 המקרא \u0003ל\"אלה\" לבסוף\u0004 לאחר בתולה, ולא יפסיק, ויהא ברור שגם היא נכללת בדין של חללות? ואומרים: אכן, \u0003קשיא\u0004 \u0005[קשה].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אף שאסור לכהן להיטמא לאחותו הנשואה, מכל מקום \u0003אחותו\u0004 שהיא \u0003ארוסה, ר' מאיר ור' יהודה אומרים:\u0004 כהן \u0003מטמא לה\u0004 במותה, \u0003ר' יוסי ור' שמעון אומרים: אין מטמא לה.\u0004 אחותו \u0003אנוסה\u0004 או \u0003מפותה — דברי הכל אין מטמא לה, ומוכת עץ אין מטמא לה,\u0004 אלו \u0003דברי ר' שמעון. שהיה ר' שמעון אומר\u0004 כלל: אם היתה אחותו \u0003ראויה\u0004 להינשא \u0003לכהן גדול — מטמא לה,\u0004 ואולם זו \u0003שאין ראויה לכהן גדול,\u0004 שאינה בתולה — \u0003אין מטמא לה.\u0004","\u0003ובוגרת\u0004 — \u0003מטמא לה,\u0004 ל\u0003דברי כל אדם,\u0004 כלומר, אף אלה שאומרים שאסור לכהן גדול לשאת בוגרת, לפי שאינה בתולה שלימה, מכל מקום אף לדעתם לענין טומאה נחשבת היא כבתולה.","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' מאיר ור' יהודה — דדרשי הכי\u0004 \u0005[ש\u0006הם \u0005דורשים כך],\u0006 נאמר: \u0003\"ולאחתו הבתולה\u0004 הקרובה אליו אשר לא היתה לאיש לה יטמא\u0003\"\u0004 (ויקרא כא, ג), ולמדים מזה: \u0003פרט לאנוסה ומפותה\u0004 שאינן בתולות.","\u0003יכול שאני מוציא אף מוכת עץ\u0004 שגם היא אינה בתולה — \u0003תלמוד לומר \"אשר לא היתה לאיש\",\u0004 וכוונתו: \u0003מי שהוייתה\u0004 (העשותה בעולה) \u0003על ידי איש, יצאה זו שאין הוייתה\u0004 (בעולה) \u0003על ידי איש\u0004 אלא על ידי חפץ. נאמר \u0003\"הקרובה\" — לרבות הארוסה,\u0004 שאף לה מיטמא, הרי קירבתם בעינה עומדת. \u0003\"אליו\" — לרבות\u0004 אחותו \u0003הבוגרת,\u0004 שכל עוד לא נישאה, הריהו מיטמא לה.","ושואלים: \u0003הא\u0004 \u0005[\u0006ול\u0005זה]\u0006 \u0003למה לי קרא\u0004 \u0005[פסוק]\u0006 מיוחד? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' מאיר\u0004 לענין כהן גדול: \u0003\"בתולה\" — אפילו מקצת בתולה משמע,\u0004 ואם כן, לשיטתו, הבוגרת אף שאין בתוליה שלמים כמו בקטנה — בתולה גמורה היא, ואינה צריכה ריבוי מיוחד! ומשיבים: בכל זאת, כאן לגבי אחותו \u0003איצטריך\u0004 \u0005[נצרך]\u0006 הדבר לאומרו, כי \u0003סלקא דעתך אמינא\u0004 \u0005[\u0006שמא \u0005יעלה על דעתך לומר]\u0006 \u0003נילף\u0004 \u0005[נלמד]\u0006 \u0003\"בתולה\" \"בתולה\" מהתם\u0004 \u0005[משם]\u0006 מדין בתולה לכהן גדול, ותאמר: \u0003מה להלן\u0004 בתולה זו \u0003נערה\u0004 ולא בוגרת, \u0003אף כאן נמי\u0004 \u0005[גם כן]\u0006 אינו מיטמא אלא לאחותו ה\u0003נערה,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ריבוי הכתוב \"אליו\", ללמד שגם אחותו הבוגרת ואפילו זקינה במשמע, שגם היא קרובה אליו.","\u0003ור' יוסי ור' שמעון,\u0004 שלדעתם אין הכהן מיטמא לאחותו הארוסה, \u0003מאי טעמייהו\u0004 \u0005[מה טעמם] —\u0006 \u0003דרשי הכי\u0004 \u0005[דורשים\u0006 הם \u0005כך]:\u0006 \u0003\"ולאחתו הבתולה\" — פרט לאנוסה ומפותה ומוכת עץ,\u0004 שאינן בתולות, \u0003\"אשר לא היתה\u0004 לאיש\" — \u0003פרט לארוסה,\u0004 אף שלא נעשתה עדיין אשת איש לגמרי, \u0003\"הקרובה\" — לרבות ארוסה שנתגרשה,\u0004 שחזרה ונעשתה קרובה אליו ומיטמא לה, \u0003\"אליו\" — לרבות את הבוגרת.\u0004 וממשיכים לדון בשיטה זו, אמרנו: \u0003\"הקרובה\" — לרבות ארוסה שנתגרשה,\u0004"],["\u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' שמעון: ראויה לכהן גדול — מטמא לה, שאין ראויה לכהן גדול — אין מטמא לה.\u0004 וזו, כיון שנתגרשה, שוב אינה ראויה לכהן! ומשיבים: \u0003שאני התם דרבי רחמנא\u0004 \u0005[שונה שם\u0006 כיון \u0005שריבתה התורה]\u0006 וכתבה \u0003\"קרובה\",\u0004 ומשמע: כל שהיא קרובה, גם אם איננה ראויה להינשא לכהן.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כן]\u0006 \u0003מוכת עץ נמי\u0004 \u0005[גם כן]\u0006 נרבה לר' שמעון! ומשיבים: \u0003רבי\u0004 \u0005[ריבה]\u0006 הכתוב \u0003\"קרובה\" — אחת ולא שתים\u0004 וממילא הלימוד מוגבל רק לענין אחד! ושואלים: \u0003ומה ראית\u0004 לומר שמוכת עץ אתה אוסר, וגרושה אתה מתיר, אולי הנכון הוא להיפך? ומשיבים: \u0003הא\u0004 \u0005[זו]\u0006 מוכת עץ \u0003— אתעביד\u0004 \u0005[נעשה]\u0006 \u0003בה מעשה\u0004 בגופה. \u0003הא\u0004 \u0005[זו]\u0006 הגרושה — \u0003לא אתעביד\u0004 \u0005[נעשה]\u0006 \u0003בה\u0004.","ושואלים: \u0003ור' יוסי, מדשבקיה לבר זוגיה\u0004 \u0005[מ\u0006כיון \u0005שעזב את בן זוגו]\u0006 ר' שמעון, שלענין ארוסה הסכים אתו — \u0003מכלל\u0004 הדברים אתה למד כי \u0003במוכת עץ כ\u0004שיטת \u0003ר' מאיר סבירא ליה\u0004 \u0005[סבור הוא]\u0006 שמיטמא לה, ואם כן \u0003מנא ליה\u0004 \u0005[מניין לו]\u0006 דבר זה — \u0003מ\u0004מה שנאמר שאסור לכהן להיטמא לאחותו \"אשר \u0003לא היתה לאיש\",\u0004 ומוכת עץ הרי לא היתה לאיש.","ושואלים: \u0003והא אפיקתיה\u0004 \u0005[והרי\u0006 כבר \u0005הוצאת אותו],\u0006 למדת מביטוי זה כדעת ר' שמעון לענין ארוסה! ומשיבים: \u0003חד\u0004 \u0005[\u0006ענין \u0005אחד]\u0006 למד ר' יוסי \u0003מ\"לא היתה\"\u0004 כלומר, לא התקדשה, \u0003וחד\u0004 \u0005[ואחד]\u0006 \u0003מ\"לאיש\",\u0004 שדווקא אם היא אינה בתולה בגלל איש, ולא בגלל משהו אחר.","אמרנו שלדעת כולם: \u0003\"אליו\" — לרבות הבוגרת\u0004 שאף לה מיטמא כל עוד אינה נשואה. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' שמעון\u0004 לגבי נישואי בוגרת לכהן גדול: \u0003\"בתולה\" — בתולה שלימה משמע\u0004 ואין הבוגרת בכלל זה! ומשיבים: \u0003טעמא דידיה נמי התם מהכא\u0004 \u0005[הטעם שלו שם, גם כן מכאן]\u0006 הוא, \u0003דדריש הכי\u0004 \u0005[ש\u0006הוא \u0005דורש כך]:\u0006 \u0003מ\u0004אחר שהביטוי שנאמר \u0003\"אליו\"\u0004 בא \u0003לרבות\u0004 את \u0003הבוגרת, מכלל\u0004 הדברים אתה למד כי \u0003\"בתולה\"\u0004 בכל מקום אחר ובכלל זה לענין נישואין — \u0003בתולה שלימה משמע,\u0004 והבוגרת כיון שאינה בכלל בתולה שלימה — אסורה.","אגב הדיון בהגדרת בתולה ובפרט לדעת ר' שמעון, מביאים דיון בנושא קרוב, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן יוחי אומר: גיורת פחותה מבת שלש שנים ויום אחד — כשירה לכהונה, שנאמר: \"וכל הטף בנשים אשר לא ידעו משכב זכר החיו לכם\"\u0004 (במדבר לא, יח), משמע — לכולכם. \u0003והרי פנחס\u0004 היה \u0003עמהם,\u0004 ופנחס כהן היה ואסור בגיורת, משמע שהטף, כלומר, ילדות פחותות מגיל שלוש מותרות אף לכהן.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם אומרים? לדעתם: \"החיו לכם\" אין כוונתו שתהיינה להם לנשים, אלא \u0003לעבדים ולשפחות.\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003בת שלש שנים ויום אחד נמי\u0004 \u0005[גם כן],\u0006 יהיו מותרות לדעת ר' שמעון ואפילו לכהן, כשלא ידעו משכב זכר?","ומשיבים: הטעם הוא \u0003כ\u0004דברי \u0003רב הונא,\u0004 ש\u0003רב הונא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 במקום אחד \u0003\"\u0004ו\u0003כל אשה ידעת איש למשכב זכר הרגו\"\u0004 (שם יז), \u0003הא\u0004 \u0005[הרי]\u0006 מכאן מובן כי זו ש\u0003אינה יודעת — קיימו,\u0004 ו\u0003מכלל\u0004 הדברים אתה למד ש\u0003הטף,\u0004 הקטנות, שאינן בגדר אשה, \u0003בין ידעו בין לא ידעו — קיימו. וכתיב\u0004 \u0005[ונאמר]\u0006 בפסוק אחר \u0003\"וכל הטף בנשים אשר לא ידעו משכב זכר החיו לכם\"\u0004 (שם יח) \u0003הא ידעי\u0004 \u0005[הרי\u0006 אם \u0005ידעו] —\u0006 \u0003הרוגו,\u0004 ואפילו טף בכלל, ויש פה איפוא סתירה!","ויש לתרץ: \u0003הוי אומר בראויה ליבעל הכתוב מדבר,\u0004 שאין הכתוב מחלק בין זו שנבעלה ובין זו שלא נבעלה, אלא כשאומר \"יודעת איש\" כוונתו הראויה להיבעל, וכל קטנה מעל גיל שלוש בכלל ראויה להיבעל ואסורה.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 מה שנאמר: \u0003\"וכל אשה ידעת איש\"\u0004 (שם יז) — \u0003בראויה ליבעל הכתוב מדבר.\u0004 ודנה הברייתא: \u0003אתה אומר בראויה ליבעל, או אינו אלא נבעלה ממש? כשהוא אומר \"וכל הטף בנשים אשר לא ידעו משכב זכר\"\u0004 (שם יח), יש לדייק: אבל אשה אפילו לא יודעת משכב זכר תיהרג, \u0003הוי אומר: בראויה ליבעל הכתוב מדבר.\u0004","ושואלים לעצם המעשה: \u0003מנא ידעי\u0004 \u0005[מניין ידעו]\u0006 אם ילדה מסויימת הגיעה לגיל זה שראויה כבר להיבעל? \u0003אמר רב הונא בר ביזנא אמר ר' שמעון חסידא: העבירום לפני הציץ\u0004 של כהן גדול, ובדרך נס \u0003כל ש\u0004היו \u0003פניה מוריקות — בידוע שהיא ראויה ליבעל, כל שאין פניה מוריקות — בידוע שאינה ראויה ליבעל.\u0004 ובדומה לזה \u0003אמר רב נחמן: סימן לעבירה — הדרוקן\u0004 שעוברי עבירה חולים במחלה זו ופניהם מוריקים.","\u0003כיוצא בדבר,\u0004 במעשה של פילגש בגבעה, שהרגו את כל אנשי יבש גלעד פרט לבתולות, \u0003אתה אומר: \"וימצאו מישבי יביש גלעד ארבע מאות נערה בתולה אשר לא ידעה איש למשכב זכר\"\u0004 (שופטים כא, יב), ואף כאן יש לשאול: \u0003מנא ידעי\u0004 \u0005[מניין ידעו]\u0006 איזו היא אשר ידעה איש? \u0003אמר רב כהנא: הושיבום על פי חבית של יין, בעולה — ריחה נודף, בתולה — אין ריחה נודף.\u0004","ושואלים: \u0003ונעברינהו\u0004 \u0005[ונעביר אותן]\u0006 \u0003לפני הציץ\u0004 כפי שעשו לבנות מדין? \u0003אמר רב כהנא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן:\u0004 \"והיה על מצח אהרן ונשא אהרן את עוון הקדשים אשר יקדישו בני ישראל לכל מתנות קדשיהם והיה על מצחו תמיד \u0003לרצון להם\u0004 לפני ה'\" (שמות כח, לח), \"לרצון\" \u0003כתיב\u0004 \u0005[נאמר],\u0006 כלומר, \u0003לרצון ולא לפורענות,\u0004 ומאחר שהבעולות נהרגו, הרי זה בכלל פורענות ואין להשתמש לכך בציץ. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003במדין נמי\u0004 \u0005[גם כן]\u0006 מדוע השתמשו בציץ לענין של פורענות? \u0003אמר רב אשי: \"להם\" כתיב\u0004 \u0005[נאמר],\u0006 כלומר, \u0003להם\u0004 לישראל \u0003לרצון ולא לפורענות, ולגוים — אפילו לפורענות.\u0004","\u0003אמר ר' יעקב בר אידי אמר ר' יהושע בן לוי: הלכה כר' שמעון בן יוחאי,\u0004 שגיורת הפחותה מבת שלוש כשרה לכהונה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לר' יעקב בר אידי: בפירוש שמיע לך\u0004 \u0005[שמעת]\u0006 שהלכה כן, \u0003או מכללא שמיע לך\u0004 \u0005[מכלל\u0006 הדברים \u0005שמעת\u0006 זאת\u0005]?\u0006 שלא שמעת פסק הלכה מפורש אלא הסקת זאת מדבר אחר.","ושואלים: \u0003מאי כללא\u0004 \u0005[מהו הכלל]\u0006 שרמז לו ר' זירא? ומסבירים: ש\u0003אמר ר' יהושע בן לוי: עיר אחת היתה בארץ ישראל שקרא עליה ערער,\u0004 שהיתה שמועה שיש פסול יוחסין במשפחה אחת בעיר זו, \u0003ושגר\u0004 (ושלח) \u0003רבי את ר' רומנוס, ובדקה, ומצא\u0004 שהיתה \u0003בה בת\u0004 של \u0003גיורת\u0004 שנתגיירה בהיותה \u0003פחותה מבת שלש שנים ויום אחד\u0004 שנישאה לכהן, \u0003והכשירה רבי לכהונה.\u0004 ואם כן, מכאן היה יכול להסיק שפסק ר' יהושע בן לוי הלכה כר' שמעון. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יעקב בר אידי: \u0003בפירוש שמיע לי\u0004 \u0005[שמעתי\u0006 זאת\u0005],\u0006 שכך אמר במפורש.","ושואלים: \u0003ואי מכללא מאי\u0004 \u0005[ואם מכלל\u0006 הדברים שמע, \u0005מה]\u0006 בכך? הרי לכאורה ראיה גמורה היא! ומשיבים: \u0003דלמא שאני התם\u0004 \u0005[שמא שונה שם]\u0006 בכך: \u0003הואיל ואנסיב\u0004 \u0005[ונישאה] —\u0006 \u0003אנסיב\u0004 \u0005[נישאה],\u0006 שלכתחילה אף הוא סבור שאסור, אבל בדיעבד אינו פוסל. \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003רב ור' יוחנן דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003בוגרת ומוכת עץ לא ישא\u0004 כהן גדול, \u0003ו\u0004אולם \u0003אם נשא — נשוי.\u0004","ודוחים: \u0003הכי השתא\u0004 \u0005[כך עכשיו,\u0006 כיצד אתה משווה\u0005]?!\u0006 \u0003בשלמא התם\u0004 \u0005[נניח שם]\u0006 בבוגרת יש טעם להתירה בדיעבד מפני הנימוק כי \u0003סופה להיות בוגרת תחתיו, סופה להיות בעולה תחתיו,\u0004 ולכן, אם עבר ונשאה — איננו מקפידים בכך, אבל \u0003הכא\u0004 \u0005[כאן]\u0006 וכי \u0003סופה להיות זונה תחתיו?!\u0004 אלא אפשר היה באמת להסיק מכאן שזו דעת ר' יהושע בן לוי.","ומעירים: אכן \u0003רב ספרא מתני לה מכללא\u0004 \u0005[\u0006היה \u0005שונה\u0006 את ההלכה \u0005הזו מכלל\u0006 הדברים\u0005],\u0006 שלא קיבל אותה במפורש כהלכה פסוקה, אלא למד אותה מאותו מעשה, \u0003וקשיא ליה\u0004 \u0005[ו\u0006היה \u0005קשה לו]\u0006 כפי שהקשינו: שמא יש לחלק ביניהם שהואיל ונישאה נישאה, \u0003ומשני ליה הכי\u0004 \u0005[ו\u0006היה \u0005מתרץ\u0006 את הדבר \u0005כך]\u0006 כפי שתירצנו.","ולענין הלכה למעשה מספרים: \u0003ההוא כהנא דאנסיב\u0004 \u0005[כהן אחד שנשא]\u0006 \u0003גיורת\u0004 שהתגיירה כאשר היתה \u0003פחותה מבת שלש שנים ויום אחד. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר יצחק: מאי האי\u0004 \u0005[מה זה]\u0006 שאתה עושה שלא כדין? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ש\u0003אמר ר' יעקב בר אידי אמר ר' יהושע בן לוי: הלכה כר' שמעון בן יוחאי\u0004 המכשיר אותה לכהונה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל אפיק\u0004 \u0005[לך, הוצא,\u0006 גרש אותה\u0005]\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 תגרשנה — \u0003מפיקנא לך\u0004 \u0005[אוציא לך]\u0006 את \u0003ר' יעקב בר אידי מאוניך\u0004 \u0005[מאוזניך],\u0006 כלומר, אנקוט כנגדך אמצעים חמורים עד שתציית ותגרש אותה ולא תוכל לסבור כר' יעקב בר אידי.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003וכן היה ר' שמעון בן יוחאי אומר:\u0004"],["\u0003קברי גויים אינן מטמאין ב\u0004טומאת \u0003אהל, שנאמר: \"ואתן צאני צאן מרעיתי אדם אתם\"\u0004 (יחזקאל לד, לא), ומכאן למד: \u0003אתם קרויין \"אדם\" ואין הגויים קרויין \"אדם\".\u0004 וכיון שבטומאת אוהל נאמר \"אדם כי ימות באהל\" (במדבר יט, יד) — הרי דין זה חל רק על ישראל, ולא על גויים.","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 והרי נאמר בשבויי מדין \u0003\"ונפש אדם ששה עשר אלף\"\u0004 (שם לא, מ), הרי שגם גויים קרויים \"אדם\"! משיבים: \u0003משום בהמה,\u0004 שהרי נמנו שם גם בהמות השלל, וכדי להבחין בין סוגי השלל, נאמר שאלה הם אדם ואלה בהמה.","ומקשים עוד, הרי נאמר בנינוה: \u0003\"אשר יש בה הרבה משתים עשרה רבו אדם אשר לא ידע בין ימינו לשמאלו ובהמה רבה\"\u0004 (יונה ד, יא)! ומשיבים: גם שם נאמר \"אדם\" \u0003משום בהמה.\u0004","ומקשים: הלא במלחמת מדין נאמר \u0003\"כל הרג נפש וכל נגע בחלל תתחטאו\"\u0004 (במדבר לא, יט), משמע שאף הגויים מטמאים! ומשיבים: \u0003דלמא איקטיל חד\u0004 \u0005[שמא נהרג אחד]\u0006 \u0003מישראל\u0004 ונטמאו לו. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 המטמאים את קברי הגוים, הם משיבים על כך: הלא נאמר \u0003\"לא נפקד ממנו איש\"\u0004 (שם מט), כלומר, אף אחד מאיתנו לא נפל במלחמה, ואם כן כל המטמאים מן ההכרח שהיו גויים. \u0003ור' שמעון בן יוחי\u0004 מפרש: \u0003\"\u0004ו\u0003לא נפקד ממנו איש\"\u0004 — כוונתו \u0003לעבירה,\u0004 שאף איש לא חטא.","\u0003רבינא אמר:\u0004 אין צורך בהסבר זה, \u0003נהי דמעטינהו קרא מאטמויי\u0004 \u0005[אמנם מיעטם הכתוב,\u0006 את הגויים, \u0005מלטמא]\u0006 \u0003באהל, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אדם כי ימות באהל\"\u0004 (שם יט, יד), אולם \u0003מ\u0004טומאת \u0003מגע ומשא מי מעטינהו קרא\u0004 \u0005[האם מיעטם הכתוב]\u0006 שלא יטמאו? וכיון שמטמאים הגויים בטומאת מת במגע ומשא, נטמאו גם האנשים שבאו ממלחמת מדין.","כהן הדיוט ש\u0003אירס את האלמנה, ו\u0004לאחר מכן \u0003נתמנה להיות כהן גדול — יכנוס\u0004 (ישא) אותה. \u0003ומעשה ביהושע בן גמלא שקדש את מרתא בת ביתוס\u0004 שהיתה אלמנה, \u0003ומנהו המלך להיות כהן גדול, ו\u0004אחר כך \u0003כנסה.\u0004 לעומת זאת, \u0003שומרת יבם שנפלה לפני כהן הדיוט, ונתמנה להיות כהן גדול, אף על פי שעשה בה מאמר\u0004 בהיותו הדיוט — \u0003הרי זה לא יכנוס,\u0004 שהרי כהן גדול אסור באלמנה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין שאם אירס את האלמנה ונתמנה להיות כהן גדול שיכנוס — תלמוד לומר: \"יקח אשה\"\u0004 (ויקרא כא, יד), שבא הכתוב לרבות, שלמרות האיסור הנאמר שם, בכל זאת יכול לקחתה לאשה. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שיש ריבוי כזה, \u0003שומרת יבם\u0004 אף שהיא אלמנה, כיון שנפלה לפניו ליבום לפני שנתמנה להיות כהן גדול \u0003נמי\u0004 \u0005[גם כן]\u0006 יכנוס! ומשיבים: נאמר בכהן גדול \u0003\"\u0004יקח \u0003אשה\" ולא יבמה,\u0004 שהיא מתחילה אינה אשה שלו אלא אשת אחיו.","מסופר במשנה \u0003מעשה ביהושע\u0004 בן גמלא שאחר שקידש את האלמנה מינהו המלך להיות כהן גדול וכנסה. ומעירים על דיוק הלשון: \u0003מנהו\u0004 המלך לבדו — \u0003אין\u0004 \u0005[כן],\u0006 אבל אם \u0003נתמנה\u0004 גם על ידי אחיו הכהנים והסנהדרין — \u0003לא\u0004 נאמר שיכול לכונסה. \u0003אמר רב יוסף: קטיר קחזינא הכא\u0004 \u0005[קשר אני רואה כאן],\u0006 כלומר, לא היה זה מינוי שנעשה כראוי על ידי הכהנים והסנהדרין, אלא מטעם השלטונות. ש\u0003אמר רב אסי: תרקבא דדינרי עיילה ליה\u0004 \u0005[תרקב,\u0006 כלי מלא \u0005דינרים הכניסה לו]\u0006 \u0003מרתא בת ביתוס לינאי מלכא\u0004 \u0005[המלך]\u0006 \u0003עד דמוקי ליה\u0004 \u0005[שהעמיד,\u0006 מינה \u0005אותו],\u0006 את \u0003יהושע בן גמלא בכהני רברבי\u0004 \u0005[לכהן גדול],\u0006 משמע שבגלל שוחד הממון מינהו המלך, ולא משום שהחליטו הכהנים למנותו עליהם.","\u0003כהן גדול שמת אחיו\u0004 בלא בנים \u0003חולץ ולא מייבם,\u0004 שהרי אלמנה היא ואסור באלמנה.","ומעירים: \u0003קא פסיק ותני\u0004 \u0005[פסק ושנה]\u0006 הלכה זו בלי שפירט, ללמדנו כי \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם היתה אלמנת אחיו \u0003מן האירוסין, ולא שנא\u0004 \u0005[ואינו שונה]\u0006 כשהיתה אלמנה \u0003מן הנשואין.\u0004 ומעתה נברר: \u0003בשלמא\u0004 \u0005[נניח]\u0006 אם היתה אלמנה \u0003מן הנשואין\u0004 אסור בה משום מצות \u0003עשה\u0004 של \"בתולה מעמיו יקח\", \u0003ו\u0004גם משום מצות \u0003לא תעשה\u0004 של \"אלמנה לא יקח\" \u0003הוא, ו\u0004כלל ההוא ש\u0003אין עשה\u0004 של ייבום \u0003דוחה\u0004 את \u0003לא תעשה ועשה. אלא\u0004 אם היתה אלמנה \u0003מן האירוסין,\u0004 מדוע לא \u0003יבא עשה\u0004 של ייבום, \u0003וידחה את לא תעשה\u0004 של אלמנה, שהרי היא עדיין בתולה?!","ומשיבים: באמת היה ראוי שידחה, אלא גזרו \u0003גזירה\u0004 אף באלמנה מן האירוסין ב\u0003ביאה ראשונה\u0004 שבא עליה, שהיא אכן מצות עשה, \u0003אטו\u0004 \u0005[משום]\u0006 \u0003ביאה שניה.\u0004 כי לאחר ביאה ראשונה הרי היא כבר כאשתו לכל דבר ופקעה מצות ייבום, ואם כן, בביאה שניה אין מצות עשה שתדחה את לא תעשה.","\u0003כהן הדיוט לא ישא אילונית,\u0004 כלומר, אשה שאיננה מסוגלת, מחמת מבנה גופה וטבעה, ללדת, שהרי הוא מצווה על הפריה ורביה כשאר ישראל, \u0003אלא אם כן יש לו אשה ובנים\u0004 קודם לכן וכבר קיים את המצוה. \u0003ר' יהודה אומר: אף על פי שיש לו אשה ובנים לא ישא אילונית, שהיא זונה האמורה בתורה.\u0004 שכיון שאיננה מסוגלת לפריה ורביה כלל, הרי בעילתה נחשבת כזנות. \u0003וחכמים אומרים: אין זונה\u0004 האסורה לכהן \u0003אלא גיורת, ו\u0004כן שפחה \u0003משוחררת, ו\u0004כל אשה \u0003שנבעלה בעילת זנות,\u0004 כלומר, למי שהיה אסור עליה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ריש גלותא\u0004 \u0005[ראש הגולה]\u0006 \u0003לרב הונא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של המשנה שכהן לא ישא איילונית — \u0003משום\u0004 שהוא חייב לקיים מצות \u0003פריה ורביה,\u0004 אולם וכי על מצות \u0003פריה ורביה כהנים הוא דמפקדי\u0004 \u0005[שנצטוו]\u0006 \u0003וישראל לא מפקדי\u0004 \u0005[נצטוו]?!\u0006 ומדוע אם כן אמרו איסור זה דווקא בכהן? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: באמת דין זה הוא כללי, אלא \u0003משום דקא בעי למיתני סיפא\u0004 \u0005[שרצה לשנות\u0006 את \u0005סופה]\u0006 של משנתנו, \u0003ר' יהודה אומר: אף על פי שיש לו אשה\u0004"],["\u0003ויש לו בנים לא ישא אילונית, שהיא זונה האמורה בתורה.\u0004 שעל ה\u0003זונה כהנים הוא דמפקדי\u0004 \u0005[שנצטוו]\u0006 \u0003ו\u0004אילו \u0003ישראל לא מפקדי\u0004 \u0005[נצטוו],\u0006 \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003קתני\u0004 \u0005[שנה]\u0006 דין זה בראש המשנה העוסקת ב\u0003כהן,\u0004 ואולם באמת גם ישראל אסור באיילונית מטעם זה.","\u0003אמר רב הונא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ו\u0003אכלו ולא ישבעו הזנו ולא יפרצו\"\u0004 (הושע ד, י), והוא מדייק מן הכתוב ומפרש: \u0003כל ביאה שאין בה פירצה,\u0004 כלומר, שאין בה תוספת, פריה ורביה — \u0003אינה אלא בעילת זנות.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: כהן לא ישא את הקטנה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לרבה: פוק\u0004 \u0005[צא]\u0006 \u0003עיין בה\u0004 בהלכה זו, כיון \u0003דלאורתא בעי לה\u0004 \u0005[שבערב ישאל אותך]\u0006 \u0003רב הונא מינך\u0004 \u0005[ממך]\u0006 את טעם הדבר. \u0003נפק\u0004 \u0005[יצא]\u0006 \u0003עיין בה\u0004 והגיע למסקנה זו: \u0003ר' אליעזר סבר לה\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' מאיר, וסבר לה\u0004 \u0005[וסבור\u0006 הוא\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' יהודה.\u0004","כיצד: \u0003סבר לה\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' מאיר דחייש למיעוטא\u0004 \u0005[שחושש למיעוט]\u0006 ואינו סומך על הרוב, ולכן אף שהאיילוניות הן מיעוט, מכל מקום בכל קטנה יש חשש שמא היא מן המיעוט ואיילונית היא. \u0003וסבר לה\u0004 \u0005[וסבור\u0006 הוא\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' יהודה,\u0004 ש\u0003אמר: אילונית זונה הויא\u0004 \u0005[היא].\u0006","ושואלים: \u0003וכ\u0004שיטת \u0003ר' מאיר מי סבר לה\u0004 \u0005[האם סבור\u0006 הוא\u0005]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003קטן וקטנה לא חולצין ולא מיבמין,\u0004 אלו \u0003דברי ר' מאיר. אמרו לו לר' מאיר: יפה אמרת שאין חולצין,\u0004 משום ש\u0003\"איש\" כתיב\u0004 \u0005[נאמר]\u0006 \u0003בפרשה\u0004 של חליצה (דברים כה, ז. ושם ט), ו\"איש\" פירושו גדול, \u0003ומקשינן\u0004 \u0005[ומקישים,\u0006 משווים \u0005אנו]\u0006 \u0003אשה\u0004 הנחלצת \u0003לאיש\u0004 כפי המפורש שם שהכוונה לגדול. \u0003אלא מאי טעמא\u0004 \u0005[מה הטעם]\u0006 \u0003אין מיבמין?\u0004","\u0003אמר להם: קטן\u0004 — \u0003שמא ימצא סריס,\u0004 שאיננו יכול להקים זרע לאחיו, ואין בו מצות ייבום, ו\u0003קטנה — שמא תמצא אילונית,\u0004 שאף בה אין מצות ייבום, \u0003ונמצאו פוגעין בערוה\u0004 לפי שהיתה זו ביאה אסורה שלא הותרה מפני המצוה. \u0003ותניא\u0004 \u0005[ושנינו\u0006 בברייתא אחרת\u0005]:\u0006 \u0003קטנה — מתייבמת ואינה חולצת,\u0004 אלו \u0003דברי ר' אליעזר,\u0004 ומשמע שאין ר' אליעזר חושש למיעוט.","ועוד: \u0003וכ\u0004שיטת \u0003ר' יהודה מי סבר לה\u0004 \u0005[האם סבור\u0006 הוא\u0005]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"זונה\"\u0004 האמורה באיסורי כהונה — \u0003זונה\u0004 היא \u0003כשמה,\u0004 כלומר, אשת איש שזינתה תחת בעלה, אלו \u0003דברי ר' אליעזר. ר' עקיבא אומר: \"זונה\" זו\u0004 אשה \u0003מופקרת\u0004 לכל, ואפילו היא פנויה, אבל אשה שנבעלה פעם אחת איננה נעשית משום כך זונה. \u0003ר' מתיא בן חרש אומר: אפילו\u0004 שקינא לה בעלה ונסתרה ו\u0003הלך בעלה\u0004 לבית הדין כדי \u0003להשקותה\u0004 מים המרים, \u0003ובא עליה בדרך — עשאה זונה,\u0004 אף שהוא בעלה, משום שהיתה אסורה עליו באותה שעה.","\u0003ר' יהודה אומר: זונה — זו אילונית. וחכמים אומרים: אין זונה אלא גיורת, ומשוחררת, ושנבעלה בעילת זנות. ר' אלעזר אומר:\u0004 אפילו \u0003פנוי הבא על פנויה שלא לשם אישות\u0004 אלא לשם הנאתו — \u0003עשאה\u0004 על ידי כך \u0003זונה.\u0004 ומכל מקום ברור מכאן שר' אליעזר איננו סבור כר' יהודה.","\u0003אלא אמר רב אדא בר אהבה:\u0004 את ההלכה של ר' אליעזר שאסור לכהן לשאת קטנה, יש להסביר בדרך אחרת: \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בכהן גדול עסקינן\u0004 \u0005[עוסקים אנו],\u0006 והטעם שקטנה אסורה לו, הוא, כי \u0003לאימת קני לה\u0004 \u0005[למתי יקנה אותה]\u0006 לו לאשה — רק \u0003לכי גדלה\u0004 \u0005[לכאשר תגדל],\u0006 שהרי קנין הקטנה אינו נחשב, ומשגדלה הרי אז \u0003בעולה היא\u0004 כבר, והרי כהן גדול מצווה על הבתולה.","\u0003אמר רבא:\u0004 דברים אלה שאתה אומר הם \u0003מכלי לב\u0004 (חסרי לב, חסרי טעם) כי, \u0003אי דקדשה אבוה\u0004 \u0005[אם שקידש אותה אביה]\u0006 גם כן \u0003מההיא שעתא\u0004 \u0005[מאותה שעה]\u0006 של הקידושין \u0003הוא דקני לה\u0004 \u0005[שקנה אותה],\u0006 שקידושין על ידי האב בבתו הקטנה קונים קנין גמור מדברי תורה, \u0003ואי דקדשה נפשה\u0004 \u0005[ואם שקידשה\u0006 הקטנה \u0005את עצמה],\u0006 וכי \u0003הא\u0004 \u0005[זו]\u0006 שיטת \u0003ר' אליעזר היא ולא\u0004 שיטת \u0003רבנן\u0004 \u0005[חכמים]?\u0006 והרי במקרה זה ודאי גם חכמים יודו שאינו רשאי לשאת קטנה שקידשה את עצמה.","\u0003אלא אמר רבא: לעולם\u0004 יש לפרש את דברי ר' אליעזר גם \u0003בכהן הדיוט,\u0004 וטעם האיסור — כי \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא תתפתה עליו,\u0004 שאם נושא אשה קטנה יש לחשוש שמא היא תתפתה על ידי אחר. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 ב\u0003ישראל נמי\u0004 \u0005[גם כן]\u0006 יש להם לחשוש לכך! ומשיבים: \u0003פתויי קטנה\u0004 איננו נחשב כפיתוי, אלא כמו \u0003אונס הוא. ואונס בישראל מישרא שרי\u0004 \u0005[מותר],\u0006 אבל בכהן, שגם אם נאנסה אשתו היא אסורה לו, אל לו להכניס עצמו לספק זה.","\u0003רב פפא אמר:\u0004 כאן מדובר \u0003בכהן גדול, ו\u0004שיטת \u0003האי תנא\u0004 \u0005[תנא זה]\u0006 \u0003הוא — דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \"בתולה מעמיו יקח אשה\u0003\"\u0004 (ויקרא כא, יד), \u0003\"בתולה\",\u0004 ונברר: \u0003יכול\u0004 דווקא \u0003קטנה\u0004 — \u0003תלמוד לומר: \"אשה\",\u0004 משמע גדולה, \u0003אי\u0004 \u0005[אם]\u0006 מה שנאמר \u0003\"אשה\", יכול\u0004 הכוונה דווקא ל\u0003בוגרת — תלמוד לומר: \"בתולה\",\u0004 והבוגרת אינה נחשבת כבתולה שלימה (ראה לעיל יבמות נט, א). \u0003הא כיצד,\u0004 את מי ישא? ישא את זו ש\u0003יצתה\u0004 (יצאה) \u0003מכלל קטנות ולכלל בגרות\u0004 עדיין \u0003לא באתה\u0004 \u0005[הגיעה],\u0006 כלומר, נערה.","\u0003רב נחמן בר יצחק אמר:\u0004 שיטת \u0003האי תנא\u0004 \u0005[תנא זה]\u0006 \u0003הוא — דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \u0003\"בתולה\",\u0004 ו\u0003אין \"בתולה\" אלא נערה. וכן הוא אומר\u0004 כרמז לדבר: \u0003\"והנער טבת מראה מאד בתולה\u0004 ואיש לא ידעה\u0003\"\u0004 (בראשית כד, טז).","שנינו באותה ברייתא ש\u0003ר' אלעזר אומר: פנוי הבא על\u0004 ה\u0003פנויה שלא לשם אישות — עשאה זונה. אמר רב עמרם: אין הלכה כר' אלעזר.\u0004","\u0003לא יבטל אדם מפריה ורביה אלא אם כן יש לו\u0004 כבר \u0003בנים.\u0004 ובכמה ילדים יוצא ידי חובה? \u0003בית שמאי אומרים: שני זכרים, ובית הלל אומרים: זכר ונקבה, שנאמר: \"זכר ונקבה בראם\"\u0004 (שם ה, ב).","מדברי המשנה מדייקים: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003יש לו\u0004 כבר \u0003בנים — מפריה ורביה בטיל\u0004 \u0005[\u0006רשאי הוא \u0005להתבטל],\u0006 אבל \u0003מאשה לא בטיל\u0004 \u0005[איננו בטל]\u0006 וצריך לשאת אשה, אלא שאינו צריך להקפיד שתהא מסוגלת ללדת. \u0003מסייעא ליה\u0004 \u0005[מסייע לו]\u0006 הדבר \u0003ל\u0004שיטת \u0003רב נחמן\u0004 ש\u0003אמר\u0004 בשם \u0003שמואל.\u0004 ש\u0003אמר: אף על פי שיש לו לאדם כמה בנים — אסור לעמוד בלא אשה, שנאמר: \"לא טוב היות\u0004 ה\u0003אדם לבדו\"\u0004 (שם ב, יח).","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 בנוסח אחר את הדיוק מהמשנה: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003יש לו בנים — בטיל\u0004 \u0005[בטל]\u0006 \u0003מפריה ורביה, ובטיל נמי\u0004 \u0005[ובטל גם כן]\u0006 \u0003מאשה, נימא תיהוי תיובתא\u0004 \u0005[\u0006האם \u0005נאמר שתהא קושיה]\u0006 מכאן על דברי \u0003רב נחמן אמר שמואל!\u0004 ודוחים: \u0003לא,\u0004 הכוונה היא: אם \u0003אין לו בנים — נושא אשה בת בנים\u0004 (אשה המסוגלת ללדת בנים), ואם \u0003יש לו בנים — נושא אשה דלאו\u0004 \u0005[שאינה]\u0006 דווקא \u0003בת בנים. נפקא מינה\u0004 \u0005[יוצא מזה]\u0006 הלכה למעשה, אם חייב או אינו חייב לשאת אשה בת בנים לענין \u0003למכור ספר תורה,\u0004 שאם אין לו בנים ונזקק לכסף כדי לשאת אשה צעירה המסוגלת ללדת בנים, יכול למכור ספר תורה לשם כך \u0003בשביל בנים,\u0004 אולם אם יש לו כבר בנים, אסור לו למכור, אלא ישא עקרה או זקנה.","שנינו במשנה ש\u0003בית שמאי אומרים:\u0004 קיום מצות פריה ורביה הוא ב\u0003שני זכרים.\u0004 ושואלים: \u0003מאי טעמייהו\u0004 \u0005[מה\u0006 \u0005טעמם]\u0006 של \u0003בית שמאי?\u0004 ומשיבים: \u0003ילפינן\u0004 \u0005[למדים אנו]\u0006 \u0003ממשה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בני משה גרשום ואליעזר\"\u0004 (דברי הימים א' כג, טו), ומשנולדו לו אלה פרש מאשתו, משמע שבזה יצא ידי חובה. \u0003ובית הלל\u0004 אומרים: \u0003ילפינן\u0004 \u0005[למדים אנו]\u0006 \u0003מברייתו של עולם\u0004 שנבראו זכר ונקיבה. ושואלים: \u0003ובית שמאי לילפי\u0004 \u0005[שילמדו]\u0006 גם הם \u0003מברייתו של עולם?\u0004 ומשיבים: לדעתם \u0003אין דנין אפשר\u0004"]]};
